// The sea ports — what their people say, what their things are, their signs, quests, packet boats and update. One row per English text, its translations in TABLE_LANGUAGES' order (see table.ts).
import type { Row } from "./table.ts";

export const PORTS_TALK: Readonly<Record<string, Row>> = {
  "A chart of the bay, the rocks off Wrack Point inked in red, twice": ["湾の海図。レック岬沖の岩礁が赤で二重に描かれている", "만의 해도. 렉 곶 앞바다의 암초가 붉은 잉크로 두 번 그려져 있다", "海湾的海图,残骸岬外的礁石用红墨描了两遍", "海灣的海圖,殘骸岬外的礁石用紅墨描了兩遍", "Hải đồ vịnh, đá ngầm ngoài mũi Wrack được tô đỏ hai lần", "Peta teluk, karang di lepas Tanjung Wrack ditandai merah, dua kali", "แผนที่อ่าว โขดหินนอกแหลมแร็กถูกลงหมึกแดงสองรอบ", "Körfezin haritası; Wrack Burnu açığındaki kayalar kırmızıyla, iki kez çizilmiş", "Una carta de la bahía, con las rocas de la Punta Wrack marcadas en rojo, dos veces", "Uma carta da baía, com as rochas da Ponta Wrack marcadas em vermelho, duas vezes", "Карта бухты, скалы у мыса Рэк обведены красным, дважды", "Мапа затоки, скелі біля мису Рек обведено червоним, двічі"],
  "Tide tables, berth books, and a brass telescope with a crack in the lens": ["潮汐表、停泊簿、そしてレンズにひびの入った真鍮の望遠鏡", "조수표, 정박 장부, 렌즈에 금이 간 놋쇠 망원경", "潮汐表、泊位簿,还有一架镜片裂了的黄铜望远镜", "潮汐表、泊位簿,還有一架鏡片裂了的黃銅望遠鏡", "Bảng thủy triều, sổ bến, và một ống nhòm đồng có vết nứt trên thấu kính", "Tabel pasang surut, buku tambatan, dan teropong kuningan dengan lensa retak", "ตารางน้ำขึ้นน้ำลง สมุดท่าจอด และกล้องส่องทางไกลทองเหลืองที่เลนส์ร้าว", "Gelgit çizelgeleri, rıhtım defterleri ve merceği çatlak pirinç bir dürbün", "Tablas de mareas, libros de atraques y un catalejo de latón con la lente rajada", "Tábuas de marés, livros de atracação e uma luneta de latão com a lente rachada", "Таблицы приливов, книги причалов и латунная подзорная труба с трещиной в линзе", "Таблиці припливів, книги причалів і латунна підзорна труба з тріщиною в лінзі"],
  "Ledgers of dues: berth, landing, anchorage, and a new column, headed 'harbour improvement'": ["税の台帳。停泊料、陸揚げ料、投錨料、そして新しい欄「港湾改良」", "세금 장부: 정박료, 양륙료, 정박지료, 그리고 '항만 개량'이라는 새 칸", "税账:泊位费、卸货费、锚地费,还有新添的一栏,标题是“港口改良”", "稅帳:泊位費、卸貨費、錨地費,還有新添的一欄,標題是「港口改良」", "Sổ thuế: phí bến, phí bốc dỡ, phí neo đậu, và một cột mới đề 'cải tạo cảng'", "Buku bea: tambat, bongkar, labuh, dan satu kolom baru berjudul 'perbaikan pelabuhan'", "สมุดค่าธรรมเนียม: ค่าท่าจอด ค่าขึ้นฝั่ง ค่าทอดสมอ และคอลัมน์ใหม่ชื่อ 'ปรับปรุงท่าเรือ'", "Vergi defterleri: rıhtım, boşaltma, demirleme ve 'liman iyileştirmesi' başlıklı yeni bir sütun", "Libros de derechos: atraque, desembarco, fondeo y una columna nueva titulada «mejora del puerto»", "Livros de taxas: atracação, desembarque, ancoragem e uma coluna nova intitulada «melhoria do porto»", "Книги сборов: причальный, выгрузной, якорный и новая графа «благоустройство гавани»", "Книги зборів: причальний, вивантажувальний, якірний і нова графа «упорядкування гавані»"],
  "DUES OF THE PORT OF GULLWICK, by order of the Collector. Berth: by the foot of keel. Landing: by the basket. Anchorage: by the night. Harbour improvement: by the boat, whether it is improved or not. Paid at the Customs House before the catch is sold.": ["ガルウィック港の諸税、徴税官の命による。停泊料:竜骨の尺ごと。陸揚げ料:籠ごと。投錨料:一夜ごと。港湾改良:船ごと、改良されたか否かを問わず。漁獲を売る前に税関にて納めること。", "걸윅 항구의 세금, 징수관의 명에 따라. 정박료: 용골 한 자마다. 양륙료: 바구니마다. 정박지료: 하룻밤마다. 항만 개량: 배마다, 개량이 되었든 아니든. 어획물을 팔기 전에 세관에서 낼 것.", "鸥湾港税费,奉税务官之命。泊位费:按龙骨尺数。卸货费:按篮。锚地费:按夜。港口改良费:按船,不论船是否改良。须在出售渔获前于海关楼缴纳。", "鷗灣港稅費,奉稅務官之命。泊位費:按龍骨尺數。卸貨費:按籃。錨地費:按夜。港口改良費:按船,不論船是否改良。須在出售漁獲前於海關樓繳納。", "THUẾ CẢNG GULLWICK, theo lệnh Quan thu thuế. Phí bến: theo từng bộ chiều dài sống thuyền. Phí bốc dỡ: theo giỏ. Phí neo đậu: theo đêm. Cải tạo cảng: theo thuyền, dù thuyền có được cải tạo hay không. Nộp tại Nhà Hải quan trước khi bán mẻ cá.", "BEA PELABUHAN GULLWICK, atas perintah Pemungut. Tambat: per kaki lunas. Bongkar: per keranjang. Labuh: per malam. Perbaikan pelabuhan: per perahu, entah diperbaiki atau tidak. Dibayar di Kantor Bea Cukai sebelum tangkapan dijual.", "ค่าธรรมเนียมท่าเรือกัลวิก ตามคำสั่งของเจ้าพนักงานเก็บภาษี ค่าท่าจอด: ตามความยาวกระดูกงูเป็นฟุต ค่าขึ้นฝั่ง: ตามตะกร้า ค่าทอดสมอ: ตามคืน ค่าปรับปรุงท่าเรือ: ตามลำ ไม่ว่าจะได้ปรับปรุงหรือไม่ ชำระที่ศุลกสถานก่อนขายปลาที่จับได้", "GULLWICK LİMANI VERGİLERİ, Tahsildar'ın emriyle. Rıhtım: omurga ayağı başına. Boşaltma: sepet başına. Demirleme: gece başına. Liman iyileştirmesi: tekne başına, iyileştirilsin ya da iyileştirilmesin. Av satılmadan önce Gümrük Binası'nda ödenir.", "DERECHOS DEL PUERTO DE GULLWICK, por orden del Recaudador. Atraque: por pie de quilla. Desembarco: por cesta. Fondeo: por noche. Mejora del puerto: por barca, se mejore o no. Se pagan en la Aduana antes de vender la pesca.", "TAXAS DO PORTO DE GULLWICK, por ordem do Coletor. Atracação: por pé de quilha. Desembarque: por cesto. Ancoragem: por noite. Melhoria do porto: por barco, seja melhorado ou não. Pagas na Alfândega antes de vender o pescado.", "СБОРЫ ГАВАНИ ГАЛЛВИКА, по распоряжению сборщика. Причальный: по футу киля. Выгрузной: по корзине. Якорный: за ночь. Благоустройство гавани: с лодки, благоустроена она или нет. Уплачиваются в таможне до продажи улова.", "ЗБОРИ ГАВАНІ ГАЛЛВІКА, за розпорядженням збирача. Причальний: за фут кіля. Вивантажувальний: за кошик. Якірний: за ніч. Упорядкування гавані: з човна, упорядкований він чи ні. Сплачуються в митниці до продажу улову."],
  "Rope, tar, lamp oil, hooks, floats, and a box of compasses that all agree": ["縄、タール、灯油、釣り針、浮き、そして全部が同じ方角を指す羅針盤の箱", "밧줄, 타르, 등잔 기름, 낚싯바늘, 부표, 그리고 모두 같은 방향을 가리키는 나침반 한 상자", "绳子、沥青、灯油、鱼钩、浮子,还有一箱指向全都一致的罗盘", "繩子、瀝青、燈油、魚鉤、浮子,還有一箱指向全都一致的羅盤", "Dây thừng, nhựa đường, dầu đèn, lưỡi câu, phao, và một hộp la bàn chỉ cùng một hướng", "Tali, ter, minyak lampu, kail, pelampung, dan sekotak kompas yang semuanya sepakat", "เชือก น้ำมันดิน น้ำมันตะเกียง เบ็ด ทุ่น และกล่องเข็มทิศที่ชี้ตรงกันทุกอัน", "İp, katran, kandil yağı, olta iğneleri, şamandıralar ve hepsi aynı yönü gösteren bir kutu pusula", "Cuerda, brea, aceite de lámpara, anzuelos, flotadores y una caja de brújulas que coinciden todas", "Corda, piche, óleo de lamparina, anzóis, boias e uma caixa de bússolas que concordam todas", "Верёвка, дёготь, масло для ламп, крючки, поплавки и коробка компасов, которые все согласны друг с другом", "Мотузка, дьоготь, олія для ламп, гачки, поплавці й коробка компасів, що всі погоджуються між собою"],
  "Ganseys folded by family pattern, oilskins hung by the shoulders like drowned men": ["家ごとの模様でたたまれたガンジー、溺れた男のように肩で吊るされた油布服", "집안 무늬별로 갠 건지 스웨터, 물에 빠진 사람처럼 어깨로 걸린 방수복", "按家族花纹叠好的渔夫毛衣,还有像溺死者一样挂着肩的油布衣", "按家族花紋疊好的漁夫毛衣,還有像溺死者一樣掛著肩的油布衣", "Áo len gansey gấp theo hoa văn từng nhà, áo dầu treo vai như người chết đuối", "Sweter gansey dilipat menurut pola keluarga, jas minyak digantung di bahu seperti orang tenggelam", "เสื้อแกนซีพับแยกตามลายของแต่ละตระกูล เสื้อกันน้ำแขวนที่ไหล่เหมือนคนจมน้ำ", "Aile desenine göre katlanmış ganseyler, boğulmuş adamlar gibi omuzlarından asılı muşambalar", "Ganseys doblados por el dibujo de cada familia, impermeables colgados por los hombros como ahogados", "Ganseys dobrados pelo padrão de cada família, oleados pendurados pelos ombros como afogados", "Гернси, сложенные по семейным узорам, и непромокаемые плащи, подвешенные за плечи, как утопленники", "Гернсі, складені за родинними візерунками, і непромокальні плащі, підвішені за плечі, як утопленики"],
  "A kettle, a clock that stopped at high tide and was left that way, and a gansey half knitted": ["やかん、満潮時に止まってそのままにされた時計、編みかけのガンジー", "주전자, 만조 때 멈추고 그대로 둔 시계, 반쯤 뜬 건지 스웨터", "一把水壶,一座在涨潮时停下就再没动过的钟,还有一件织了一半的渔夫毛衣", "一把水壺,一座在漲潮時停下就再沒動過的鐘,還有一件織了一半的漁夫毛衣", "Một ấm nước, một chiếc đồng hồ dừng lúc triều cường và được để nguyên thế, và một áo gansey đan dở", "Sebuah ketel, jam yang berhenti saat pasang naik dan dibiarkan begitu, dan sweter gansey setengah dirajut", "กาน้ำ นาฬิกาที่หยุดตอนน้ำขึ้นสูงสุดแล้วก็ปล่อยไว้อย่างนั้น และเสื้อแกนซีที่ถักได้ครึ่งตัว", "Bir çaydanlık, gelgitin en yükseğinde durup öyle bırakılmış bir saat ve yarısı örülmüş bir gansey", "Una tetera, un reloj que se paró con la pleamar y se dejó así, y un gansey a medio tejer", "Uma chaleira, um relógio que parou na preia-mar e ficou assim, e um gansey tricotado pela metade", "Чайник, часы, остановившиеся в прилив и так и оставленные, и недовязанный гернси", "Чайник, годинник, що зупинився в приплив і так і лишився, та недов'язаний гернсі"],
  "Nets hung from the rafters to dry, every one mended a hundred times": ["垂木から吊るして干した網。どれも百回は繕われている", "서까래에 걸어 말리는 그물들. 하나같이 백 번은 기웠다", "挂在椽子上晾的渔网,每张都补过上百次", "掛在椽子上晾的漁網,每張都補過上百次", "Lưới treo trên xà cho khô, tấm nào cũng vá cả trăm lần", "Jala digantung di kasau agar kering, masing-masing sudah ditambal seratus kali", "อวนแขวนตากจากขื่อ ทุกผืนปะซ่อมมาแล้วนับร้อยครั้ง", "Kirişlerden kurumaya asılmış ağlar, her biri yüz kez yamanmış", "Redes colgadas de las vigas para secar, cada una remendada cien veces", "Redes penduradas nas vigas para secar, cada uma remendada cem vezes", "Сети, развешанные на стропилах для просушки, каждая чинена сто раз", "Сіті, розвішені на кроквах для просушування, кожна латана сто разів"],
  "Her husband's gansey, folded, and a lantern with the glass taken out": ["たたまれた夫のガンジーと、ガラスを外したランタン", "곱게 갠 남편의 건지 스웨터와 유리를 빼낸 등불", "她丈夫叠好的渔夫毛衣,还有一盏拆掉了玻璃的灯笼", "她丈夫疊好的漁夫毛衣,還有一盞拆掉了玻璃的燈籠", "Áo gansey của chồng bà, đã gấp, và một chiếc đèn lồng bị tháo kính", "Sweter gansey suaminya, terlipat, dan lentera yang kacanya dilepas", "เสื้อแกนซีของสามีเธอ พับไว้ และตะเกียงที่ถอดกระจกออก", "Kocasının katlanmış ganseyi ve camı çıkarılmış bir fener", "El gansey de su marido, doblado, y un farol sin el cristal", "O gansey do marido, dobrado, e uma lanterna sem o vidro", "Сложенный гернси её мужа и фонарь с вынутым стеклом", "Складений гернсі її чоловіка й ліхтар із вийнятим склом"],
  "GULLWICK, the harbour of the Thistle Vale. Harbourmaster Wenna Coyle keeps the harbour, the Collector keeps the dues, and Gullwick Light keeps everyone else off the rocks. Packets sail from the quay to every port that pays. Hollyhock is east along the lane.": ["ガルウィック、アザミの谷の港。港は港長ウェナ・コイルが、税は徴税官が預かり、そのほかの皆を岩から遠ざけるのはガルウィック灯台。定期船は岸壁から、払う者のいるあらゆる港へ出る。ホリホックは小道を東へ。", "걸윅, 엉겅퀴 골짜기의 항구. 항구는 항만장 웨나 코일이, 세금은 징수관이 맡고, 나머지 모두를 바위에서 지켜 주는 건 걸윅 등대다. 정기선은 부두에서 돈을 내는 모든 항구로 떠난다. 할리혹은 오솔길 따라 동쪽.", "鸥湾,蓟谷的港口。港务长温娜·科伊尔掌管港口,税务官掌管税费,鸥湾灯塔让其余所有人远离礁石。邮船从码头开往每一个付得起钱的港口。蜀葵村沿小路往东。", "鷗灣,薊谷的港口。港務長溫娜·科伊爾掌管港口,稅務官掌管稅費,鷗灣燈塔讓其餘所有人遠離礁石。郵船從碼頭開往每一個付得起錢的港口。蜀葵村沿小路往東。", "GULLWICK, cảng của Thung lũng Kế. Trưởng cảng Wenna Coyle giữ cảng, Quan thu thuế giữ thuế, còn Đèn biển Gullwick giữ mọi người khác tránh xa đá ngầm. Thuyền chở khách rời bến tới mọi cảng chịu trả tiền. Hollyhock ở phía đông dọc con đường.", "GULLWICK, pelabuhan Lembah Thistle. Syahbandar Wenna Coyle menjaga pelabuhan, Pemungut menjaga bea, dan Mercusuar Gullwick menjaga semua orang lainnya dari karang. Kapal paket berlayar dari dermaga ke setiap pelabuhan yang mau membayar. Hollyhock di timur menyusuri jalan setapak.", "กัลวิก ท่าเรือแห่งหุบเขาทิสเซิล นายท่าเวนนา คอยล์ดูแลท่าเรือ เจ้าพนักงานเก็บภาษีดูแลค่าธรรมเนียม และประภาคารกัลวิกดูแลทุกคนที่เหลือให้พ้นโขดหิน เรือโดยสารออกจากท่าไปทุกเมืองท่าที่จ่ายค่าโดยสาร ฮอลลีฮ็อกอยู่ทางตะวันออกตามทางเดิน", "GULLWICK, Devedikeni Vadisi'nin limanı. Limanı Liman Reisi Wenna Coyle, vergileri Tahsildar tutar; geri kalan herkesi kayalardan uzak tutan Gullwick Feneri'dir. Posta tekneleri rıhtımdan, parasını ödeyen her limana kalkar. Hollyhock patikadan doğuya.", "GULLWICK, el puerto del Valle del Cardo. La capitana de puerto Wenna Coyle guarda el puerto, el Recaudador guarda los derechos, y el faro de Gullwick guarda a todos los demás lejos de las rocas. Los paquebotes salen del muelle hacia todo puerto que pague. Hollyhock está al este por el camino.", "GULLWICK, o porto do Vale do Cardo. A capitã do porto Wenna Coyle cuida do porto, o Coletor cuida das taxas e o farol de Gullwick mantém todos os outros longe das rochas. Os paquetes saem do cais para todo porto que pague. Hollyhock fica a leste pela trilha.", "ГАЛЛВИК, гавань Чертополоховой долины. Гаванью ведает начальница порта Венна Койл, сборами — сборщик, а всех остальных от скал бережёт Галлвикский маяк. Пакетботы ходят от причала в любой порт, который платит. Холлихок — на восток по дорожке.", "ГАЛЛВІК, гавань Будякової долини. Гаванню порядкує начальниця порту Венна Койл, зборами — збирач, а всіх інших від скель береже Галлвіцький маяк. Пакетботи ходять від причалу до будь-якого порту, що платить. Голлігок — на схід стежкою."],
  "The Ledger of Salt, a volume a month, bound in violet: every sack, every pan, every name": ["塩の台帳。月に一冊、紫で装丁されている。袋の一つひとつ、塩田の一つひとつ、名前の一つひとつ", "소금 장부. 한 달에 한 권, 보랏빛 장정. 모든 자루, 모든 염전, 모든 이름", "《盐册》,每月一卷,紫色装帧:每一袋、每一块盐田、每一个名字", "《鹽冊》,每月一卷,紫色裝幀:每一袋、每一塊鹽田、每一個名字", "Sổ Muối, mỗi tháng một quyển, đóng bìa tím: mọi bao, mọi ô ruộng, mọi cái tên", "Buku Garam, satu jilid sebulan, bersampul ungu: setiap karung, setiap petak, setiap nama", "สมุดบัญชีเกลือ เดือนละเล่ม เข้าปกสีม่วง: ทุกกระสอบ ทุกนา ทุกชื่อ", "Tuz Defteri, ayda bir cilt, mor ciltli: her çuval, her havuz, her isim", "El Libro de la Sal, un tomo al mes, encuadernado en violeta: cada saco, cada salina, cada nombre", "O Livro do Sal, um volume por mês, encadernado em violeta: cada saco, cada salina, cada nome", "Книга соли, по тому в месяц, в фиолетовом переплёте: каждый мешок, каждый бассейн, каждое имя", "Книга солі, по тому на місяць, у фіолетовій оправі: кожен мішок, кожен басейн, кожне ім'я"],
  "One book, the same book as next door's, and a salt cellar of white glaze": ["本が一冊、隣の家と同じ本。そして白い釉の塩入れ", "책 한 권, 옆집과 같은 책. 그리고 흰 유약을 바른 소금 그릇", "一本书,和隔壁家那本一模一样,还有一个白釉盐罐", "一本書,和隔壁家那本一模一樣,還有一個白釉鹽罐", "Một cuốn sách, giống hệt cuốn của nhà bên, và một lọ muối men trắng", "Satu buku, sama dengan buku tetangga, dan wadah garam berglasir putih", "หนังสือหนึ่งเล่ม เล่มเดียวกับบ้านข้างๆ และกระปุกเกลือเคลือบขาว", "Bir kitap, yan evdekiyle aynı kitap, ve beyaz sırlı bir tuzluk", "Un libro, el mismo libro que el de al lado, y un salero de esmalte blanco", "Um livro, o mesmo livro da casa ao lado, e um saleiro de esmalte branco", "Одна книга, та же, что у соседей, и солонка белой глазури", "Одна книга, та сама, що в сусідів, і сільничка білої поливи"],
  "Bread of the one kind at the one price, salt herring in barrels, salt in sacks of three sizes": ["一種類一値段のパン、樽詰めの塩ニシン、三つの大きさの袋に入った塩", "한 종류 한 가격의 빵, 통에 든 소금 청어, 세 가지 크기 자루에 든 소금", "只有一种、只卖一个价的面包,一桶桶腌鲱鱼,三种尺寸袋装的盐", "只有一種、只賣一個價的麵包,一桶桶醃鯡魚,三種尺寸袋裝的鹽", "Bánh mì một loại một giá, cá trích muối trong thùng, muối trong bao ba cỡ", "Roti satu jenis satu harga, haring asin dalam tong, garam dalam karung tiga ukuran", "ขนมปังชนิดเดียวราคาเดียว ปลาแฮร์ริ่งเค็มเป็นถัง เกลือในกระสอบสามขนาด", "Tek çeşit, tek fiyat ekmek, fıçılarda tuzlu ringa, üç boy çuvalda tuz", "Pan de una sola clase a un solo precio, arenques salados en barriles, sal en sacos de tres tamaños", "Pão de um só tipo a um só preço, arenques salgados em barris, sal em sacos de três tamanhos", "Хлеб одного сорта по одной цене, солёная сельдь в бочках, соль в мешках трёх размеров", "Хліб одного сорту за однією ціною, солоні оселедці в барилах, сіль у мішках трьох розмірів"],
  "Smocks and coifs in salt-white, mantles in the one violet a port may wear": ["塩白のスモックと頭巾、そして港に許された唯一の紫のマント", "소금처럼 흰 작업복과 두건, 그리고 항구에 허락된 단 하나의 보랏빛 망토", "盐白色的罩衫和头巾,还有港口唯一获准穿的那种紫色斗篷", "鹽白色的罩衫和頭巾,還有港口唯一獲准穿的那種紫色斗篷", "Áo choàng làm việc và khăn trùm màu trắng muối, áo khoác ngoài màu tím duy nhất một bến cảng được mặc", "Baju kerja dan tudung putih garam, mantel dalam satu-satunya ungu yang boleh dipakai pelabuhan", "เสื้อคลุมทำงานและหมวกคลุมสีขาวเกลือ เสื้อคลุมไหล่สีม่วงสีเดียวที่เมืองท่าได้รับอนุญาตให้สวม", "Tuz beyazı önlükler ve başlıklar, bir limanın giyebileceği tek mor renkte pelerinler", "Blusones y cofias blanco sal, mantos en el único violeta que un puerto puede llevar", "Batas e toucas branco-sal, mantos no único violeta que um porto pode usar", "Блузы и чепцы цвета соли, накидки единственного фиолетового, что дозволен порту", "Блузи й очіпки кольору солі, накидки єдиного фіолетового, що дозволений портові"],
  "A salt barge, low in the water, its hold sealed by the Salt-House": ["喫水の深い塩運搬船。船倉は塩館により封印されている", "물에 깊이 잠긴 소금 바지선. 짐칸은 소금관이 봉인했다", "一艘吃水很深的运盐驳船,货舱由盐务所封着", "一艘吃水很深的運鹽駁船,貨艙由鹽務所封著", "Một sà lan muối, chìm sâu trong nước, khoang hàng niêm phong bởi Nhà Muối", "Tongkang garam, terbenam dalam di air, palkanya disegel Rumah Garam", "เรือบรรทุกเกลือ กินน้ำลึก ระวางถูกผนึกโดยโรงเกลือ", "Suya gömülmüş bir tuz mavnası, ambarı Tuz Evi'nce mühürlü", "Una barcaza de sal, hundida en el agua, con la bodega sellada por la Casa de la Sal", "Uma barcaça de sal, funda na água, com o porão selado pela Casa do Sal", "Соляная баржа, глубоко сидящая в воде, трюм опечатан Соляным домом", "Соляна баржа, глибоко занурена у воду, трюм опечатано Соляним домом"],
  "SALTREACH, the King's salt port. By order of the Crown, every pound of salt is weighed at the King's Salt-House before it leaves the pans, and written in the Ledger of Salt. Boats sail from the quay. The capital is north; Greyford and the King's road are east, over the bridge.": ["ソルトリーチ、王の塩の港。王冠の命により、塩はすべて塩田を出る前に王の塩館で量られ、塩の台帳に記される。船は岸壁から出る。都は北。グレイフォードと王の街道は橋を渡って東。", "솔트리치, 왕의 소금 항구. 왕실의 명에 따라 모든 소금은 염전을 떠나기 전에 왕의 소금관에서 무게를 달고 소금 장부에 기록한다. 배는 부두에서 떠난다. 수도는 북쪽. 그레이포드와 왕의 길은 다리 건너 동쪽.", "盐滩港,国王的盐港。奉王室之命,每一磅盐离开盐田前都要在王家盐务所过秤,并记入《盐册》。船从码头出发。王都在北;灰渡和国王大道在东,过桥即是。", "鹽灘港,國王的鹽港。奉王室之命,每一磅鹽離開鹽田前都要在王家鹽務所過秤,並記入《鹽冊》。船從碼頭出發。王都在北;灰渡和國王大道在東,過橋即是。", "SALTREACH, cảng muối của Nhà Vua. Theo lệnh Vương miện, mỗi cân muối đều được cân tại Nhà Muối của Nhà Vua trước khi rời ruộng muối, và ghi vào Sổ Muối. Thuyền rời từ bến. Kinh đô ở phía bắc; Greyford và đường của Nhà Vua ở phía đông, qua cầu.", "SALTREACH, pelabuhan garam Raja. Atas perintah Mahkota, setiap pon garam ditimbang di Rumah Garam Raja sebelum meninggalkan petak garam, dan dicatat di Buku Garam. Perahu berlayar dari dermaga. Ibu kota di utara; Greyford dan jalan Raja di timur, di seberang jembatan.", "ซอลต์รีช เมืองท่าเกลือของกษัตริย์ ตามพระบัญชาของราชบัลลังก์ เกลือทุกปอนด์ต้องชั่งที่โรงเกลือหลวงก่อนออกจากนาเกลือ และจดลงสมุดบัญชีเกลือ เรือออกจากท่า เมืองหลวงอยู่ทางเหนือ เกรย์ฟอร์ดและถนนหลวงอยู่ทางตะวันออก ข้ามสะพานไป", "SALTREACH, Kral'ın tuz limanı. Taç'ın emriyle her libre tuz, tuzlalardan çıkmadan önce Kralın Tuz Evi'nde tartılır ve Tuz Defteri'ne yazılır. Tekneler rıhtımdan kalkar. Başkent kuzeyde; Greyford ve Kral'ın yolu doğuda, köprünün öte yanında.", "SALTREACH, el puerto de la sal del Rey. Por orden de la Corona, cada libra de sal se pesa en la Casa de la Sal del Rey antes de salir de las salinas, y se anota en el Libro de la Sal. Las barcas salen del muelle. La capital está al norte; Greyford y el camino del Rey, al este, cruzando el puente.", "SALTREACH, o porto do sal do Rei. Por ordem da Coroa, cada libra de sal é pesada na Casa do Sal do Rei antes de deixar as salinas, e escrita no Livro do Sal. Os barcos saem do cais. A capital fica ao norte; Greyford e a estrada do Rei, a leste, atravessando a ponte.", "СОЛТРИЧ, королевский соляной порт. По велению Короны каждый фунт соли взвешивают в Королевском Соляном доме, прежде чем он покинет бассейны, и записывают в Книгу соли. Лодки отходят от причала. Столица — на севере; Грейфорд и Королевская дорога — на востоке, за мостом.", "СОЛТРІЧ, королівський соляний порт. З наказу Корони кожен фунт солі зважують у Королівському Соляному домі, перш ніж він покине басейни, і записують до Книги солі. Човни відходять від причалу. Столиця — на півночі; Грейфорд і Королівська дорога — на сході, за мостом."],
  "Dates, rope, lamp oil, diving stones with holes bored through, and nose-clips of tortoiseshell": ["ナツメヤシ、縄、灯油、穴を開けた潜水石、そして鼈甲の鼻ばさみ", "대추야자, 밧줄, 등잔 기름, 구멍을 뚫은 잠수돌, 거북딱지 코집게", "椰枣、绳子、灯油、钻了孔的潜水石,还有玳瑁鼻夹", "椰棗、繩子、燈油、鑽了孔的潛水石,還有玳瑁鼻夾", "Chà là, dây thừng, dầu đèn, đá lặn đục lỗ, và kẹp mũi bằng mai rùa", "Kurma, tali, minyak lampu, batu selam berlubang, dan penjepit hidung dari kulit penyu", "อินทผลัม เชือก น้ำมันตะเกียง หินดำน้ำเจาะรู และที่หนีบจมูกทำจากกระ", "Hurma, ip, kandil yağı, delikli dalış taşları ve bağa burun mandalları", "Dátiles, cuerda, aceite de lámpara, piedras de buceo agujereadas y pinzas de nariz de carey", "Tâmaras, corda, óleo de lamparina, pedras de mergulho furadas e prendedores de nariz de casco de tartaruga", "Финики, верёвка, масло для ламп, ныряльные камни с дырами и носовые зажимы из черепахового панциря", "Фініки, мотузка, олія для ламп, пірнальні камені з отворами й носові затискачі з черепахового панцира"],
  "The Copper Banner's pennant, and under it a smaller flag: Khetmar's harbour": ["銅の旗の三角旗、その下に小さな旗:ケトマルの港", "구리 깃발의 삼각기, 그 아래에 작은 깃발: 케트마르의 항구", "铜旗的三角旗,下面还挂着一面小旗:克特马尔之港", "銅旗的三角旗,下面還掛著一面小旗:克特馬爾之港", "Cờ đuôi nheo của Cờ Đồng, bên dưới là lá cờ nhỏ hơn: cảng của Khetmar", "Panji kecil Panji Tembaga, dan di bawahnya bendera lebih kecil: pelabuhan Khetmar", "ธงชายแหลมของธงทองแดง และใต้นั้นเป็นธงผืนเล็กกว่า: ท่าเรือของเคทมาร์", "Bakır Sancak'ın flaması ve altında daha küçük bir bayrak: Khetmar'ın limanı", "El gallardete del Estandarte de Cobre y, debajo, una bandera más pequeña: el puerto de Khetmar", "A flâmula do Estandarte de Cobre e, embaixo, uma bandeira menor: o porto de Khetmar", "Вымпел Медного знамени, а под ним флажок поменьше: гавань Кетмара", "Вимпел Мідного стягу, а під ним менший прапорець: гавань Кетмара"],
  "The harbour book: boats in, boats out, and dues to Khetmar in a careful hand": ["港の帳簿:入港した船、出港した船、そしてケトマルへの税が丁寧な筆跡で", "항구 장부: 들어온 배, 나간 배, 그리고 케트마르에 낼 세금이 꼼꼼한 글씨로", "港口簿:进港的船、出港的船,还有交给克特马尔的税费,字迹一丝不苟", "港口簿:進港的船、出港的船,還有交給克特馬爾的稅費,字跡一絲不苟", "Sổ cảng: thuyền vào, thuyền ra, và thuế nộp Khetmar bằng nét chữ cẩn thận", "Buku pelabuhan: perahu masuk, perahu keluar, dan bea untuk Khetmar dalam tulisan yang cermat", "สมุดท่าเรือ: เรือเข้า เรือออก และค่าธรรมเนียมส่งเคทมาร์ ด้วยลายมือประณีต", "Liman defteri: giren tekneler, çıkan tekneler ve Khetmar'a vergiler, özenli bir el yazısıyla", "El libro del puerto: barcas que entran, barcas que salen y los derechos para Khetmar, con letra cuidadosa", "O livro do porto: barcos que entram, barcos que saem e as taxas para Khetmar, em letra cuidadosa", "Портовая книга: лодки вошли, лодки вышли, и сборы для Кетмара, аккуратным почерком", "Портова книга: човни зайшли, човни вийшли, і збори для Кетмара, акуратним почерком"],
  "Diving stones on a cord, a nose-clip, and a basket for the shells": ["紐に通した潜水石、鼻ばさみ、そして貝を入れる籠", "줄에 꿴 잠수돌, 코집게, 조개를 담을 바구니", "穿在绳上的潜水石、一个鼻夹,还有装贝壳的篮子", "穿在繩上的潛水石、一個鼻夾,還有裝貝殼的籃子", "Đá lặn xâu trên dây, một cái kẹp mũi, và một giỏ đựng vỏ sò", "Batu selam pada tali, penjepit hidung, dan keranjang untuk kerang", "หินดำน้ำร้อยเชือก ที่หนีบจมูก และตะกร้าใส่หอย", "İpe dizili dalış taşları, bir burun mandalı ve kabuklar için bir sepet", "Piedras de buceo en un cordel, una pinza de nariz y una cesta para las conchas", "Pedras de mergulho num cordão, um prendedor de nariz e um cesto para as conchas", "Ныряльные камни на шнуре, носовой зажим и корзина для раковин", "Пірнальні камені на шнурі, носовий затискач і кошик для мушель"],
  "Cotton in sea-green, white and indigo, and a vat of blue the colour of the beds at noon": ["海緑と白と藍の木綿、そして真昼の海床の色をした青の染め甕", "바다빛 초록과 흰색과 쪽빛의 무명, 그리고 한낮 바다 밑 진주밭 빛깔의 파란 염료 통", "海绿、白和靛蓝的棉布,还有一缸正午珠床颜色的蓝染料", "海綠、白和靛藍的棉布,還有一缸正午珠床顏色的藍染料", "Vải bông màu xanh biển, trắng và chàm, và một vại thuốc nhuộm xanh màu bãi ngọc lúc giữa trưa", "Katun hijau laut, putih dan nila, dan sebejana biru berwarna dasar laut di siang hari", "ผ้าฝ้ายสีเขียวน้ำทะเล ขาว และคราม และถังย้อมสีน้ำเงินสีเดียวกับแหล่งหอยมุกยามเที่ยง", "Deniz yeşili, beyaz ve çivit pamuklular ve öğlen vakti yatakların renginde bir küp mavi", "Algodón verde mar, blanco y añil, y una tina de azul del color de los bancos a mediodía", "Algodão verde-mar, branco e anil, e uma tina de azul da cor dos bancos ao meio-dia", "Хлопок цвета морской волны, белый и индиго, и чан синего цвета жемчужных отмелей в полдень", "Бавовна кольору морської хвилі, біла й індиго, і чан синього кольору перлових мілин опівдні"],
  "MERRAB, the harbour of the east coast. The Copper Banner keeps the harbour for Khetmar, the Gilded Court buys the pearls, and the divers keep the beds and everybody else in bread. Khetmar is north up the road; Tel Ashun is off it to the west; Ennu's Well is south.": ["メラブ、東の海岸の港。港は銅の旗がケトマルのために預かり、真珠は金色の宮廷が買い、潜り手たちは真珠床を守ってほかの皆を食わせている。ケトマルは街道を北へ。テル・アシュンはその途中を西へ。エンヌの井戸は南。", "메라브, 동쪽 해안의 항구. 구리 깃발이 케트마르를 위해 항구를 지키고, 황금 궁정이 진주를 사들이며, 잠수부들은 진주밭을 지키며 나머지 모두를 먹여 살린다. 케트마르는 길 따라 북쪽, 텔 아슌은 그 길에서 서쪽으로, 엔누의 우물은 남쪽.", "梅拉布,东海岸的港口。铜旗替克特马尔守着港口,镀金宫廷收购珍珠,潜水人守着珠床,养活其他所有人。克特马尔沿路往北;泰勒阿顺在途中往西;恩努井在南。", "梅拉布,東海岸的港口。銅旗替克特馬爾守著港口,鍍金宮廷收購珍珠,潛水人守著珠床,養活其他所有人。克特馬爾沿路往北;泰勒阿順在途中往西;恩努井在南。", "MERRAB, cảng của bờ biển phía đông. Cờ Đồng giữ cảng cho Khetmar, Triều Mạ Vàng mua ngọc trai, còn thợ lặn giữ các bãi ngọc và nuôi cơm mọi người khác. Khetmar ở phía bắc theo con đường; Tel Ashun rẽ về phía tây; Giếng Ennu ở phía nam.", "MERRAB, pelabuhan pantai timur. Panji Tembaga menjaga pelabuhan untuk Khetmar, Istana Bersepuh membeli mutiara, dan para penyelam menjaga dasar laut dan memberi makan semua orang lain. Khetmar di utara menyusuri jalan; Tel Ashun bercabang ke barat; Sumur Ennu di selatan.", "เมอร์รับ ท่าเรือแห่งชายฝั่งตะวันออก ธงทองแดงดูแลท่าเรือให้เคทมาร์ ราชสำนักปิดทองรับซื้อไข่มุก และนักดำน้ำดูแลแหล่งหอยมุกและเลี้ยงปากท้องทุกคนที่เหลือ เคทมาร์อยู่ทางเหนือตามถนน เทล อาชุนแยกไปทางตะวันตก บ่อน้ำเอนนูอยู่ทางใต้", "MERRAB, doğu kıyısının limanı. Limanı Khetmar adına Bakır Sancak tutar, incileri Yaldızlı Saray satın alır, dalgıçlar da yatakları korur ve geri kalan herkesi doyurur. Khetmar yoldan kuzeyde; Tel Ashun yoldan batıya ayrılır; Ennu Kuyusu güneyde.", "MERRAB, el puerto de la costa este. El Estandarte de Cobre guarda el puerto para Khetmar, la Corte Dorada compra las perlas, y los buceadores cuidan los bancos y dan de comer a todos los demás. Khetmar está al norte por el camino; Tel Ashun sale de él hacia el oeste; el Pozo de Ennu, al sur.", "MERRAB, o porto da costa leste. O Estandarte de Cobre guarda o porto para Khetmar, a Corte Dourada compra as pérolas, e os mergulhadores cuidam dos bancos e põem pão na mesa de todos os outros. Khetmar fica ao norte pela estrada; Tel Ashun sai dela para o oeste; o Poço de Ennu, ao sul.", "МЕРРАБ, гавань восточного побережья. Медное знамя держит гавань для Кетмара, Позолоченный двор скупает жемчуг, а ныряльщики стерегут отмели и кормят всех остальных. Кетмар — на север по дороге; Тель-Ашун — от неё на запад; Колодец Энну — на юге.", "МЕРРАБ, гавань східного узбережжя. Мідний стяг тримає гавань для Кетмара, Позолочений двір скуповує перли, а пірнальники стережуть мілини й годують усіх інших. Кетмар — на північ дорогою; Тель-Ашун — від неї на захід; Криниця Енну — на півдні."],
  "Pots of every age dug from the mound, the oldest at the bottom, nobody's sure why": ["丘から掘り出したあらゆる時代の壺。いちばん古いものがいちばん下にあるが、なぜかは誰も知らない", "언덕에서 파낸 온갖 시대의 항아리. 가장 오래된 것이 맨 아래에 있는데, 왜 그런지는 아무도 모른다", "从土丘里挖出来的各个年代的陶罐,最老的在最底下,谁也说不清为什么", "從土丘裡挖出來的各個年代的陶罐,最老的在最底下,誰也說不清為什麼", "Những chiếc bình đủ mọi thời đào từ gò đất, cái cổ nhất nằm dưới cùng, chẳng ai rõ tại sao", "Tembikar dari segala zaman yang digali dari gundukan, yang tertua paling bawah, tak ada yang yakin kenapa", "หม้อทุกยุคที่ขุดจากเนิน ใบที่เก่าแก่ที่สุดอยู่ล่างสุด ไม่มีใครแน่ใจว่าทำไม", "Höyükten çıkarılmış her çağdan çömlekler, en eskisi en altta, kimse nedenini bilmiyor", "Vasijas de todas las épocas sacadas del montículo, las más antiguas abajo; nadie sabe muy bien por qué", "Potes de todas as épocas tirados do monte, os mais antigos embaixo; ninguém sabe bem por quê", "Горшки всех времён, выкопанные из холма, самые старые внизу, никто толком не знает почему", "Горщики всіх часів, викопані з пагорба, найстаріші внизу, ніхто достеменно не знає чому"],
  "The recorder's tent: black linen, a lapis border, the Obsidian Legacy's": ["記録官の天幕。黒い亜麻布に瑠璃色の縁、黒曜の遺統のものだ", "기록관의 천막. 검은 아마포에 청금석 빛 테두리, 흑요 유산의 것이다", "记录官的帐篷:黑亚麻布,青金石色镶边,是黑曜遗脉的", "記錄官的帳篷:黑亞麻布,青金石色鑲邊,是黑曜遺脈的", "Lều của người ghi chép: vải lanh đen, viền xanh lam ngọc, của Di Sản Hắc Diện", "Tenda pencatat: linen hitam, pinggiran lapis, milik Warisan Obsidian", "เต็นท์ของผู้บันทึก: ผ้าลินินดำ ขอบสีลาพิส ของมรดกออบซิเดียน", "Kayıtçının çadırı: kara keten, lacivert taşı kenarlı, Obsidyen Mirası'nın", "La tienda de la registradora: lino negro, ribete de lapislázuli, del Legado de Obsidiana", "A tenda da registradora: linho negro, debrum de lápis-lazúli, do Legado de Obsidiana", "Шатёр летописицы: чёрный лён, лазуритовая кайма, Обсидианового наследия", "Намет літописиці: чорний льон, лазуритова облямівка, Обсидіанової спадщини"],
  "Mudbricks drying in rows, stamped with the brickmaker's thumb": ["列になって乾く日干し煉瓦。煉瓦職人の親指の跡がついている", "줄지어 마르는 흙벽돌. 벽돌장이의 엄지 자국이 찍혀 있다", "一排排晾着的泥砖,印着砖匠的拇指印", "一排排晾著的泥磚,印著磚匠的拇指印", "Gạch bùn phơi thành hàng, in dấu ngón cái của thợ gạch", "Bata lumpur dijemur berjajar, dicap jempol si pembuat bata", "อิฐดินตากเรียงเป็นแถว ประทับรอยนิ้วโป้งของช่างทำอิฐ", "Sıra sıra kuruyan kerpiçler, tuğlacının başparmağıyla damgalı", "Adobes secándose en hileras, marcados con el pulgar del ladrillero", "Adobes secando em fileiras, marcados com o polegar do oleiro", "Сырцовые кирпичи сохнут рядами, с отпечатком большого пальца кирпичника", "Саманні цеглини сохнуть рядами, з відбитком великого пальця цегляра"],
  "TEL ASHUN, on its mound. Elder Hazane speaks for the village. Mudbrick for sale by the hundred. The mound is not for sale, the Elder says, though it is, she admits, for digging.": ["丘の上のテル・アシュン。村を代表するのは長老ハザネ。日干し煉瓦、百個単位で販売。丘は売り物ではない、と長老は言う。掘るためのものではある、と認めはするが。", "언덕 위의 텔 아슌. 마을을 대표하는 이는 장로 하자네. 흙벽돌 백 장 단위로 판매. 언덕은 팔지 않는다고 장로는 말한다. 파기는 한다고, 인정은 하지만.", "泰勒阿顺,坐落在它的土丘上。长老哈扎妮代表全村说话。泥砖按百块出售。长老说,土丘不卖;不过她承认,土丘是可以挖的。", "泰勒阿順,坐落在它的土丘上。長老哈扎妮代表全村說話。泥磚按百塊出售。長老說,土丘不賣;不過她承認,土丘是可以挖的。", "TEL ASHUN, trên gò đất của nó. Trưởng lão Hazane nói thay cho làng. Gạch bùn bán theo trăm viên. Gò thì không bán, Trưởng lão nói, dù bà thừa nhận là có đào.", "TEL ASHUN, di atas gundukannya. Tetua Hazane berbicara untuk desa. Bata lumpur dijual per seratus. Gundukan itu tidak dijual, kata sang Tetua, meski, ia mengakui, boleh digali.", "เทล อาชุน บนเนินของมัน ผู้อาวุโสฮาซาเนพูดแทนหมู่บ้าน อิฐดินขายเป็นร้อยก้อน เนินนั้นไม่ได้มีไว้ขาย ผู้อาวุโสว่า แต่เธอยอมรับว่ามีไว้ขุด", "TEL ASHUN, höyüğünün üstünde. Köy adına Yaşlı Hazane konuşur. Kerpiç yüzlük satılır. Höyük satılık değil, der Yaşlı; ama kazılık olduğunu kabul eder.", "TEL ASHUN, sobre su montículo. La anciana Hazane habla por la aldea. Adobe a la venta por centenares. El montículo no está a la venta, dice la anciana, aunque sí, admite, para cavar.", "TEL ASHUN, sobre o seu monte. A anciã Hazane fala pela aldeia. Adobe à venda às centenas. O monte não está à venda, diz a anciã, embora esteja, ela admite, para escavar.", "ТЕЛЬ-АШУН, на своём холме. За деревню говорит старейшина Хазане. Сырцовый кирпич продаётся сотнями. Холм не продаётся, говорит старейшина, хотя копать его, признаёт она, можно.", "ТЕЛЬ-АШУН, на своєму пагорбі. За село говорить старійшина Хазане. Саманна цегла продається сотнями. Пагорб не продається, каже старійшина, хоча копати його, визнає вона, можна."],
  "Tally sticks of water shares, one notch a day, going back three keepers": ["水の取り分を刻んだ割符。一日一刻み、三代の井戸守にさかのぼる", "물 배분을 새긴 눈금 막대. 하루에 한 눈금, 우물지기 세 대를 거슬러 올라간다", "记录用水份额的计数木签,一天刻一道,追溯三任守井人", "記錄用水份額的計數木籤,一天刻一道,追溯三任守井人", "Những que khắc phần nước, mỗi ngày một vết, từ ba đời người giữ giếng", "Batang hitung jatah air, satu takik sehari, sampai tiga penjaga sebelumnya", "ไม้ขีดนับส่วนแบ่งน้ำ วันละหนึ่งรอย ย้อนไปสามรุ่นผู้ดูแล", "Su paylarının çentik çubukları, günde bir çentik, üç bekçi geriye giden", "Tarjas de las partes de agua, una muesca al día, desde hace tres guardianes", "Talhas de contagem das partes de água, um entalhe por dia, desde três guardiões atrás", "Бирки водных долей, по зарубке в день, за три поколения хранителей", "Бирки водяних часток, по зарубці на день, за три покоління хранителів"],
  "A water jar, its lid tied down, and a dried date-palm frond for the floor": ["蓋を縛りつけた水瓶と、床を掃くための乾いたナツメヤシの葉", "뚜껑을 묶어 둔 물항아리와 바닥을 쓸 마른 대추야자 잎", "一只盖子绑紧的水罐,还有一片扫地用的干椰枣叶", "一隻蓋子綁緊的水罐,還有一片掃地用的乾椰棗葉", "Một vò nước buộc chặt nắp, và một tàu lá chà là khô để quét nhà", "Kendi air dengan tutup terikat, dan pelepah kurma kering untuk lantai", "โอ่งน้ำที่มัดฝาไว้ และทางอินทผลัมแห้งไว้กวาดพื้น", "Kapağı bağlı bir su testisi ve yer için kurumuş bir hurma dalı", "Una tinaja con la tapa atada y una hoja seca de palmera datilera para el suelo", "Uma talha com a tampa amarrada e uma folha seca de tamareira para o chão", "Кувшин с привязанной крышкой и сухая пальмовая ветвь для пола", "Глек із прив'язаною кришкою й суха пальмова гілка для підлоги"],
  "ENNU'S WELL. Water for the village first, for the gardens second, for the caravans third, and for the thirsty always. Ask the well-keeper before you fill more than a skin.": ["エンヌの井戸。水はまず村に、次に畑に、三番目に隊商に、そして渇いた者にはいつでも。革袋一つより多く汲むときは井戸守に尋ねること。", "엔누의 우물. 물은 첫째로 마을에, 둘째로 밭에, 셋째로 대상에게, 그리고 목마른 이에게는 언제나. 가죽 부대 하나보다 많이 채우려면 우물지기에게 물어볼 것.", "恩努井。水先给村子,其次给园子,再次给商队,口渴的人随时可饮。装水超过一袋者,请先问守井人。", "恩努井。水先給村子,其次給園子,再次給商隊,口渴的人隨時可飲。裝水超過一袋者,請先問守井人。", "GIẾNG ENNU. Nước trước hết cho làng, thứ hai cho vườn, thứ ba cho đoàn lữ hành, và luôn luôn cho người khát. Hỏi người giữ giếng trước khi lấy quá một túi da.", "SUMUR ENNU. Air pertama untuk desa, kedua untuk kebun, ketiga untuk kafilah, dan selalu untuk yang haus. Tanyakan penjaga sumur sebelum mengisi lebih dari satu kantong kulit.", "บ่อน้ำเอนนู น้ำสำหรับหมู่บ้านก่อน สำหรับสวนเป็นอันดับสอง สำหรับกองคาราวานเป็นอันดับสาม และสำหรับคนกระหายเสมอ ถามผู้ดูแลบ่อก่อนตักเกินหนึ่งถุงหนัง", "ENNU KUYUSU. Su önce köye, ikinci bahçelere, üçüncü kervanlara, susayana ise her zaman. Bir tulumdan fazla dolduracaksan önce kuyu bekçisine sor.", "EL POZO DE ENNU. El agua, primero para la aldea, segundo para los huertos, tercero para las caravanas, y siempre para el sediento. Pregunta a la guardiana del pozo antes de llenar más de un odre.", "O POÇO DE ENNU. A água, primeiro para a aldeia, segundo para os pomares, terceiro para as caravanas, e sempre para quem tem sede. Pergunte à guardiã do poço antes de encher mais de um odre.", "КОЛОДЕЦ ЭННУ. Вода — сперва деревне, затем садам, затем караванам, а жаждущему — всегда. Спросите хранительницу колодца, прежде чем наполнить больше одного бурдюка.", "КРИНИЦЯ ЕННУ. Вода — спершу селу, потім садам, потім караванам, а спраглому — завжди. Запитайте хранительку криниці, перш ніж набрати більше одного бурдюка."],
  "Whatever came off the boats this morning, in a pot with potatoes and milk and pepper. Gullwick's inn has never made it the same way twice. Heals 14.": ["今朝船から揚がったものを、じゃがいもと牛乳と胡椒と一緒に鍋に入れたもの。ガルウィックの宿は同じ味で作れたためしがない。14回復。", "오늘 아침 배에서 내린 것은 뭐든, 감자와 우유와 후추를 넣어 냄비에 끓였다. 걸윅 여관은 한 번도 같은 맛으로 만든 적이 없다. 14 회복.", "今早船上卸下来的随便什么,和土豆、牛奶、胡椒一起下锅。鸥湾的客栈从没做出过两锅一样的。恢复14点。", "今早船上卸下來的隨便什麼,和馬鈴薯、牛奶、胡椒一起下鍋。鷗灣的客棧從沒做出過兩鍋一樣的。恢復14點。", "Mọi thứ thuyền mang về sáng nay, cho vào nồi với khoai tây, sữa và tiêu. Quán trọ Gullwick chưa bao giờ nấu hai lần giống nhau. Hồi 14.", "Apa pun yang turun dari perahu pagi ini, dimasak dalam panci dengan kentang, susu, dan lada. Penginapan Gullwick tak pernah membuatnya sama dua kali. Memulihkan 14.", "อะไรก็ตามที่ขึ้นจากเรือเมื่อเช้านี้ ใส่หม้อกับมันฝรั่ง นม และพริกไทย โรงเตี๊ยมกัลวิกไม่เคยทำออกมาเหมือนเดิมสักครั้ง ฟื้นฟู 14", "Bu sabah teknelerden ne çıktıysa, patates, süt ve karabiberle bir tencerede. Gullwick'in hanı onu hiç iki kez aynı yapmadı. 14 iyileştirir.", "Lo que haya salido de las barcas esta mañana, en una olla con patatas, leche y pimienta. La posada de Gullwick nunca lo ha hecho igual dos veces. Cura 14.", "O que tiver saído dos barcos esta manhã, numa panela com batatas, leite e pimenta. A estalagem de Gullwick nunca o fez igual duas vezes. Cura 14.", "Всё, что утром сняли с лодок, в котле с картошкой, молоком и перцем. Галлвикский трактир ни разу не сварил её одинаково. Лечит 14.", "Усе, що вранці зняли з човнів, у казані з картоплею, молоком і перцем. Галлвіцька корчма жодного разу не зварила її однаково. Лікує 14."],
  "A herring split, salted and dried on Saltreach's racks until it would keep through a war. Heals 7.": ["開いて塩をし、戦争をひとつ越せるほどソルトリーチの干し棚で干したニシン。7回復。", "배를 갈라 소금에 절여, 전쟁 하나는 너끈히 버틸 만큼 솔트리치의 건조대에서 말린 청어. 7 회복.", "一条剖开的鲱鱼,抹了盐,在盐滩港的晾架上晒到能撑过一场战争。恢复7点。", "一條剖開的鯡魚,抹了鹽,在鹽灘港的晾架上曬到能撐過一場戰爭。恢復7點。", "Một con cá trích xẻ đôi, ướp muối và phơi trên giàn ở Saltreach cho tới khi để được qua cả một cuộc chiến. Hồi 7.", "Seekor haring dibelah, diasinkan dan dijemur di rak Saltreach sampai awet melewati perang. Memulihkan 7.", "ปลาแฮร์ริ่งผ่าซีก หมักเกลือและตากบนราวของซอลต์รีชจนเก็บได้ข้ามสงคราม ฟื้นฟู 7", "Yarılmış, tuzlanmış ve Saltreach'in askılarında bir savaşı atlatacak kadar kurutulmuş bir ringa. 7 iyileştirir.", "Un arenque abierto, salado y secado en los secaderos de Saltreach hasta que aguante una guerra. Cura 7.", "Um arenque aberto, salgado e seco nos varais de Saltreach até aguentar uma guerra. Cura 7.", "Сельдь, распластанная, посоленная и высушенная на вешалах Солтрича так, что пролежит всю войну. Лечит 7.", "Оселедець, розпластаний, посолений і висушений на вішалах Солтріча так, що пролежить усю війну. Лікує 7."],
  "A pearl off Merrab's beds, pale with a pink light in it. The divers say each one is a year of somebody's breath.": ["メラブの真珠床で採れた真珠。淡く、内に薄紅の光がある。潜り手たちは、一粒一粒が誰かの一年分の息だと言う。", "메라브 진주밭에서 건진 진주. 옅은 빛 속에 분홍빛이 감돈다. 잠수부들은 한 알 한 알이 누군가의 일 년 치 숨이라고 말한다.", "一颗梅拉布珠床的珍珠,色浅,里头透着粉光。潜水人说,每一颗都是某个人一年的气息。", "一顆梅拉布珠床的珍珠,色淺,裡頭透著粉光。潛水人說,每一顆都是某個人一年的氣息。", "Một viên ngọc từ các bãi ngọc của Merrab, nhạt màu với ánh hồng bên trong. Thợ lặn nói mỗi viên là một năm hơi thở của ai đó.", "Mutiara dari dasar laut Merrab, pucat dengan cahaya merah muda di dalamnya. Para penyelam bilang tiap butir adalah setahun napas seseorang.", "ไข่มุกจากแหล่งหอยมุกของเมอร์รับ สีซีดมีประกายชมพูอยู่ข้างใน นักดำน้ำว่าแต่ละเม็ดคือลมหายใจหนึ่งปีของใครสักคน", "Merrab yataklarından bir inci, soluk, içinde pembe bir ışık. Dalgıçlar her birinin birinin bir yıllık nefesi olduğunu söyler.", "Una perla de los bancos de Merrab, pálida, con una luz rosada dentro. Los buceadores dicen que cada una es un año del aliento de alguien.", "Uma pérola dos bancos de Merrab, pálida, com uma luz rosada dentro. Os mergulhadores dizem que cada uma é um ano do fôlego de alguém.", "Жемчужина с отмелей Мерраба, бледная, с розовым светом внутри. Ныряльщики говорят, что каждая — это год чьего-то дыхания.", "Перлина з мілин Меррабу, бліда, з рожевим світлом усередині. Пірнальники кажуть, що кожна — це рік чийогось подиху."],
  "Gullwick Light's spare oilskin, salt-stiff and smelling of lamp oil. The keeper says it's kept three keepers dry and one of them honest.": ["ガルウィック灯台の予備の油布外套。塩でこわばり、灯油の匂いがする。灯台守いわく、三人の灯台守を濡らさず、そのうち一人を正直にしておいたそうだ。", "걸윅 등대의 여벌 방수 외투. 소금기로 뻣뻣하고 등잔 기름 냄새가 난다. 등대지기 말로는 등대지기 셋을 젖지 않게 했고, 그중 하나는 정직하게 했단다.", "鸥湾灯塔备用的油布衣,被盐浸得发硬,一股灯油味。守灯人说,它让三任守灯人没淋湿过,还让其中一个保持了诚实。", "鷗灣燈塔備用的油布衣,被鹽浸得發硬,一股燈油味。守燈人說,它讓三任守燈人沒淋濕過,還讓其中一個保持了誠實。", "Chiếc áo dầu dự phòng của Đèn biển Gullwick, cứng muối và nồng mùi dầu đèn. Người giữ đèn nói nó đã giữ khô ba người giữ đèn, và giữ một người trong số họ lương thiện.", "Jas minyak cadangan Mercusuar Gullwick, kaku oleh garam dan berbau minyak lampu. Penjaganya bilang jas ini menjaga tiga penjaga tetap kering dan salah satunya tetap jujur.", "เสื้อกันน้ำสำรองของประภาคารกัลวิก แข็งด้วยเกลือและมีกลิ่นน้ำมันตะเกียง ผู้เฝ้าว่ามันทำให้ผู้เฝ้าสามคนไม่เปียก และทำให้หนึ่งในนั้นซื่อสัตย์", "Gullwick Feneri'nin yedek muşambası, tuzdan kaskatı ve kandil yağı kokulu. Fenerci, üç fenerciyi kuru, birini de dürüst tuttuğunu söyler.", "El impermeable de repuesto del faro de Gullwick, tieso de sal y con olor a aceite de lámpara. El farero dice que ha mantenido secos a tres fareros y honrado a uno de ellos.", "O oleado de reserva do farol de Gullwick, duro de sal e cheirando a óleo de lamparina. O faroleiro diz que manteve secos três faroleiros e honesto um deles.", "Запасной непромокаемый плащ Галлвикского маяка, жёсткий от соли и пахнущий ламповым маслом. Смотритель говорит, что он держал сухими трёх смотрителей, а одного — честным.", "Запасний непромокальний плащ Галлвіцького маяка, цупкий від солі й пахне ламповою олією. Доглядач каже, що він тримав сухими трьох доглядачів, а одного — чесним."],
  "A plain silver ring stamped with the old Saltreach standard, a pound as it was before anyone recast it. It weighs exactly what it says.": ["古いソルトリーチの基準、誰かが鋳直す前の一ポンドが刻印された素朴な銀の指輪。刻まれたとおりの重さがある。", "옛 솔트리치 기준, 누군가 다시 주조하기 전의 한 파운드가 찍힌 소박한 은반지. 새겨진 그대로의 무게가 나간다.", "一枚朴素的银戒,刻着盐滩港的旧标准,一磅还是没人重铸前的一磅。它的重量和刻的分毫不差。", "一枚樸素的銀戒,刻著鹽灘港的舊標準,一磅還是沒人重鑄前的一磅。它的重量和刻的分毫不差。", "Một chiếc nhẫn bạc trơn đóng dấu chuẩn cũ của Saltreach, một cân như khi chưa ai đúc lại. Nó nặng đúng như nó ghi.", "Cincin perak polos bercap standar lama Saltreach, satu pon seperti sebelum ada yang menuang ulang. Beratnya persis seperti tertulis.", "แหวนเงินเรียบๆ ประทับมาตรฐานเก่าของซอลต์รีช หนึ่งปอนด์อย่างที่เป็นก่อนใครหล่อใหม่ หนักตรงตามที่สลักไว้", "Eski Saltreach ölçüsüyle, kimse yeniden dökmeden önceki libreyle damgalı sade bir gümüş yüzük. Tam yazdığı kadar çeker.", "Un sencillo anillo de plata con el viejo patrón de Saltreach, una libra como era antes de que nadie la refundiera. Pesa exactamente lo que dice.", "Um anel de prata simples estampado com o antigo padrão de Saltreach, uma libra como era antes de alguém a refundir. Pesa exatamente o que diz.", "Простое серебряное кольцо с клеймом старого солтричского эталона, фунта, каким он был до перелива. Весит ровно столько, сколько на нём написано.", "Простий срібний перстень із клеймом старого солтрічського еталона, фунта, яким він був до переливання. Важить рівно стільки, скільки на ньому написано."],
  "One pearl from the beds, strung on a diver's cord. The divers of Merrab give it to someone who went into the water for them, which isn't many.": ["真珠床の真珠を一粒、潜り手の紐に通したもの。メラブの潜り手たちが、自分たちのために水に入った者に贈る。そういう者は多くない。", "진주밭의 진주 한 알을 잠수부의 끈에 꿴 것. 메라브의 잠수부들이 자기들을 위해 물에 들어간 사람에게 준다. 그런 사람은 많지 않다.", "珠床里的一颗珍珠,穿在潜水人的绳上。梅拉布的潜水人把它送给为他们下过水的人,这样的人不多。", "珠床裡的一顆珍珠,穿在潛水人的繩上。梅拉布的潛水人把它送給為他們下過水的人,這樣的人不多。", "Một viên ngọc từ bãi ngọc, xâu trên dây của thợ lặn. Thợ lặn Merrab tặng nó cho người đã xuống nước vì họ, mà chẳng mấy ai.", "Sebutir mutiara dari dasar laut, dironce pada tali penyelam. Para penyelam Merrab memberikannya kepada orang yang turun ke air demi mereka, dan itu tak banyak.", "ไข่มุกหนึ่งเม็ดจากแหล่งหอยมุก ร้อยด้วยเชือกของนักดำน้ำ นักดำน้ำแห่งเมอร์รับมอบให้คนที่ลงน้ำเพื่อพวกเขา ซึ่งมีไม่มากนัก", "Yataklardan bir inci, bir dalgıç ipine dizili. Merrab dalgıçları onu kendileri için suya giren birine verir; pek çok kişi değildir.", "Una perla de los bancos, ensartada en un cordel de buceador. Los buceadores de Merrab se la dan a quien se metió en el agua por ellos, que no son muchos.", "Uma pérola dos bancos, enfiada num cordão de mergulhador. Os mergulhadores de Merrab a dão a quem entrou na água por eles, e não são muitos.", "Одна жемчужина с отмелей на шнуре ныряльщика. Ныряльщики Мерраба дарят её тому, кто лез в воду ради них, а таких немного.", "Одна перлина з мілин на шнурі пірнальника. Пірнальники Меррабу дарують її тому, хто ліз у воду заради них, а таких небагато."],
  "Tel Ashun's brickmaker's gloves, cracked with clay at every knuckle. Tahun's grandfather made the leather; Tahun has made the cracks.": ["テル・アシュンの煉瓦職人の手袋。どの指の節も粘土でひび割れている。革を作ったのはタフンの祖父、ひびを作ったのはタフンだ。", "텔 아슌 벽돌장이의 장갑. 마디마다 흙으로 갈라져 있다. 가죽은 타훈의 할아버지가 만들었고, 갈라진 틈은 타훈이 만들었다.", "泰勒阿顺砖匠的手套,每个指节都被泥巴撑裂了。皮子是塔洪的祖父鞣的,裂口是塔洪磨的。", "泰勒阿順磚匠的手套,每個指節都被泥巴撐裂了。皮子是塔洪的祖父鞣的,裂口是塔洪磨的。", "Đôi găng tay của thợ gạch Tel Ashun, nứt vì đất sét ở mọi đốt ngón. Ông nội Tahun làm da; Tahun làm ra những vết nứt.", "Sarung tangan pembuat bata Tel Ashun, retak oleh tanah liat di setiap buku jari. Kakek Tahun membuat kulitnya; Tahun membuat retakannya.", "ถุงมือของช่างทำอิฐแห่งเทล อาชุน แตกด้วยดินเหนียวทุกข้อนิ้ว ปู่ของทาฮุนทำหนัง ทาฮุนทำรอยแตก", "Tel Ashun tuğlacısının eldivenleri, her boğumda kilden çatlamış. Deriyi Tahun'un dedesi yaptı; çatlakları Tahun.", "Los guantes del ladrillero de Tel Ashun, agrietados de barro en cada nudillo. El abuelo de Tahun hizo el cuero; Tahun ha hecho las grietas.", "As luvas do oleiro de Tel Ashun, rachadas de barro em cada nó dos dedos. O avô de Tahun fez o couro; Tahun fez as rachaduras.", "Перчатки кирпичника из Тель-Ашуна, потрескавшиеся от глины на каждом суставе. Кожу выделал дед Тахуна, трещины — сам Тахун.", "Рукавиці цегляра з Тель-Ашуна, потріскані від глини на кожному суглобі. Шкіру вичинив дід Тахуна, тріщини — сам Тахун."],
  "An indigo headcloth with a white thread worked through it like running water: Ennu's Well's, for someone who kept it.": ["流れる水のように白い糸を織り込んだ藍の頭布。エンヌの井戸のもので、井戸を守った者に贈られる。", "흐르는 물처럼 흰 실을 짜 넣은 쪽빛 머릿수건. 엔누의 우물의 것으로, 우물을 지킨 이에게 준다.", "一条靛蓝头巾,一道白线像流水般织在其中:恩努井的头巾,给守过这口井的人。", "一條靛藍頭巾,一道白線像流水般織在其中:恩努井的頭巾,給守過這口井的人。", "Một khăn trùm đầu màu chàm có sợi trắng dệt xuyên như dòng nước chảy: của Giếng Ennu, cho người đã giữ giếng.", "Kain kepala nila dengan benang putih ditenun seperti air mengalir: milik Sumur Ennu, untuk orang yang menjaganya.", "ผ้าคลุมศีรษะสีครามที่ทอด้ายขาวสอดผ่านดั่งน้ำไหล: ของบ่อน้ำเอนนู สำหรับผู้ที่ดูแลมัน", "İçinden akan su gibi beyaz bir iplik geçirilmiş çivit bir başörtüsü: Ennu Kuyusu'nun, onu koruyan biri için.", "Un tocado añil con un hilo blanco que lo atraviesa como agua corriente: del Pozo de Ennu, para quien lo guardó.", "Um lenço anil com um fio branco atravessando-o como água corrente: do Poço de Ennu, para quem o guardou.", "Индиговый платок с белой нитью, пущенной по нему, как бегущая вода: от Колодца Энну тому, кто его сберёг.", "Індигова хустка з білою ниткою, пущеною по ній, як біжуча вода: від Криниці Енну тому, хто її зберіг."],
  "A knitted cap of navy wool, rolled at the brim. Every head on every boat out of Gullwick has one, and argues about whose is warmest.": ["つばを折り返した紺の毛糸編み帽。ガルウィックの船に乗る頭という頭がかぶっていて、誰のがいちばん暖かいかで言い争う。", "챙을 말아 올린 짙은 남색 털실 모자. 걸윅에서 나가는 모든 배의 모든 머리에 하나씩 있고, 누구 것이 제일 따뜻한지 다툰다.", "一顶藏青毛线织的帽子,帽檐卷起。从鸥湾出海的每条船上每个人头上都有一顶,还争谁的最暖和。", "一頂藏青毛線織的帽子,帽簷捲起。從鷗灣出海的每條船上每個人頭上都有一頂,還爭誰的最暖和。", "Một chiếc mũ len xanh hải quân, vành cuộn lên. Mọi cái đầu trên mọi con thuyền rời Gullwick đều có một chiếc, và cãi nhau xem chiếc nào ấm nhất.", "Topi rajut wol biru tua, tepinya digulung. Setiap kepala di setiap perahu dari Gullwick punya satu, dan berdebat milik siapa yang paling hangat.", "หมวกถักขนสัตว์สีกรมท่า ม้วนขอบ ทุกหัวบนเรือทุกลำที่ออกจากกัลวิกมีหนึ่งใบ และเถียงกันว่าใบของใครอุ่นที่สุด", "Kenarı kıvrık, lacivert yünden örme bir bere. Gullwick'ten çıkan her teknedeki her başta bir tane vardır ve hangisinin en sıcak olduğu tartışılır.", "Un gorro de punto de lana azul marino, con el borde vuelto. Todas las cabezas de todas las barcas de Gullwick tienen uno, y discuten cuál abriga más.", "Um gorro de tricô de lã azul-marinho, com a aba dobrada. Toda cabeça em todo barco de Gullwick tem um, e discute qual é o mais quente.", "Вязаная шапка из тёмно-синей шерсти с подвёрнутым краем. Она есть на каждой голове в каждой лодке из Галлвика, и все спорят, чья теплее.", "В'язана шапка з темно-синьої вовни з підгорнутим краєм. Вона є на кожній голові в кожному човні з Галлвіка, і всі сперечаються, чия тепліша."],
  "A fisher's jersey knitted tight in oiled navy wool, ropes and ladders worked down the front. Each family has its own pattern, so the sea can't keep anyone nameless.": ["脂を含んだ紺の毛糸できつく編んだ漁師のセーター。前身頃に縄と梯子の模様。家ごとに模様が違うので、海は誰も名なしのままにはしておけない。", "기름 먹인 남색 털실로 촘촘히 뜬 어부의 스웨터. 앞판에 밧줄과 사다리 무늬가 있다. 집집마다 무늬가 달라서, 바다는 아무도 이름 없이 붙잡아 둘 수 없다.", "用浸过油的藏青毛线织得紧实的渔夫毛衣,前襟织着绳纹和梯纹。每家都有自己的花纹,这样大海就没法让任何人无名无姓。", "用浸過油的藏青毛線織得緊實的漁夫毛衣,前襟織著繩紋和梯紋。每家都有自己的花紋,這樣大海就沒法讓任何人無名無姓。", "Áo len của dân chài đan chặt bằng len xanh hải quân tẩm dầu, hoa văn dây thừng và thang dọc mặt trước. Mỗi nhà một kiểu, nên biển không thể giữ ai mà không có tên.", "Sweter nelayan dirajut rapat dari wol biru tua berminyak, motif tali dan tangga di bagian depan. Tiap keluarga punya polanya sendiri, sehingga laut tak bisa menahan siapa pun tanpa nama.", "เสื้อถักของชาวประมง ถักแน่นด้วยขนสัตว์สีกรมท่าชุบน้ำมัน ลายเชือกและบันไดไล่ลงด้านหน้า แต่ละตระกูลมีลายของตัวเอง ทะเลจึงเก็บใครไว้โดยไร้ชื่อไม่ได้", "Yağlı lacivert yünden sıkı örülmüş bir balıkçı kazağı, önünde halat ve merdiven desenleri. Her ailenin kendi deseni vardır; deniz kimseyi isimsiz tutamaz.", "Un jersey de pescador tejido apretado en lana azul marino engrasada, con cuerdas y escaleras en la pechera. Cada familia tiene su dibujo, para que el mar no pueda quedarse a nadie sin nombre.", "Uma camisola de pescador tricotada justa em lã azul-marinho oleada, com cordas e escadas na frente. Cada família tem seu padrão, para que o mar não fique com ninguém sem nome.", "Рыбацкий свитер плотной вязки из промасленной тёмно-синей шерсти, с канатами и лесенками на груди. У каждой семьи свой узор, чтобы море никого не оставило безымянным.", "Рибальський светр щільної в'язки з промасленої темно-синьої вовни, з канатами й драбинками на грудях. Кожна родина має свій візерунок, щоб море нікого не лишило безіменним."],
  "Breeches cut from an old sail, tarred at the knees, as stiff as a door until the third wash.": ["古い帆から裁った半ズボン。膝にタールを塗ってあり、三度洗うまでは戸板のように硬い。", "낡은 돛을 잘라 만든 반바지. 무릎에 타르를 먹였고, 세 번 빨기 전까지는 문짝처럼 뻣뻣하다.", "用旧帆裁成的马裤,膝盖涂了沥青,洗三遍之前硬得像门板。", "用舊帆裁成的馬褲,膝蓋塗了瀝青,洗三遍之前硬得像門板。", "Quần cắt từ một cánh buồm cũ, đầu gối quét nhựa, cứng như cánh cửa cho tới lần giặt thứ ba.", "Celana dipotong dari layar tua, lututnya diter, kaku seperti pintu sampai cucian ketiga.", "กางเกงตัดจากใบเรือเก่า ทาน้ำมันดินที่เข่า แข็งเหมือนบานประตูจนกว่าจะซักครั้งที่สาม", "Eski bir yelkenden kesilmiş, dizleri katranlı, üçüncü yıkamaya kadar kapı gibi kaskatı bir pantolon.", "Calzones cortados de una vela vieja, embreados en las rodillas, tiesos como una puerta hasta el tercer lavado.", "Calções cortados de uma vela velha, alcatroados nos joelhos, duros como uma porta até a terceira lavagem.", "Бриджи, скроенные из старого паруса, просмолённые на коленях, жёсткие, как дверь, до третьей стирки.", "Бриджі, скроєні зі старого вітрила, просмолені на колінах, тверді, як двері, до третього прання."],
  "A heavy black cloak with a red lining, the harbour pilots' own: they wear it red side out when a ship's coming in, so the ship can see who to blame.": ["裏地の赤い重たい黒外套。港の水先案内人のものだ。船が入ってくるときは赤い側を表にして着る。誰のせいにすればいいか、船から見えるように。", "안감이 붉은 무거운 검은 망토. 항구 도선사들의 것이다. 배가 들어올 때면 붉은 쪽을 겉으로 입는다. 배가 누구를 탓해야 할지 볼 수 있도록.", "一件红衬里的厚重黑斗篷,港口引航员专用:船进港时他们把红面翻到外面穿,好让船看清该怪谁。", "一件紅襯裡的厚重黑斗篷,港口引航員專用:船進港時他們把紅面翻到外面穿,好讓船看清該怪誰。", "Một chiếc áo choàng đen nặng lót đỏ, của riêng các hoa tiêu cảng: họ mặc mặt đỏ ra ngoài khi có tàu vào, để tàu thấy nên trách ai.", "Jubah hitam tebal berlapis merah, milik para pandu pelabuhan: mereka memakainya dengan sisi merah di luar saat kapal masuk, supaya kapal tahu siapa yang harus disalahkan.", "เสื้อคลุมดำหนักซับในสีแดง เป็นของผู้นำร่องท่าเรือ พวกเขากลับด้านแดงออกเมื่อมีเรือเข้ามา เพื่อให้เรือเห็นว่าควรโทษใคร", "Kırmızı astarlı ağır siyah bir pelerin, liman kılavuzlarının: bir gemi girerken kırmızı yüzü dışta giyerler ki gemi kimi suçlayacağını görsün.", "Una pesada capa negra forrada de rojo, la de los prácticos del puerto: la llevan con el rojo por fuera cuando entra un barco, para que el barco vea a quién culpar.", "Uma pesada capa negra forrada de vermelho, a dos práticos do porto: usam-na com o vermelho para fora quando um navio está chegando, para que o navio veja a quem culpar.", "Тяжёлый чёрный плащ на красной подкладке, плащ портовых лоцманов: когда входит корабль, его надевают красной стороной наружу, чтобы корабль видел, кого винить.", "Важкий чорний плащ на червоній підкладці, плащ портових лоцманів: коли заходить корабель, його вдягають червоним боком назовні, щоб корабель бачив, кого винуватити."],
  "Thigh-high leather boots, greased, folded down at the knee on land and up at sea.": ["脂を塗った腿までの革長靴。陸では膝で折り返し、海では引き上げる。", "기름을 먹인 허벅지까지 오는 가죽 장화. 뭍에서는 무릎에서 접고 바다에서는 끌어올린다.", "齐大腿的皮靴,上过油,在岸上翻到膝盖,出海时拉上去。", "齊大腿的皮靴,上過油,在岸上翻到膝蓋,出海時拉上去。", "Ủng da cao tới đùi, bôi mỡ, gập xuống đầu gối khi trên bờ và kéo lên khi ra biển.", "Sepatu bot kulit setinggi paha, diminyaki, dilipat di lutut di darat dan ditarik di laut.", "รองเท้าบูตหนังสูงถึงต้นขา ทาไข พับลงที่เข่าเมื่ออยู่บนบกและดึงขึ้นเมื่อออกทะเล", "Uyluğa kadar çıkan, yağlanmış deri çizmeler; karada dizde katlanır, denizde çekilir.", "Botas de cuero hasta el muslo, engrasadas, dobladas a la rodilla en tierra y subidas en el mar.", "Botas de couro até a coxa, engraxadas, dobradas no joelho em terra e puxadas no mar.", "Кожаные сапоги до бедра, смазанные жиром, на суше подвёрнутые до колена, в море натянутые.", "Шкіряні чоботи до стегна, змащені жиром, на суші підгорнуті до коліна, у морі натягнуті."],
  "A close white coif tied under the chin, against the glare off the pans. The Sumptuary Office allows it a violet edge, one finger wide.": ["塩田の照り返しを防ぐ、顎の下で結ぶぴったりした白い頭巾。奢侈取締局は指一本幅の紫の縁を許している。", "염전의 눈부신 반사광을 막으려 턱 밑에서 묶는 꼭 맞는 흰 두건. 사치단속청은 손가락 하나 너비의 보랏빛 테두리를 허락한다.", "一顶贴头的白头巾,在下巴下系紧,挡住盐田的反光。禁奢署允许它镶一指宽的紫边。", "一頂貼頭的白頭巾,在下巴下繫緊,擋住鹽田的反光。禁奢署允許它鑲一指寬的紫邊。", "Một chiếc khăn trùm trắng ôm đầu buộc dưới cằm, chống ánh chói từ ruộng muối. Sở Kiểm soát Xa xỉ cho phép nó một đường viền tím rộng một ngón tay.", "Tudung putih rapat diikat di bawah dagu, menahan silau petak garam. Kantor Kemewahan mengizinkan pinggiran ungu selebar satu jari.", "หมวกคลุมสีขาวแนบศีรษะ ผูกใต้คาง กันแสงจ้าจากนาเกลือ สำนักควบคุมความฟุ่มเฟือยอนุญาตให้มีขอบม่วงกว้างหนึ่งนิ้ว", "Tuzlaların parıltısına karşı çenenin altından bağlanan dar beyaz bir başlık. İsraf Dairesi ona bir parmak eninde mor bir kenar izni verir.", "Una cofia blanca ceñida, atada bajo la barbilla, contra el resplandor de las salinas. La Oficina Suntuaria le permite un ribete violeta de un dedo de ancho.", "Uma touca branca justa, amarrada sob o queixo, contra o brilho das salinas. O Ofício Suntuário lhe permite uma borda violeta da largura de um dedo.", "Плотный белый чепец, завязанный под подбородком, от слепящего блеска бассейнов. Управление роскоши дозволяет ему фиолетовую кайму шириной в палец.", "Щільний білий очіпок, зав'язаний під підборіддям, від сліпучого блиску басейнів. Управління розкоші дозволяє йому фіолетову облямівку завширшки в палець."],
  "A long smock of undyed linen, white with salt to the elbow. Saltreach washes it on the seventh day, after the seventh prayer.": ["染めていない亜麻の長いスモック。肘まで塩で白い。ソルトリーチでは七日目、七度目の祈りのあとに洗う。", "물들이지 않은 아마로 만든 긴 작업복. 팔꿈치까지 소금으로 하얗다. 솔트리치에서는 이레째 날, 일곱 번째 기도 뒤에 빤다.", "一件本色亚麻长罩衫,一直到手肘都被盐染白了。盐滩港在第七天、第七次祷告之后洗它。", "一件本色亞麻長罩衫,一直到手肘都被鹽染白了。鹽灘港在第七天、第七次禱告之後洗它。", "Một chiếc áo choàng dài bằng vải lanh không nhuộm, trắng muối tới khuỷu tay. Saltreach giặt nó vào ngày thứ bảy, sau lời cầu nguyện thứ bảy.", "Baju kerja panjang dari linen tak dicelup, putih oleh garam sampai siku. Saltreach mencucinya di hari ketujuh, setelah doa ketujuh.", "เสื้อคลุมยาวผ้าลินินไม่ย้อม ขาวด้วยเกลือถึงข้อศอก ซอลต์รีชซักมันในวันที่เจ็ด หลังการสวดครั้งที่เจ็ด", "Boyanmamış ketenden uzun bir önlük, dirseğe kadar tuzdan beyaz. Saltreach onu yedinci gün, yedinci duadan sonra yıkar.", "Un blusón largo de lino sin teñir, blanco de sal hasta el codo. Saltreach lo lava el séptimo día, después de la séptima oración.", "Uma bata comprida de linho cru, branca de sal até o cotovelo. Saltreach a lava no sétimo dia, depois da sétima oração.", "Длинная блуза из некрашеного льна, белая от соли до локтя. В Солтриче её стирают на седьмой день, после седьмой молитвы.", "Довга блуза з нефарбованого льону, біла від солі до ліктя. У Солтрічі її перуть на сьомий день, після сьомої молитви."],
  "A violet-grey kirtle tucked up at the hem for the brine, the colour of the capital's roofs in rain.": ["塩水に濡れないよう裾をたくし上げた紫がかった灰色のカートル。雨の日の都の屋根の色。", "소금물에 젖지 않게 단을 걷어 올린 보랏빛 회색 커틀. 비 오는 날 수도 지붕의 빛깔이다.", "一条紫灰色长裙,下摆掖起来防盐水,是王都屋顶在雨中的颜色。", "一條紫灰色長裙,下擺掖起來防鹽水,是王都屋頂在雨中的顏色。", "Một chiếc váy dài màu xám tím, gấu xắn lên tránh nước muối, màu của mái nhà kinh đô dưới mưa.", "Rok panjang ungu kelabu, ujungnya diselipkan agar tak kena air garam, warna atap ibu kota saat hujan.", "กระโปรงยาวสีเทาอมม่วง เหน็บชายขึ้นกันน้ำเกลือ สีเดียวกับหลังคาเมืองหลวงยามฝนตก", "Tuzlu sudan korumak için eteği toplanmış mor-gri bir etek; başkentin yağmurdaki çatılarının rengi.", "Una saya gris violácea, recogida en el bajo por la salmuera, del color de los tejados de la capital bajo la lluvia.", "Uma saia cinza-violeta, arregaçada na barra por causa da salmoura, da cor dos telhados da capital na chuva.", "Фиолетово-серая юбка, подоткнутая от рассола, цвета столичных крыш в дождь.", "Фіолетово-сіра спідниця, підіткнута від розсолу, кольору столичних дахів у дощ."],
  "A short violet mantle edged in white, as the port's citizens wear to the Salt-House when they're called. They are called often.": ["白で縁取った短い紫のマント。港の市民が塩館に呼ばれたときに着ていく。彼らはよく呼ばれる。", "흰 테를 두른 짧은 보랏빛 망토. 항구 시민들이 소금관에 불려 갈 때 입는다. 그들은 자주 불려 간다.", "一件白边的紫色短斗篷,港口的市民被传唤到盐务所时穿。他们常被传唤。", "一件白邊的紫色短斗篷,港口的市民被傳喚到鹽務所時穿。他們常被傳喚。", "Một chiếc áo khoác ngoài ngắn màu tím viền trắng, dân cảng mặc khi bị gọi tới Nhà Muối. Họ bị gọi thường xuyên.", "Mantel ungu pendek bertepi putih, dipakai warga pelabuhan saat dipanggil ke Rumah Garam. Mereka sering dipanggil.", "เสื้อคลุมไหล่สีม่วงสั้นขลิบขาว ที่ชาวเมืองท่าสวมไปโรงเกลือเมื่อถูกเรียกตัว พวกเขาถูกเรียกบ่อย", "Beyaz kenarlı kısa mor bir pelerin; liman halkı Tuz Evi'ne çağrıldığında giyer. Sık çağrılırlar.", "Un manto violeta corto ribeteado de blanco, el que llevan los vecinos del puerto a la Casa de la Sal cuando los citan. Los citan a menudo.", "Um manto violeta curto debruado de branco, o que os cidadãos do porto usam na Casa do Sal quando são chamados. São chamados com frequência.", "Короткая фиолетовая накидка с белой каймой; её надевают горожане порта, когда их вызывают в Соляной дом. Вызывают их часто.", "Коротка фіолетова накидка з білою облямівкою; її вдягають городяни порту, коли їх викликають до Соляного дому. Викликають їх часто."],
  "Wooden-soled boots for walking the dikes between the pans, rimed white to the ankle.": ["塩田のあいだの堤を歩くための木底の長靴。足首まで白く塩が吹いている。", "염전 사이 둑을 걷기 위한 나무 밑창 장화. 발목까지 하얗게 소금이 앉았다.", "木底靴,用来在盐田间的堤埂上走,脚踝以下结了一层白霜似的盐。", "木底靴,用來在鹽田間的堤埂上走,腳踝以下結了一層白霜似的鹽。", "Ủng đế gỗ để đi trên bờ đê giữa các ô ruộng muối, trắng muối tới mắt cá.", "Sepatu bot bersol kayu untuk berjalan di pematang antara petak garam, putih berkerak sampai mata kaki.", "รองเท้าบูตพื้นไม้สำหรับเดินบนคันกั้นระหว่างนาเกลือ ขาวด้วยเกลือถึงข้อเท้า", "Tuzlalar arasındaki setlerde yürümek için tahta tabanlı çizmeler, bileğe kadar beyaz kırağılı.", "Botas de suela de madera para andar por los diques entre las salinas, escarchadas de blanco hasta el tobillo.", "Botas de sola de madeira para andar nos diques entre as salinas, cobertas de branco até o tornozelo.", "Сапоги на деревянной подошве для ходьбы по дамбам меж бассейнов, белые от соли до щиколотки.", "Чоботи на дерев'яній підошві для ходіння дамбами між басейнами, білі від солі до кісточки."],
  "A sea-green cloth wound close over the hair, the tail tucked in so it can't catch on the reef. Merrab wears it on land too, out of habit and pride.": ["髪にぴったり巻いた海緑の布。端は岩礁に引っかからないよう押し込んである。メラブでは陸でも、習慣と誇りから巻いている。", "머리카락 위로 바짝 감은 바다빛 초록 천. 끝자락은 암초에 걸리지 않게 안으로 접어 넣었다. 메라브 사람들은 뭍에서도 습관과 자부심으로 두른다.", "一块海绿色的布紧紧缠在头发上,尾端掖进去,免得钩在礁石上。梅拉布人上了岸也照样缠,出于习惯,也出于骄傲。", "一塊海綠色的布緊緊纏在頭髮上,尾端掖進去,免得鉤在礁石上。梅拉布人上了岸也照樣纏,出於習慣,也出於驕傲。", "Một tấm vải xanh biển quấn sát tóc, đuôi giắt vào để không vướng đá ngầm. Người Merrab đội cả trên bờ, vì thói quen và niềm tự hào.", "Kain hijau laut dililit rapat di rambut, ujungnya diselipkan agar tak tersangkut karang. Orang Merrab memakainya di darat juga, karena kebiasaan dan kebanggaan.", "ผ้าสีเขียวน้ำทะเลพันแนบผม เหน็บชายไว้ไม่ให้เกี่ยวแนวปะการัง ชาวเมอร์รับสวมบนบกด้วย ด้วยความเคยชินและความภูมิใจ", "Saçın üstüne sıkıca sarılmış deniz yeşili bir bez, ucu resife takılmasın diye içe sokulmuş. Merrab onu karada da takar; alışkanlıktan ve gururdan.", "Un paño verde mar ceñido sobre el pelo, con la punta metida para que no se enganche en el arrecife. En Merrab lo llevan también en tierra, por costumbre y por orgullo.", "Um pano verde-mar enrolado rente ao cabelo, com a ponta enfiada para não prender no recife. Em Merrab usam-no também em terra, por hábito e orgulho.", "Ткань цвета морской волны, плотно обмотанная вокруг волос, конец заправлен, чтобы не зацепился за риф. В Меррабе её носят и на суше, по привычке и из гордости.", "Тканина кольору морської хвилі, щільно обмотана довкола волосся, кінець заправлено, щоб не зачепився за риф. У Меррабі її носять і на суші, за звичкою та з гордості."],
  "A long wrap of light cotton, white for the sun, a sea-green band at the hem for the harbour.": ["軽い木綿の長い巻衣。日差しに白、裾には港の海緑の帯。", "가벼운 무명으로 만든 긴 두름옷. 햇볕을 위해 흰색이고, 단에는 항구를 위한 바다빛 초록 띠가 있다.", "一件轻薄棉布的长裹袍,白色挡日头,下摆一道海绿色的边代表港口。", "一件輕薄棉布的長裹袍,白色擋日頭,下擺一道海綠色的邊代表港口。", "Một tấm áo quấn dài bằng vải bông nhẹ, trắng để tránh nắng, một dải xanh biển ở gấu cho bến cảng.", "Kain lilit panjang dari katun tipis, putih untuk matahari, dengan pita hijau laut di ujung untuk pelabuhan.", "ผ้าพันกายยาวผ้าฝ้ายบาง สีขาวกันแดด แถบสีเขียวน้ำทะเลที่ชายผ้าแทนท่าเรือ", "Hafif pamuktan uzun bir sargı; güneş için beyaz, liman için eteğinde deniz yeşili bir şerit.", "Una larga envoltura de algodón ligero, blanca por el sol, con una franja verde mar en el bajo por el puerto.", "Um longo manto de algodão leve, branco por causa do sol, com uma faixa verde-mar na barra pelo porto.", "Длинная накидка из лёгкого хлопка, белая от солнца, с полосой цвета морской волны по подолу в честь гавани.", "Довга накидка з легкої бавовни, біла від сонця, зі смугою кольору морської хвилі по подолу на честь гавані."],
  "Loose indigo trousers gathered at the ankle, salt-faded at the knee from kneeling on the quay to sort the shells.": ["足首ですぼめたゆったりした藍のズボン。岸壁にひざまずいて貝を選り分けるので、膝が塩で色褪せている。", "발목에서 오므린 헐렁한 쪽빛 바지. 부두에 무릎 꿇고 조개를 고르느라 무릎이 소금에 바랬다.", "宽松的靛蓝长裤,裤脚在脚踝处收紧,膝盖因为常跪在码头上挑贝壳而被盐褪了色。", "寬鬆的靛藍長褲,褲腳在腳踝處收緊,膝蓋因為常跪在碼頭上挑貝殼而被鹽褪了色。", "Quần chàm rộng túm ở mắt cá, đầu gối bạc màu muối vì quỳ trên bến lựa vỏ sò.", "Celana nila longgar dikerut di mata kaki, lututnya pudar oleh garam karena berlutut di dermaga memilah kerang.", "กางเกงครามหลวมรวบที่ข้อเท้า เข่าซีดด้วยเกลือจากการคุกเข่าบนท่าเรือคัดหอย", "Bilekte büzülen bol çivit şalvar; rıhtımda diz çöküp kabuk ayıklamaktan dizleri tuzdan solmuş.", "Pantalones añil holgados, fruncidos en el tobillo, desteñidos de sal en la rodilla de arrodillarse en el muelle a clasificar conchas.", "Calças anil folgadas, franzidas no tornozelo, desbotadas de sal no joelho de tanto ajoelhar no cais para separar as conchas.", "Свободные штаны цвета индиго, собранные у щиколотки, выцветшие от соли на коленях: на причале раковины сортируют на коленях.", "Вільні штани кольору індиго, зібрані біля кісточки, вигорілі від солі на колінах: на причалі мушлі сортують навколішки."],
  "A mantle dyed with the blue the divers say is the colour of the beds at noon, ten fathoms down.": ["潜り手たちが、真昼に十尋の深さで見る真珠床の色だという青で染めたマント。", "잠수부들이 한낮에 열 길 아래 진주밭의 빛깔이라 말하는 파랑으로 물들인 망토.", "一件斗篷,染成潜水人口中正午时十寻深处珠床的那种蓝。", "一件斗篷,染成潛水人口中正午時十尋深處珠床的那種藍。", "Một áo khoác ngoài nhuộm màu xanh mà thợ lặn bảo là màu bãi ngọc lúc giữa trưa, sâu mười sải.", "Mantel dicelup biru yang menurut para penyelam adalah warna dasar laut di siang hari, sepuluh depa di bawah.", "เสื้อคลุมไหล่ย้อมด้วยสีน้ำเงินที่นักดำน้ำว่าเป็นสีของแหล่งหอยมุกยามเที่ยง ลึกลงไปสิบวา", "Dalgıçların öğlen vakti on kulaç derinde yatakların rengi dediği maviyle boyanmış bir pelerin.", "Un manto teñido del azul que, dicen los buceadores, tienen los bancos a mediodía, a diez brazas de profundidad.", "Um manto tingido do azul que, dizem os mergulhadores, têm os bancos ao meio-dia, a dez braças de fundo.", "Накидка, окрашенная в ту синеву, какая, по словам ныряльщиков, у отмелей в полдень на глубине десяти саженей.", "Накидка, пофарбована в ту синь, яка, за словами пірнальників, у мілин опівдні на глибині десяти сажнів."],
  "Sandals plaited from shore reeds, light enough to swim in, cheap enough to lose.": ["浜の葦で編んだサンダル。履いたまま泳げるほど軽く、なくしても惜しくないほど安い。", "바닷가 갈대로 엮은 샌들. 신은 채 헤엄칠 만큼 가볍고, 잃어버려도 될 만큼 싸다.", "用海边芦苇编的凉鞋,轻得能穿着游泳,便宜得丢了也不心疼。", "用海邊蘆葦編的涼鞋,輕得能穿著游泳,便宜得丟了也不心疼。", "Dép bện từ sậy bờ biển, nhẹ đủ để bơi, rẻ đủ để đánh mất.", "Sandal anyaman alang-alang pantai, cukup ringan untuk berenang, cukup murah untuk hilang.", "รองเท้าแตะสานจากต้นอ้อริมฝั่ง เบาพอจะสวมว่ายน้ำ ถูกพอจะทำหาย", "Kıyı kamışından örülmüş sandaletler; içinde yüzecek kadar hafif, kaybedecek kadar ucuz.", "Sandalias trenzadas con juncos de la orilla, lo bastante ligeras para nadar con ellas y lo bastante baratas para perderlas.", "Sandálias trançadas com junco da praia, leves o bastante para nadar e baratas o bastante para perder.", "Сандалии, сплетённые из прибрежного тростника: в них можно плавать, их не жалко потерять.", "Сандалі, сплетені з прибережного очерету: у них можна плавати, їх не шкода загубити."],
  "A fisher by daylight, in a gansey with the pattern unpicked so nobody can say whose. By night, someone who hangs a lantern where a lantern shouldn't be.": ["昼は漁師。誰のものか分からないよう模様をほどいたガンジーを着ている。夜は、ランタンがあってはならない場所にランタンを吊るす者。", "낮에는 어부. 누구 것인지 모르게 무늬를 풀어 버린 건지 스웨터를 입었다. 밤에는 등불이 있어서는 안 될 곳에 등불을 거는 자.", "白天是渔民,穿着拆掉了花纹的渔夫毛衣,谁也认不出是哪家的。夜里,则是把灯笼挂在不该挂的地方的人。", "白天是漁民,穿著拆掉了花紋的漁夫毛衣,誰也認不出是哪家的。夜裡,則是把燈籠掛在不該掛的地方的人。", "Ban ngày là dân chài, mặc áo gansey đã tháo hoa văn để không ai biết của nhà nào. Ban đêm, là kẻ treo đèn lồng ở nơi không nên có đèn.", "Nelayan di siang hari, bersweter gansey yang polanya dibongkar agar tak ada yang tahu milik siapa. Di malam hari, orang yang menggantung lentera di tempat yang tak semestinya.", "ชาวประมงยามกลางวัน สวมเสื้อแกนซีที่เลาะลายออกจนไม่มีใครบอกได้ว่าของใคร ยามค่ำคืน คือคนที่แขวนตะเกียงไว้ในที่ที่ไม่ควรมีตะเกียง", "Gündüz bir balıkçı; deseni sökülmüş, kimin olduğu anlaşılmayan bir gansey giyer. Gece ise fenerin olmaması gereken yere fener asan biri.", "Pescador de día, con un gansey al que le han deshecho el dibujo para que nadie sepa de quién es. De noche, alguien que cuelga un farol donde no debería haberlo.", "Pescador de dia, com um gansey de padrão desmanchado para ninguém saber de quem é. De noite, alguém que pendura uma lanterna onde não deveria haver uma.", "Днём рыбак в гернси с распущенным узором, чтобы никто не понял, чей он. Ночью — тот, кто вешает фонарь там, где фонаря быть не должно.", "Удень рибалка в гернсі з розпущеним візерунком, щоб ніхто не зрозумів, чий він. Уночі — той, хто вішає ліхтар там, де ліхтаря бути не повинно."],
  "Nan Tregellas's son, with a lantern hook in one hand and a gutting knife in the other. He stopped paying the customs house's dues and started collecting them back, off the rocks.": ["ナン・トレゲラスの息子。片手にランタンの鉤、もう片手に魚をさばく小刀。税関の税を払うのをやめ、岩場から取り立て返しはじめた。", "낸 트레겔라스의 아들. 한 손에는 등불 갈고리, 다른 손에는 생선 손질 칼. 세관의 세금을 내지 않기 시작하더니, 바위에서 도로 거두어들이기 시작했다.", "南·特雷盖拉斯的儿子,一手拿着挂灯钩,一手拿着剖鱼刀。他不再缴海关的税,开始从礁石上把钱收回来。", "南·特雷蓋拉斯的兒子,一手拿著掛燈鉤,一手拿著剖魚刀。他不再繳海關的稅,開始從礁石上把錢收回來。", "Con trai của Nan Tregellas, một tay cầm móc đèn, tay kia cầm dao mổ cá. Anh ta thôi nộp thuế cho nhà hải quan và bắt đầu thu lại, từ đá ngầm.", "Putra Nan Tregellas, kait lentera di satu tangan dan pisau pembelah ikan di tangan lain. Ia berhenti membayar bea kantor bea cukai dan mulai menagihnya kembali, dari karang.", "ลูกชายของแนน เทรเกลลัส มือหนึ่งถือขอแขวนตะเกียง อีกมือถือมีดผ่าปลา เขาเลิกจ่ายค่าธรรมเนียมให้ศุลกสถาน แล้วเริ่มเก็บคืนจากโขดหิน", "Nan Tregellas'ın oğlu; bir elinde fener kancası, ötekinde balık temizleme bıçağı. Gümrüğün vergilerini ödemeyi bırakıp onları kayalardan geri toplamaya başladı.", "El hijo de Nan Tregellas, con un gancho de farol en una mano y un cuchillo de destripar en la otra. Dejó de pagar los derechos de la aduana y empezó a cobrárselos de vuelta, en las rocas.", "O filho de Nan Tregellas, com um gancho de lanterna numa mão e uma faca de estripar na outra. Deixou de pagar as taxas da alfândega e começou a cobrá-las de volta, nas rochas.", "Сын Нэн Трегеллас, в одной руке крюк для фонаря, в другой — разделочный нож. Он перестал платить таможенные сборы и начал собирать их обратно, со скал.", "Син Нен Трегеллас, в одній руці гак для ліхтаря, в другій — ніж для патрання. Він перестав сплачувати митні збори й почав збирати їх назад, зі скель."],
  "A sea crocodile as long as a diving boat, barnacled along the back, one eye white with an old spear-scar. It has learnt that the divers come up tired.": ["潜水船ほどの長さのある海ワニ。背中はフジツボだらけで、片目は古い銛の傷で白く濁っている。潜り手が疲れて上がってくることを覚えてしまった。", "잠수선만큼 긴 바다 악어. 등에는 따개비가 붙었고, 한쪽 눈은 오래된 작살 흉터로 하얗다. 잠수부들이 지쳐서 올라온다는 걸 알아 버렸다.", "一条海鳄,和潜水船一样长,背上长满藤壶,一只眼睛因为旧矛伤而发白。它已经学会了:潜水人上来时都累了。", "一條海鱷,和潛水船一樣長,背上長滿藤壺,一隻眼睛因為舊矛傷而發白。它已經學會了:潛水人上來時都累了。", "Một con cá sấu biển dài như chiếc thuyền lặn, lưng bám đầy hà, một mắt trắng đục vì vết lao cũ. Nó đã biết rằng thợ lặn ngoi lên lúc mệt.", "Buaya laut sepanjang perahu selam, punggungnya bertritip, satu matanya putih karena bekas luka tombak lama. Ia sudah belajar bahwa para penyelam naik dalam keadaan lelah.", "จระเข้ทะเลยาวพอๆ กับเรือดำน้ำหามุก หลังมีเพรียงเกาะ ตาข้างหนึ่งขาวด้วยแผลหอกเก่า มันเรียนรู้แล้วว่านักดำน้ำขึ้นมาตอนเหนื่อย", "Bir dalış teknesi boyunda, sırtı midyeli, bir gözü eski bir zıpkın yarasıyla beyazlamış bir deniz timsahı. Dalgıçların yorgun çıktığını öğrenmiş.", "Un cocodrilo de mar tan largo como una barca de buceo, con percebes en el lomo y un ojo blanco por una vieja cicatriz de arpón. Ha aprendido que los buceadores suben cansados.", "Um crocodilo-marinho tão comprido quanto um barco de mergulho, com cracas no dorso e um olho branco de uma velha cicatriz de arpão. Aprendeu que os mergulhadores sobem cansados.", "Морской крокодил длиной с ныряльную лодку, в морских жёлудях по хребту, один глаз белый от старого шрама от остроги. Он усвоил, что ныряльщики поднимаются усталыми.", "Морський крокодил завдовжки з пірнальний човен, у морських жолудях по хребту, одне око біле від старого шраму від остроги. Він засвоїв, що пірнальники виринають утомленими."],
  "A long, many-legged thing armoured in plates the colour of the dunes, that tunnels toward the smell of water and leaves sand behind it wherever it's been.": ["砂丘の色をした甲殻に覆われた、脚の多い長い生き物。水の匂いに向かってトンネルを掘り、通った跡にはどこでも砂を残す。", "모래 언덕 빛깔의 판갑을 두른 길고 다리 많은 것. 물 냄새를 향해 굴을 파고, 지나간 곳마다 모래를 남긴다.", "一种细长多足的东西,披着沙丘颜色的甲片,循着水的气味钻洞,走到哪儿就在哪儿留下沙子。", "一種細長多足的東西,披著沙丘顏色的甲片,循著水的氣味鑽洞,走到哪兒就在哪兒留下沙子。", "Một sinh vật dài, nhiều chân, bọc giáp màu cồn cát, đào hầm về phía mùi nước và để lại cát ở mọi nơi nó đi qua.", "Makhluk panjang berkaki banyak berlapis pelat sewarna bukit pasir, menggali terowongan ke arah bau air dan meninggalkan pasir di mana pun ia lewat.", "สิ่งมีชีวิตยาวขาเยอะ หุ้มเกราะแผ่นสีเนินทราย ขุดอุโมงค์ไปตามกลิ่นน้ำ และทิ้งทรายไว้ทุกที่ที่มันผ่าน", "Kumul renginde plakalarla zırhlanmış, uzun, çok bacaklı bir şey; suyun kokusuna doğru tünel kazar, geçtiği her yerde arkasında kum bırakır.", "Una cosa larga y de muchas patas, acorazada con placas del color de las dunas, que excava hacia el olor del agua y deja arena allí por donde pasa.", "Uma coisa comprida e de muitas patas, blindada com placas da cor das dunas, que escava em direção ao cheiro de água e deixa areia por onde passa.", "Длинная многоногая тварь в пластинах цвета дюн, что роет ходы на запах воды и оставляет песок везде, где проползла.", "Довга багатонога тварюка в пластинах кольору дюн, що риє ходи на запах води й лишає пісок усюди, де проповзла."],
  "Gullwick's harbourmaster: berths, tides, quarrels and the lighthouse, all hers. She has a voice for shouting across water and uses it indoors.": ["ガルウィックの港長。停泊場所も潮も喧嘩も灯台も、すべて彼女の管轄。水の向こうへ怒鳴るための声を持ち、それを屋内でも使う。", "걸윅의 항만장. 정박지, 조수, 다툼, 등대까지 모두 그녀 소관이다. 물 건너로 소리칠 목청을 가졌고, 그걸 실내에서도 쓴다.", "鸥湾的港务长:泊位、潮汐、争吵和灯塔,全归她管。她有一副隔着水面喊话的嗓子,在屋里也照用不误。", "鷗灣的港務長:泊位、潮汐、爭吵和燈塔,全歸她管。她有一副隔著水面喊話的嗓子,在屋裡也照用不誤。", "Trưởng cảng Gullwick: bến đậu, thủy triều, cãi vã và ngọn hải đăng, tất cả là của bà. Bà có giọng để quát qua mặt nước và dùng nó cả trong nhà.", "Syahbandar Gullwick: tambatan, pasang surut, pertengkaran, dan mercusuar, semuanya urusannya. Suaranya dibuat untuk berteriak melintasi air dan ia memakainya di dalam ruangan.", "นายท่าแห่งกัลวิก: ท่าจอด น้ำขึ้นน้ำลง การทะเลาะ และประภาคาร เป็นของเธอทั้งหมด เธอมีเสียงไว้ตะโกนข้ามน้ำ และใช้มันในบ้านด้วย", "Gullwick'in liman reisi: rıhtımlar, gelgitler, kavgalar ve fener, hepsi onun. Suyun öte yanına bağırmak için bir sesi var ve onu içeride de kullanır.", "La capitana de puerto de Gullwick: atraques, mareas, riñas y el faro, todo suyo. Tiene voz para gritar de una orilla a otra y la usa bajo techo.", "A capitã do porto de Gullwick: atracações, marés, brigas e o farol, tudo dela. Tem voz para gritar de uma margem a outra e a usa dentro de casa.", "Начальница порта Галлвика: причалы, приливы, ссоры и маяк — всё на ней. У неё голос, чтобы кричать через воду, и она пользуется им в помещении.", "Начальниця порту Галлвіка: причали, припливи, сварки й маяк — усе на ній. Має голос, щоб кричати через воду, і користується ним у приміщенні."],
  "Collector of the port's dues, in a good black coat and a worse temper. The harbour wall is falling into the sea, he says, and the sea doesn't pay dues.": ["港の税を取り立てる徴税官。上等の黒い上着に、それ以上の不機嫌。港の防波堤が海に崩れ落ちている、と彼は言う。そして海は税を払わない。", "항구 세금을 거두는 징수관. 좋은 검은 외투에 그보다 나쁜 성미. 항구 방벽이 바다로 무너지고 있다고 그는 말한다. 그리고 바다는 세금을 내지 않는다고.", "港口税费的税务官,穿着体面的黑外套,脾气比外套还冲。他说,港口的防波墙正在往海里塌,而大海可不交税。", "港口稅費的稅務官,穿著體面的黑外套,脾氣比外套還衝。他說,港口的防波牆正在往海裡塌,而大海可不交稅。", "Quan thu thuế của cảng, mặc áo khoác đen tốt và tính khí tệ hơn. Ông nói tường cảng đang đổ xuống biển, và biển thì không nộp thuế.", "Pemungut bea pelabuhan, bermantel hitam bagus dan berwatak lebih buruk. Tembok pelabuhan runtuh ke laut, katanya, dan laut tidak membayar bea.", "เจ้าพนักงานเก็บค่าธรรมเนียมท่าเรือ สวมเสื้อคลุมดำอย่างดีกับอารมณ์ที่แย่กว่า เขาว่ากำแพงท่าเรือกำลังพังลงทะเล และทะเลไม่จ่ายค่าธรรมเนียม", "Limanın vergi tahsildarı; iyi bir siyah palto, daha kötü bir huy. Liman duvarı denize çöküyor, der, ve deniz vergi ödemez.", "El recaudador de los derechos del puerto, con un buen abrigo negro y peor genio. El muro del puerto se está cayendo al mar, dice, y el mar no paga derechos.", "O coletor das taxas do porto, num bom casaco preto e de pior humor. O muro do porto está caindo no mar, diz ele, e o mar não paga taxas.", "Сборщик портовых сборов в хорошем чёрном сюртуке и с характером похуже. Портовая стена рушится в море, говорит он, а море сборов не платит.", "Збирач портових зборів у доброму чорному сюртуку й із гіршою вдачею. Портова стіна обвалюється в море, каже він, а море зборів не сплачує."],
  "Keeper of Gullwick Light for thirty years, salt-white of beard and soot-black of hand. He has not let the lamp go out once in thirty years, he says, until this month.": ["三十年ガルウィック灯台を守ってきた男。ひげは塩のように白く、手は煤で黒い。三十年一度も灯を消したことはない、と彼は言う。今月までは。", "삼십 년 동안 걸윅 등대를 지켜 온 사람. 수염은 소금처럼 희고 손은 그을음처럼 검다. 삼십 년 동안 한 번도 불을 꺼뜨린 적이 없다고 그는 말한다. 이번 달 전까지는.", "守了鸥湾灯塔三十年,胡子白得像盐,手黑得像煤灰。他说三十年来他一次也没让灯灭过,直到这个月。", "守了鷗灣燈塔三十年,鬍子白得像鹽,手黑得像煤灰。他說三十年來他一次也沒讓燈滅過,直到這個月。", "Người giữ Đèn biển Gullwick ba mươi năm, râu trắng như muối, tay đen như bồ hóng. Ông nói ba mươi năm chưa để đèn tắt lần nào, cho tới tháng này.", "Penjaga Mercusuar Gullwick selama tiga puluh tahun, berjanggut putih garam dan bertangan hitam jelaga. Tak sekali pun ia membiarkan lampu padam dalam tiga puluh tahun, katanya, sampai bulan ini.", "ผู้เฝ้าประภาคารกัลวิกมาสามสิบปี เคราขาวดั่งเกลือ มือดำดั่งเขม่า เขาว่าไม่เคยปล่อยให้ตะเกียงดับเลยสักครั้งในสามสิบปี จนกระทั่งเดือนนี้", "Otuz yıldır Gullwick Feneri'nin bekçisi; sakalı tuz beyazı, eli is karası. Otuz yılda lambanın bir kez bile sönmesine izin vermedi, der, bu aya kadar.", "Farero del faro de Gullwick desde hace treinta años, de barba blanca como la sal y manos negras de hollín. No ha dejado que la lámpara se apague ni una vez en treinta años, dice, hasta este mes.", "Faroleiro do farol de Gullwick há trinta anos, de barba branca como sal e mãos negras de fuligem. Não deixou a lâmpada se apagar uma única vez em trinta anos, diz ele, até este mês.", "Смотритель Галлвикского маяка уже тридцать лет, борода белая от соли, руки чёрные от копоти. За тридцать лет он ни разу не дал огню погаснуть, говорит он, до этого месяца.", "Доглядач Галлвіцького маяка вже тридцять років, борода біла від солі, руки чорні від кіптяви. За тридцять років він жодного разу не дав вогню згаснути, каже він, до цього місяця."],
  "Keeps the Gull and Lantern, and the harbour's news, and a stew that has been going in the same pot since her mother's day.": ["カモメとランタン亭を切り盛りし、港の噂も握り、母の代から同じ鍋で煮つづけているシチューも守っている。", "갈매기와 등불을 꾸리고, 항구 소식도 쥐고 있으며, 어머니 대부터 같은 냄비에서 끓여 온 스튜도 지킨다.", "经营“海鸥与灯笼”,掌握港口的消息,还守着一锅从她母亲那辈起就在同一口锅里炖着的炖菜。", "經營「海鷗與燈籠」,掌握港口的消息,還守著一鍋從她母親那輩起就在同一口鍋裡燉著的燉菜。", "Trông quán Hải Âu và Đèn Lồng, cùng tin tức của bến cảng, và một nồi hầm sôi trong cùng một nồi từ thời mẹ bà.", "Mengurus Camar dan Lentera, kabar pelabuhan, dan semur yang mendidih di panci yang sama sejak zaman ibunya.", "ดูแลนกนางนวลกับตะเกียง ข่าวของท่าเรือ และสตูว์ที่เคี่ยวอยู่ในหม้อใบเดิมมาตั้งแต่สมัยแม่ของเธอ", "Martı ve Fener'i, limanın haberlerini ve annesinin zamanından beri aynı tencerede kaynayan bir yahniyi işletir.", "Lleva La Gaviota y el Farol, las noticias del puerto y un guiso que lleva hirviendo en la misma olla desde los tiempos de su madre.", "Cuida da Gaivota e a Lanterna, das notícias do porto e de um ensopado que ferve na mesma panela desde o tempo da mãe dela.", "Держит «Чайку и фонарь», портовые новости и похлёбку, что варится в одном и том же котле со времён её матери.", "Тримає «Чайку і ліхтар», портові новини й юшку, що вариться в тому самому казані ще з часів її матері."],
  "Gullwick's chandler: rope, tar, oil, hooks and floats, and the price of all of them by heart.": ["ガルウィックの船具商。縄、タール、油、釣り針、浮き、そのすべての値段をそらんじている。", "걸윅의 선구상. 밧줄, 타르, 기름, 낚싯바늘, 부표, 그리고 그 모든 값을 외우고 있다.", "鸥湾的船具商:绳子、沥青、油、鱼钩、浮子,样样的价钱都记在心里。", "鷗灣的船具商:繩子、瀝青、油、魚鉤、浮子,樣樣的價錢都記在心裡。", "Người bán đồ tàu ở Gullwick: dây thừng, nhựa đường, dầu, lưỡi câu và phao, và thuộc lòng giá của tất cả.", "Pedagang perlengkapan kapal Gullwick: tali, ter, minyak, kail dan pelampung, dan hafal harga semuanya.", "พ่อค้าอุปกรณ์เรือแห่งกัลวิก: เชือก น้ำมันดิน น้ำมัน เบ็ด ทุ่น และจำราคาทุกอย่างได้ขึ้นใจ", "Gullwick'in gemi malzemecisi: ip, katran, yağ, olta iğneleri ve şamandıralar, hepsinin fiyatı ezberinde.", "El cordelero de Gullwick: cuerda, brea, aceite, anzuelos y flotadores, y el precio de todo de memoria.", "O fornecedor náutico de Gullwick: corda, piche, óleo, anzóis e boias, e o preço de tudo de cor.", "Судовой лавочник Галлвика: верёвка, дёготь, масло, крючки и поплавки, и цены на всё — наизусть.", "Судновий крамар Галлвіка: мотузка, дьоготь, олія, гачки й поплавці, і ціни на все — напам'ять."],
  "Sells the morning's catch off the quay, guts it faster than you can point at it, and knows which boat every fish came off.": ["朝の漁獲を岸壁で売る。指さすより早くさばき、どの魚がどの船から揚がったかを知っている。", "아침 어획을 부두에서 판다. 가리키기도 전에 손질을 끝내고, 생선마다 어느 배에서 왔는지 안다.", "在码头上卖早上的渔获,你手指还没指过去她就剖好了,每条鱼是哪条船上的她都知道。", "在碼頭上賣早上的漁獲,你手指還沒指過去她就剖好了,每條魚是哪條船上的她都知道。", "Bán mẻ cá buổi sáng ngay trên bến, mổ nhanh hơn bạn kịp chỉ tay, và biết từng con cá từ thuyền nào.", "Menjual tangkapan pagi di dermaga, membelahnya lebih cepat daripada kau menunjuk, dan tahu dari perahu mana tiap ikan.", "ขายปลาที่จับได้ยามเช้าบนท่าเรือ ควักไส้เร็วกว่าที่คุณจะชี้ทัน และรู้ว่าปลาทุกตัวมาจากเรือลำไหน", "Sabahın avını rıhtımda satar, sen gösterene kadar temizler ve her balığın hangi tekneden çıktığını bilir.", "Vende la pesca de la mañana en el muelle, la destripa antes de que la señales y sabe de qué barca salió cada pez.", "Vende o pescado da manhã no cais, estripa-o mais rápido do que você aponta e sabe de que barco saiu cada peixe.", "Продаёт утренний улов прямо с причала, потрошит быстрее, чем ты укажешь пальцем, и знает, с какой лодки каждая рыба.", "Продає ранковий улов просто з причалу, патрає швидше, ніж ти вкажеш пальцем, і знає, з якого човна кожна риба."],
  "Lays rope in the ropewalk, walking backwards the length of the shed all day. He has walked to Saltmarrow and back, he says, without leaving Gullwick.": ["縄打ち場で縄をなう。一日じゅう小屋の端から端まで後ろ向きに歩く。ガルウィックを出ないまま、ソルトマロウまで行って帰ってきた、と彼は言う。", "밧줄 공방에서 밧줄을 꼰다. 하루 종일 창고 끝에서 끝까지 뒷걸음질한다. 걸윅을 떠나지 않고도 솔트매로까지 다녀왔다고 그는 말한다.", "在制绳场搓绳,整天倒着从棚子这头走到那头。他说,自己没出鸥湾一步,却已经走到盐髓港又走回来了。", "在製繩場搓繩,整天倒著從棚子這頭走到那頭。他說,自己沒出鷗灣一步,卻已經走到鹽髓港又走回來了。", "Bện thừng trong xưởng, cả ngày đi lùi dọc chiều dài lán. Ông nói đã đi tới Saltmarrow rồi về mà không rời Gullwick.", "Memilin tali di lorong tali, berjalan mundur sepanjang gudang seharian. Ia sudah berjalan ke Saltmarrow dan kembali, katanya, tanpa meninggalkan Gullwick.", "ฟั่นเชือกในโรงฟั่นเชือก เดินถอยหลังตลอดความยาวโรงทั้งวัน เขาว่าเดินไปซอลต์แมร์โรว์แล้วกลับมาโดยไม่ได้ออกจากกัลวิกเลย", "Halat yolunda halat büker, bütün gün barakanın boyunca geri geri yürür. Gullwick'ten çıkmadan Saltmarrow'a gidip geldiğini söyler.", "Tuerce cuerda en la cordelería, caminando hacia atrás todo el largo del cobertizo durante el día entero. Ha ido a Saltmarrow y vuelto, dice, sin salir de Gullwick.", "Torce corda na cordoaria, andando de costas pelo comprimento do galpão o dia inteiro. Já foi a Saltmarrow e voltou, diz ele, sem sair de Gullwick.", "Вьёт канаты на канатной дорожке, весь день шагая задом наперёд по всей длине сарая. Он, говорит, дошёл до Солтмэрроу и обратно, не покидая Галлвика.", "В'є канати на канатній доріжці, увесь день крокуючи задки на всю довжину сараю. Він, каже, дійшов до Солтмерроу й назад, не покидаючи Галлвіка."],
  "Sells oilskins and knits ganseys, each in its family's pattern. She can tell you whose son you are by your jersey.": ["油布服を売り、家ごとの模様でガンジーを編む。セーターを見れば、あなたが誰の息子か言い当てられる。", "방수복을 팔고 집안마다의 무늬로 건지 스웨터를 뜬다. 스웨터만 보고도 네가 누구 아들인지 말할 수 있다.", "卖油布衣,织渔夫毛衣,每件都照各家的花纹。看你的毛衣,她就能说出你是谁家的儿子。", "賣油布衣,織漁夫毛衣,每件都照各家的花紋。看你的毛衣,她就能說出你是誰家的兒子。", "Bán áo dầu và đan áo gansey, mỗi chiếc theo hoa văn của một nhà. Nhìn áo len, bà nói được bạn là con nhà ai.", "Menjual jas minyak dan merajut sweter gansey, masing-masing dengan pola keluarganya. Ia bisa menebak kau anak siapa dari sweatermu.", "ขายเสื้อกันน้ำและถักเสื้อแกนซี แต่ละตัวตามลายของตระกูล เธอบอกได้ว่าคุณเป็นลูกใครจากเสื้อถักของคุณ", "Muşamba satar, her birini ailesinin deseninde gansey örer. Kazağına bakıp kimin oğlu olduğunu söyleyebilir.", "Vende impermeables y teje ganseys, cada uno con el dibujo de su familia. Por tu jersey sabe de quién eres hijo.", "Vende oleados e tricota ganseys, cada um no padrão da sua família. Pela sua camisola ela diz de quem você é filho.", "Продаёт непромокаемые плащи и вяжет гернси, каждый с узором своей семьи. По свитеру скажет, чей ты сын.", "Продає непромокальні плащі й в'яже гернсі, кожен із візерунком своєї родини. За светром скаже, чий ти син."],
  "A fisher's widow in a gansey too big for her, mending a net at her door. Her son's boat hasn't gone out in a month, and she has stopped saying why.": ["大きすぎるガンジーを着た漁師の未亡人。戸口で網を繕っている。息子の船はひと月出ておらず、彼女はもう理由を口にしなくなった。", "몸에 너무 큰 건지 스웨터를 입은 어부의 과부. 문간에서 그물을 깁고 있다. 아들의 배는 한 달째 나가지 않았고, 그녀는 이제 이유를 말하지 않는다.", "一个渔民的寡妇,穿着过大的渔夫毛衣,在门口补网。她儿子的船一个月没出海了,她也不再说为什么。", "一個漁民的寡婦,穿著過大的漁夫毛衣,在門口補網。她兒子的船一個月沒出海了,她也不再說為什麼。", "Một góa phụ dân chài mặc chiếc áo gansey quá rộng, ngồi vá lưới trước cửa. Thuyền của con trai bà đã một tháng không ra khơi, và bà thôi nói vì sao.", "Janda nelayan bersweter gansey yang kebesaran, menambal jala di pintunya. Perahu putranya sudah sebulan tak melaut, dan ia berhenti mengatakan sebabnya.", "หญิงม่ายชาวประมงในเสื้อแกนซีตัวใหญ่เกินตัว นั่งปะอวนที่หน้าประตู เรือของลูกชายเธอไม่ได้ออกทะเลมาเดือนหนึ่งแล้ว และเธอเลิกพูดว่าทำไม", "Kendisine fazla büyük bir gansey giymiş, kapısında ağ yamayan bir balıkçı dulu. Oğlunun teknesi bir aydır denize çıkmadı ve o nedenini söylemeyi bıraktı.", "La viuda de un pescador, con un gansey demasiado grande para ella, remendando una red en su puerta. La barca de su hijo no sale desde hace un mes, y ella ha dejado de decir por qué.", "A viúva de um pescador, num gansey grande demais para ela, remendando uma rede à porta. O barco do filho não sai há um mês, e ela parou de dizer por quê.", "Вдова рыбака в слишком большом для неё гернси чинит сеть у порога. Лодка её сына не выходит в море уже месяц, и она перестала говорить почему.", "Вдова рибалки в завеликому для неї гернсі латає сітку біля порога. Човен її сина не виходить у море вже місяць, і вона перестала казати чому."],
  "A fisher off one of the luggers, mending, baiting, or complaining about the dues, and sometimes all three.": ["ラガー船の漁師。網を繕うか、餌をつけるか、税に文句を言っている。三つ同時のこともある。", "러거선 어부. 그물을 깁거나, 미끼를 끼우거나, 세금 불평을 하거나, 가끔은 셋 다 한다.", "一条斜桁帆船上的渔民,不是补网、上饵,就是抱怨税费,有时三样一起来。", "一條斜桁帆船上的漁民,不是補網、上餌,就是抱怨稅費,有時三樣一起來。", "Một ngư dân trên chiếc lugger, đang vá lưới, móc mồi, hoặc than phiền về thuế, đôi khi cả ba.", "Nelayan dari salah satu perahu lugger, sedang menambal, memasang umpan, atau mengeluh soal bea, kadang ketiganya.", "ชาวประมงจากเรือลักเกอร์ลำหนึ่ง กำลังปะอวน ติดเหยื่อ หรือบ่นเรื่องค่าธรรมเนียม บางทีก็ทั้งสามอย่าง", "Lugger teknelerinden birinin balıkçısı; ağ yamar, yem takar ya da vergilerden yakınır, bazen üçünü birden.", "Un pescador de uno de los lugres, remendando, cebando o quejándose de los derechos, y a veces las tres cosas.", "Um pescador de um dos lugres, remendando, iscando ou reclamando das taxas, e às vezes as três coisas.", "Рыбак с одного из люгеров: чинит, наживляет или жалуется на сборы, а иногда всё сразу.", "Рибалка з одного з люгерів: латає, наживлює або скаржиться на збори, а часом усе одразу."],
  "One of the harbour watch, paid by the Collector, with a lantern, a cudgel and opinions about the Collector.": ["港の夜警の一人。徴税官に雇われ、ランタンと棍棒と、徴税官についての意見を持っている。", "항구 경비대원. 징수관에게 돈을 받으며, 등불과 몽둥이와 징수관에 대한 의견을 들고 다닌다.", "港口巡夜队的一员,由税务官付钱,带着灯笼、棍子,还有对税务官的看法。", "港口巡夜隊的一員,由稅務官付錢,帶著燈籠、棍子,還有對稅務官的看法。", "Một lính gác cảng, do Quan thu thuế trả lương, có đèn lồng, dùi cui và ý kiến về Quan thu thuế.", "Salah satu penjaga pelabuhan, dibayar Pemungut, membawa lentera, pentungan, dan pendapat tentang Pemungut.", "หนึ่งในยามท่าเรือ ได้ค่าจ้างจากเจ้าพนักงานเก็บภาษี มีตะเกียง กระบอง และความเห็นเกี่ยวกับเจ้าพนักงานเก็บภาษี", "Tahsildarın maaş verdiği liman nöbetçilerinden biri; bir fener, bir sopa ve Tahsildar hakkında fikirleri var.", "Uno de la guardia del puerto, pagado por el Recaudador, con un farol, un garrote y opiniones sobre el Recaudador.", "Um da guarda do porto, pago pelo Coletor, com uma lanterna, um porrete e opiniões sobre o Coletor.", "Один из портовой стражи: жалованье от сборщика, при нём фонарь, дубинка и мнение о сборщике.", "Один із портової варти: платня від збирача, при ньому ліхтар, кийок і думка про збирача."],
  "Someone of the harbour town in a navy gansey, smelling of the sea and saying so.": ["紺のガンジーを着た港町の人。潮の匂いがして、それを自分で言う。", "남색 건지 스웨터를 입은 항구 마을 사람. 바다 냄새가 나고, 스스로 그렇다고 말한다.", "港镇上的人,穿着藏青色渔夫毛衣,一身海味,还挂在嘴上。", "港鎮上的人,穿著藏青色漁夫毛衣,一身海味,還掛在嘴上。", "Một người ở thị trấn cảng mặc áo gansey xanh hải quân, nồng mùi biển và nói ra điều đó.", "Warga kota pelabuhan bersweter gansey biru tua, berbau laut dan mengatakannya.", "ชาวเมืองท่าในเสื้อแกนซีสีกรมท่า มีกลิ่นทะเลและพูดเองว่าอย่างนั้น", "Lacivert ganseyli, deniz kokan ve bunu söyleyen bir liman kasabası sakini.", "Alguien del pueblo del puerto con un gansey azul marino, que huele a mar y lo dice.", "Alguém da cidade portuária num gansey azul-marinho, cheirando a mar e dizendo isso.", "Житель портового городка в тёмно-синем гернси, пахнущий морем и сообщающий об этом.", "Мешканець портового містечка в темно-синьому гернсі, що пахне морем і про це повідомляє."],
  "The Crown's assessor at Saltreach, in violet and silver, the Ledger of Salt open on his arm. He weighs, he writes, and he has never once been wrong, in writing.": ["ソルトリーチにおける王冠の査定官。紫と銀をまとい、腕には塩の台帳を開いている。量り、記し、書面の上では一度たりとも間違えたことがない。", "솔트리치의 왕실 감정관. 보라와 은을 입고, 팔에 소금 장부를 펼쳐 들었다. 무게를 달고, 적고, 서면상으로는 한 번도 틀린 적이 없다.", "王室派驻盐滩港的估税官,一身紫与银,臂弯里摊着《盐册》。他称量,他书写,而在纸面上,他从来没错过一次。", "王室派駐鹽灘港的估稅官,一身紫與銀,臂彎裡攤著《鹽冊》。他稱量,他書寫,而在紙面上,他從來沒錯過一次。", "Quan định giá của Vương miện ở Saltreach, mặc tím và bạc, Sổ Muối mở trên cánh tay. Ông cân, ông ghi, và trên giấy tờ ông chưa từng sai lần nào.", "Penaksir Mahkota di Saltreach, berbaju ungu dan perak, Buku Garam terbuka di lengannya. Ia menimbang, ia menulis, dan tak sekali pun ia salah, di atas kertas.", "เจ้าพนักงานประเมินของราชบัลลังก์ประจำซอลต์รีช ในชุดม่วงและเงิน สมุดบัญชีเกลือเปิดอยู่บนแขน เขาชั่ง เขาเขียน และไม่เคยผิดสักครั้ง บนกระดาษ", "Taç'ın Saltreach'teki değerleyicisi; mor ve gümüş giysili, kolunda açık Tuz Defteri. Tartar, yazar ve yazılı olarak bir kez bile yanılmamıştır.", "El tasador de la Corona en Saltreach, de violeta y plata, con el Libro de la Sal abierto en el brazo. Pesa, escribe, y nunca se ha equivocado, por escrito.", "O avaliador da Coroa em Saltreach, de violeta e prata, com o Livro do Sal aberto no braço. Pesa, escreve e nunca errou uma vez, por escrito.", "Оценщик Короны в Солтриче, в фиолетовом и серебре, с раскрытой Книгой соли на руке. Он взвешивает, он записывает и ни разу не ошибся — на бумаге.", "Оцінювач Корони в Солтрічі, у фіолетовому й сріблі, з розгорнутою Книгою солі на руці. Він зважує, він записує й жодного разу не помилився — на папері."],
  "Eldest of the salt-panners, white to the elbows, her rake taller than she is. She has paid the King's salt for fifty years and has started to wonder what it weighs.": ["塩田で働く者の最年長。肘まで白く、熊手は彼女より背が高い。五十年王の塩税を払ってきて、それがどれほどの重さなのか考えはじめた。", "염부들 가운데 최연장자. 팔꿈치까지 하얗고, 갈퀴는 그녀보다 키가 크다. 오십 년 동안 왕의 소금세를 내 왔고, 이제 그게 무게가 얼마나 나가는지 궁금해지기 시작했다.", "盐工里最年长的一个,一直白到手肘,耙子比她人还高。她缴了五十年的王家盐税,开始琢磨它到底有多重。", "鹽工裡最年長的一個,一直白到手肘,耙子比她人還高。她繳了五十年的王家鹽稅,開始琢磨它到底有多重。", "Người lớn tuổi nhất trong những người làm muối, trắng tới khuỷu tay, cây cào cao hơn bà. Bà đã nộp muối của Nhà Vua năm mươi năm và bắt đầu tự hỏi nó nặng bao nhiêu.", "Yang tertua di antara petani garam, putih sampai siku, garunya lebih tinggi dari dirinya. Ia sudah membayar garam Raja selama lima puluh tahun dan mulai bertanya-tanya berapa beratnya.", "ผู้อาวุโสที่สุดในหมู่ชาวนาเกลือ ขาวถึงข้อศอก คราดสูงกว่าตัวเธอ เธอจ่ายภาษีเกลือของกษัตริย์มาห้าสิบปี และเริ่มสงสัยว่ามันหนักเท่าไร", "Tuzcuların en yaşlısı; dirseklerine kadar beyaz, tırmığı kendisinden uzun. Elli yıldır Kral'ın tuzunu ödüyor ve ne kadar çektiğini merak etmeye başladı.", "La mayor de los salineros, blanca hasta los codos, con un rastrillo más alto que ella. Lleva cincuenta años pagando la sal del Rey y ha empezado a preguntarse cuánto pesa.", "A mais velha dos salineiros, branca até os cotovelos, com um rodo mais alto que ela. Paga o sal do Rei há cinquenta anos e começou a se perguntar quanto ele pesa.", "Старшая из солеваров, белая до локтей, с граблями выше её самой. Пятьдесят лет она платит королевскую соль и начала задумываться, сколько та весит.", "Найстарша із солеварів, біла до ліктів, із граблями вищими за неї саму. П'ятдесят років вона сплачує королівську сіль і почала замислюватися, скільки та важить."],
  "Keeps the pans' own weights in the weighing shed, so the panners know what to expect before the Salt-House tells them.": ["塩田独自の分銅を計量小屋に置いている。塩館に言われる前に、塩田の者たちが心づもりできるように。", "계량 창고에 염전 자체의 저울추를 둔다. 소금관이 알려 주기 전에 염부들이 무엇을 각오해야 할지 알도록.", "在称量棚里保管盐田自己的砝码,好让盐工们在盐务所开口之前心里有数。", "在稱量棚裡保管鹽田自己的砝碼,好讓鹽工們在鹽務所開口之前心裡有數。", "Giữ những quả cân riêng của ruộng muối trong lán cân, để người làm muối biết trước điều sẽ nghe trước khi Nhà Muối nói ra.", "Menyimpan anak timbangan petak garam sendiri di gudang timbang, supaya para petani garam tahu apa yang menanti sebelum Rumah Garam mengatakannya.", "เก็บลูกตุ้มชั่งของนาเกลือเองไว้ในโรงชั่ง เพื่อให้ชาวนาเกลือรู้ว่าจะได้อะไรก่อนที่โรงเกลือจะบอก", "Tuzlaların kendi ağırlıklarını tartı barakasında tutar ki tuzcular Tuz Evi söylemeden ne bekleyeceklerini bilsin.", "Guarda las pesas propias de las salinas en el cobertizo de pesaje, para que los salineros sepan qué esperar antes de que se lo diga la Casa de la Sal.", "Guarda os pesos próprios das salinas no galpão de pesagem, para que os salineiros saibam o que esperar antes que a Casa do Sal lhes diga.", "Хранит в весовом сарае собственные гири солеварен, чтобы солевары знали, чего ждать, прежде чем им скажет Соляной дом.", "Зберігає у ваговому сараї власні гирі соляних басейнів, щоб солевари знали, чого чекати, перш ніж їм скаже Соляний дім."],
  "Keeps the Salt Cellar, which serves one measure of small beer each, as the Law asks, and a great deal of salt herring, which it doesn't.": ["塩入れ亭を切り盛りしている。掟に従って弱い麦酒を一人一杯、そして掟が何も言わない塩ニシンをたっぷり出す。", "소금 그릇을 꾸린다. 율법대로 약한 맥주는 한 사람에 한 잔, 율법이 말하지 않는 소금 청어는 잔뜩 낸다.", "经营“盐罐”酒馆:按律法每人一份淡啤酒,律法没提的腌鲱鱼则管够。", "經營「鹽罐」酒館:按律法每人一份淡啤酒,律法沒提的醃鯡魚則管夠。", "Trông quán Lọ Muối, mỗi người một chén bia nhẹ như Luật đòi hỏi, và rất nhiều cá trích muối, thứ Luật không nói gì.", "Mengurus Wadah Garam, yang menyajikan satu takar bir ringan per orang, sesuai Hukum, dan banyak haring asin, yang tidak diatur Hukum.", "ดูแลกระปุกเกลือ ที่เสิร์ฟเบียร์อ่อนคนละหนึ่งถ้วยตามที่กฎกำหนด และปลาแฮร์ริ่งเค็มมากมาย ซึ่งกฎไม่ได้กำหนด", "Tuzluk'u işletir; Yasa'nın istediği gibi kişi başı bir ölçü hafif bira, Yasa'nın bir şey demediği bol tuzlu ringa verir.", "Lleva El Salero, que sirve una medida de cerveza floja por cabeza, como pide la Ley, y muchísimo arenque salado, que la Ley no pide.", "Cuida do Saleiro, que serve uma medida de cerveja fraca por cabeça, como pede a Lei, e muito arenque salgado, que a Lei não pede.", "Держит «Солонку», где каждому наливают одну меру слабого пива, как велит Закон, и подают уйму солёной сельди, о которой Закон молчит.", "Тримає «Сільничку», де кожному наливають одну міру слабкого пива, як велить Закон, і подають безліч солоних оселедців, про які Закон мовчить."],
  "Keeps the provisions by the quay: bread of the one kind at the one price, and everything else at whatever the Ledger allows.": ["岸壁そばの食料品店の主人。一種類一値段のパンと、ほかのものは台帳が許す値段で。", "부두 옆 식료품점 주인. 한 종류 한 가격의 빵, 그리고 나머지는 장부가 허락하는 값에.", "经营码头边的杂货铺:面包只有一种、只卖一个价,其余东西按册子允许的价钱卖。", "經營碼頭邊的雜貨鋪:麵包只有一種、只賣一個價,其餘東西按冊子允許的價錢賣。", "Trông tiệm lương thực cạnh bến: bánh mì một loại một giá, còn mọi thứ khác theo giá Sổ cho phép.", "Mengurus perbekalan dekat dermaga: roti satu jenis satu harga, dan sisanya seharga yang diizinkan Buku.", "ดูแลร้านเสบียงข้างท่าเรือ: ขนมปังชนิดเดียวราคาเดียว และอย่างอื่นตามราคาที่สมุดบัญชีอนุญาต", "Rıhtım yanındaki erzakçıyı işletir: tek çeşit, tek fiyat ekmek, gerisi Defter'in izin verdiği fiyata.", "Lleva las provisiones junto al muelle: pan de una sola clase a un solo precio, y todo lo demás al que permita el Libro.", "Cuida das provisões junto ao cais: pão de um só tipo a um só preço, e todo o resto pelo que o Livro permitir.", "Держит припасы у причала: хлеб одного сорта по одной цене, а всё прочее — по той, что дозволит Книга.", "Тримає припаси біля причалу: хліб одного сорту за однією ціною, а все інше — за тією, що дозволить Книга."],
  "Weaves the port's smocks and coifs in salt-white, and the one violet the Sumptuary Office allows a port.": ["港のスモックと頭巾を塩白で織り、奢侈取締局が港に許した唯一の紫も織る。", "항구의 작업복과 두건을 소금처럼 희게 짜고, 사치단속청이 항구에 허락한 단 하나의 보랏빛도 짠다.", "用盐白色织港口的罩衫和头巾,还有禁奢署允许港口用的那唯一一种紫。", "用鹽白色織港口的罩衫和頭巾,還有禁奢署允許港口用的那唯一一種紫。", "Dệt áo choàng làm việc và khăn trùm màu trắng muối cho cảng, và màu tím duy nhất Sở Kiểm soát Xa xỉ cho phép một bến cảng.", "Menenun baju kerja dan tudung pelabuhan dalam putih garam, dan satu-satunya ungu yang diizinkan Kantor Kemewahan untuk pelabuhan.", "ทอเสื้อคลุมทำงานและหมวกคลุมของเมืองท่าเป็นสีขาวเกลือ และสีม่วงสีเดียวที่สำนักควบคุมความฟุ่มเฟือยอนุญาตให้เมืองท่า", "Limanın önlüklerini ve başlıklarını tuz beyazında dokur, bir de İsraf Dairesi'nin bir limana izin verdiği tek moru.", "Teje los blusones y cofias del puerto en blanco sal, y el único violeta que la Oficina Suntuaria permite a un puerto.", "Tece as batas e toucas do porto em branco-sal, e o único violeta que o Ofício Suntuário permite a um porto.", "Ткёт для порта блузы и чепцы цвета соли и тот единственный фиолетовый, что Управление роскоши дозволяет порту.", "Тче для порту блузи й очіпки кольору солі та той єдиний фіолетовий, що Управління розкоші дозволяє портові."],
  "A panner raking the drying salt into ridges, white-rimed to the knee, squinting against the glare off the pans.": ["乾きかけの塩を熊手で畝に寄せている作業者。膝まで白く塩が吹き、塩田の照り返しに目を細めている。", "마르는 소금을 갈퀴로 이랑지게 긁어모으는 염부. 무릎까지 하얗게 소금이 앉았고, 염전의 반사광에 눈을 찡그린다.", "一个盐工正把晒干的盐耙成垄,膝盖以下结满白盐,眯着眼抵挡盐田的反光。", "一個鹽工正把曬乾的鹽耙成壟,膝蓋以下結滿白鹽,瞇著眼抵擋鹽田的反光。", "Một người làm muối đang cào muối khô thành luống, trắng muối tới gối, nheo mắt vì ánh chói từ ruộng muối.", "Petani garam menggaru garam yang mengering menjadi pematang, berkerak putih sampai lutut, menyipit karena silau petak garam.", "ชาวนาเกลือกำลังคราดเกลือที่แห้งให้เป็นสัน ขาวด้วยเกลือถึงเข่า หยีตาสู้แสงจ้าจากนาเกลือ", "Kuruyan tuzu tırmıkla sırtlar halinde toplayan, dizine kadar beyaz kırağılı, tuzlaların parıltısına gözlerini kısan bir tuzcu.", "Un salinero rastrillando la sal en caballones, escarchado de blanco hasta la rodilla, entornando los ojos ante el resplandor de las salinas.", "Um salineiro rodando o sal em leiras, coberto de branco até o joelho, apertando os olhos contra o brilho das salinas.", "Солевар сгребает подсыхающую соль в гряды, белый от соли до колен, щурясь от блеска бассейнов.", "Солевар згрібає соль, що підсихає, у гряди, білий від солі до колін, мружачись від блиску басейнів."],
  "A guard of the King's Salt-House in a violet tabard, who checks the seals on every sack and the faces on every boat.": ["紫の陣羽織を着た王の塩館の衛兵。袋の封印をひとつ残らず、船の顔をひとつ残らず確かめる。", "보랏빛 겉옷을 입은 왕의 소금관 경비병. 모든 자루의 봉인과 모든 배의 얼굴을 확인한다.", "王家盐务所的卫兵,穿着紫色战袍,检查每一袋的封印,也检查每条船上的面孔。", "王家鹽務所的衛兵,穿著紫色戰袍,檢查每一袋的封印,也檢查每條船上的面孔。", "Một lính gác Nhà Muối của Nhà Vua mặc áo khoác ngoài màu tím, kiểm tra niêm phong trên mọi bao và mặt người trên mọi thuyền.", "Penjaga Rumah Garam Raja bertabar ungu, yang memeriksa segel di setiap karung dan wajah di setiap perahu.", "ยามโรงเกลือหลวงในเสื้อคลุมสีม่วง ตรวจตราผนึกทุกกระสอบและหน้าตาทุกคนบนเรือทุกลำ", "Mor cüppeli bir Kralın Tuz Evi muhafızı; her çuvalın mührünü ve her teknedeki yüzleri denetler.", "Un guardia de la Casa de la Sal del Rey con tabardo violeta, que revisa los sellos de cada saco y las caras de cada barca.", "Um guarda da Casa do Sal do Rei num tabardo violeta, que confere os selos de cada saco e os rostos de cada barco.", "Стражник Королевского Соляного дома в фиолетовом табарде, проверяющий печати на каждом мешке и лица в каждой лодке.", "Вартовий Королівського Соляного дому у фіолетовому табарді, що перевіряє печатки на кожному мішку й обличчя в кожному човні."],
  "A citizen of the salt port in white and violet, on the way to the Salt-House, or back from it, or praying about it.": ["白と紫をまとった塩の港の市民。塩館へ向かうところか、帰るところか、それについて祈っているところ。", "흰색과 보라를 입은 소금 항구의 시민. 소금관에 가는 길이거나, 돌아오는 길이거나, 그 일로 기도하는 중이다.", "盐港的市民,一身白与紫,不是在去盐务所的路上,就是从那儿回来,要么在为这事祷告。", "鹽港的市民,一身白與紫,不是在去鹽務所的路上,就是從那兒回來,要麼在為這事禱告。", "Một công dân cảng muối mặc trắng và tím, đang trên đường tới Nhà Muối, hoặc đi về, hoặc đang cầu nguyện về chuyện đó.", "Warga pelabuhan garam berbaju putih dan ungu, sedang menuju Rumah Garam, atau pulang dari sana, atau berdoa soal itu.", "พลเมืองเมืองท่าเกลือในชุดขาวและม่วง กำลังไปโรงเกลือ หรือกลับมาจากที่นั่น หรือกำลังสวดภาวนาเรื่องนั้น", "Beyaz ve mor giysili, Tuz Evi'ne giden, oradan dönen ya da bunun için dua eden bir tuz limanı vatandaşı.", "Un vecino del puerto de la sal, de blanco y violeta, de camino a la Casa de la Sal, o de vuelta, o rezando por ello.", "Um cidadão do porto do sal, de branco e violeta, a caminho da Casa do Sal, ou de volta dela, ou rezando por isso.", "Горожанин соляного порта в белом и фиолетовом: идёт в Соляной дом, или оттуда, или молится по этому поводу.", "Городянин соляного порту в білому й фіолетовому: іде до Соляного дому, або звідти, або молиться з цього приводу."],
  "Head of Merrab's pearl divers, broad-shouldered, her ears ringing from twenty years of the deep beds. She can hold her breath longer than you can hold a conversation.": ["メラブの真珠潜りの頭。肩幅が広く、二十年深い真珠床に潜ってきたせいで耳鳴りがする。あなたが会話を続けられるより長く息を止めていられる。", "메라브 진주 잠수부들의 우두머리. 어깨가 넓고, 이십 년간 깊은 진주밭을 드나든 탓에 귀가 울린다. 네가 대화를 이어 가는 것보다 더 오래 숨을 참을 수 있다.", "梅拉布采珠人的头领,肩膀宽阔,在深珠床潜了二十年,耳朵一直嗡嗡响。她憋气的时间比你能撑住一场谈话还长。", "梅拉布採珠人的頭領,肩膀寬闊,在深珠床潛了二十年,耳朵一直嗡嗡響。她憋氣的時間比你能撐住一場談話還長。", "Người đứng đầu thợ lặn ngọc trai Merrab, vai rộng, tai ù vì hai mươi năm lặn bãi ngọc sâu. Bà nín thở được lâu hơn bạn giữ nổi một cuộc trò chuyện.", "Kepala penyelam mutiara Merrab, berbahu lebar, telinganya berdenging karena dua puluh tahun di dasar laut dalam. Ia bisa menahan napas lebih lama daripada kau bisa menahan obrolan.", "หัวหน้านักดำน้ำหามุกแห่งเมอร์รับ ไหล่กว้าง หูอื้อจากการดำแหล่งหอยมุกลึกมายี่สิบปี เธอกลั้นหายใจได้นานกว่าที่คุณจะคุยต่อได้", "Merrab inci dalgıçlarının başı; geniş omuzlu, yirmi yıllık derin yataklardan kulakları çınlıyor. Sen bir sohbeti sürdüreceğinden daha uzun nefesini tutabilir.", "La jefa de los buceadores de perlas de Merrab, ancha de hombros, con los oídos zumbando tras veinte años de bancos profundos. Aguanta la respiración más de lo que tú aguantas una conversación.", "A chefe dos mergulhadores de pérolas de Merrab, de ombros largos, com os ouvidos zunindo de vinte anos de bancos fundos. Ela prende o fôlego por mais tempo do que você sustenta uma conversa.", "Старшая над ныряльщиками за жемчугом Мерраба, широкоплечая, в ушах звенит от двадцати лет глубоких отмелей. Она задерживает дыхание дольше, чем ты способен поддерживать разговор.", "Старша над пірнальниками за перлами Меррабу, широкоплеча, у вухах дзвенить від двадцяти років глибоких мілин. Вона затримує подих довше, ніж ти здатен підтримувати розмову."],
  "The Gilded Court's pearl factor at Merrab, in white linen with a gold-worked collar. He lends the divers their boats, buys their pearls, and keeps the book of what they owe.": ["メラブに駐在する金色の宮廷の真珠代理商。金糸の襟のついた白い亜麻をまとう。潜り手に船を貸し、真珠を買い、彼らの借りの帳簿をつけている。", "메라브에 있는 황금 궁정의 진주 중개인. 금실 수 놓은 깃의 흰 아마옷을 입었다. 잠수부들에게 배를 빌려주고, 진주를 사들이고, 그들이 진 빚의 장부를 쥐고 있다.", "镀金宫廷派驻梅拉布的珍珠代理商,一身白亚麻,领口绣着金线。他借船给潜水人,收购他们的珍珠,还记着他们欠债的账本。", "鍍金宮廷派駐梅拉布的珍珠代理商,一身白亞麻,領口繡著金線。他借船給潛水人,收購他們的珍珠,還記著他們欠債的帳本。", "Đại lý ngọc trai của Triều Mạ Vàng ở Merrab, mặc vải lanh trắng cổ thêu vàng. Ông cho thợ lặn mượn thuyền, mua ngọc của họ, và giữ sổ những gì họ nợ.", "Agen mutiara Istana Bersepuh di Merrab, berlinen putih dengan kerah bersulam emas. Ia meminjamkan perahu kepada para penyelam, membeli mutiara mereka, dan memegang buku utang mereka.", "ตัวแทนรับซื้อไข่มุกของราชสำนักปิดทองประจำเมอร์รับ สวมผ้าลินินขาวคอปักทอง เขาให้นักดำน้ำยืมเรือ ซื้อไข่มุกของพวกเขา และถือสมุดหนี้ของพวกเขา", "Yaldızlı Saray'ın Merrab'daki inci kâhyası; altın işlemeli yakalı beyaz keten giyer. Dalgıçlara teknelerini ödünç verir, incilerini alır ve borç defterlerini tutar.", "El factor de perlas de la Corte Dorada en Merrab, de lino blanco con cuello bordado en oro. Presta las barcas a los buceadores, les compra las perlas y lleva el libro de lo que deben.", "O feitor de pérolas da Corte Dourada em Merrab, de linho branco com gola bordada a ouro. Empresta os barcos aos mergulhadores, compra suas pérolas e guarda o livro do que eles devem.", "Жемчужный фактор Позолоченного двора в Меррабе, в белом льне с вышитым золотом воротом. Он ссужает ныряльщикам лодки, скупает их жемчуг и ведёт книгу их долгов.", "Перловий фактор Позолоченого двору в Меррабі, у білому льоні з гаптованим золотом коміром. Він позичає пірнальникам човни, скуповує їхні перли й веде книгу їхніх боргів."],
  "The Copper Banner's captain of Merrab's harbour, who collects Khetmar's dues and would rather be collecting anything else, preferably somewhere with shade.": ["銅の旗のメラブ港担当の隊長。ケトマルへの税を取り立てているが、できれば日陰のある場所で何か別のものを集めていたい。", "구리 깃발 소속 메라브 항구 대장. 케트마르의 세금을 거두지만, 할 수만 있다면 그늘 있는 곳에서 다른 무엇이든 거두고 싶어 한다.", "铜旗驻梅拉布港的队长,替克特马尔收税,其实更想收点别的什么,最好是在有阴凉的地方。", "銅旗駐梅拉布港的隊長,替克特馬爾收稅,其實更想收點別的什麼,最好是在有陰涼的地方。", "Đội trưởng cảng Merrab của Cờ Đồng, thu thuế cho Khetmar và thà thu bất cứ thứ gì khác, tốt nhất là ở nơi có bóng râm.", "Kapten pelabuhan Merrab dari Panji Tembaga, yang memungut bea untuk Khetmar dan lebih suka memungut apa pun yang lain, sebaiknya di tempat yang teduh.", "ผู้กองท่าเรือเมอร์รับของธงทองแดง ผู้เก็บค่าธรรมเนียมให้เคทมาร์ และอยากเก็บอย่างอื่นมากกว่า ดีที่สุดคือในที่ร่ม", "Bakır Sancak'ın Merrab limanı yüzbaşısı; Khetmar'ın vergilerini toplar, ama başka herhangi bir şeyi, tercihen gölge bir yerde toplamayı yeğlerdi.", "El capitán del Estandarte de Cobre en el puerto de Merrab, que cobra los derechos de Khetmar y preferiría cobrar cualquier otra cosa, a ser posible a la sombra.", "O capitão do Estandarte de Cobre no porto de Merrab, que cobra as taxas de Khetmar e preferiria cobrar qualquer outra coisa, de preferência à sombra.", "Капитан Медного знамени в гавани Мерраба: собирает сборы для Кетмара, а охотнее собирал бы что угодно другое, желательно в тени.", "Капітан Мідного стягу в гавані Меррабу: збирає збори для Кетмара, а охочіше збирав би будь-що інше, бажано в затінку."],
  "Keeps the Sea Gate Inn, and keeps the divers fed whether or not they can pay, which the factor finds very irritating.": ["海門亭を切り盛りし、払えようが払えまいが潜り手たちを食わせている。代理商はそれがひどく気に入らない。", "바다 문 여관을 꾸리며, 돈을 낼 수 있든 없든 잠수부들을 먹인다. 중개인은 그게 몹시 못마땅하다.", "经营海门客栈,不管潜水人付不付得起都管他们吃饱,这让代理商非常恼火。", "經營海門客棧,不管潛水人付不付得起都管他們吃飽,這讓代理商非常惱火。", "Trông Quán trọ Cổng Biển, và cho thợ lặn ăn no dù họ có trả được hay không, điều khiến viên đại lý rất bực mình.", "Mengurus Penginapan Gerbang Laut, dan memberi makan para penyelam entah mereka bisa membayar atau tidak, yang membuat sang agen sangat kesal.", "ดูแลโรงเตี๊ยมประตูทะเล และเลี้ยงนักดำน้ำให้อิ่มไม่ว่าจะจ่ายได้หรือไม่ ซึ่งตัวแทนรู้สึกหงุดหงิดมาก", "Deniz Kapısı Hanı'nı işletir ve dalgıçları ödeyebilseler de ödeyemeseler de doyurur; kâhya buna çok sinirlenir.", "Lleva la posada de la Puerta del Mar, y da de comer a los buceadores puedan pagar o no, cosa que al factor le irrita muchísimo.", "Cuida da estalagem do Portão do Mar e alimenta os mergulhadores, paguem ou não, o que irrita muito o feitor.", "Держит трактир «Морские ворота» и кормит ныряльщиков, могут они платить или нет, что фактора ужасно раздражает.", "Тримає корчму «Морська брама» й годує пірнальників, можуть вони платити чи ні, що фактора страшенно дратує."],
  "Keeps the stores on the harbour street: dates, rope, oil and diving stones, all priced in Sefrah gold and argued about in Khetmar copper.": ["港通りの雑貨店の主人。ナツメヤシ、縄、油、潜水石。値段はどれもセフラの金貨で、値切りはケトマルの銅貨で。", "항구 거리의 잡화점 주인. 대추야자, 밧줄, 기름, 잠수돌. 값은 모두 세프라 금화로 매기고, 흥정은 케트마르 동전으로 한다.", "经营港口街上的杂货铺:椰枣、绳子、油、潜水石,全用塞弗拉金币标价,用克特马尔铜板讨价还价。", "經營港口街上的雜貨鋪:椰棗、繩子、油、潛水石,全用塞弗拉金幣標價,用克特馬爾銅板討價還價。", "Trông cửa hàng trên phố cảng: chà là, dây thừng, dầu và đá lặn, tất cả niêm yết bằng vàng Sefrah và mặc cả bằng đồng Khetmar.", "Mengurus toko di jalan pelabuhan: kurma, tali, minyak, dan batu selam, semuanya dihargai dalam emas Sefrah dan ditawar dalam tembaga Khetmar.", "ดูแลร้านบนถนนท่าเรือ: อินทผลัม เชือก น้ำมัน และหินดำน้ำ ทั้งหมดติดราคาเป็นทองเซฟราห์ และต่อรองกันด้วยทองแดงเคทมาร์", "Liman caddesindeki dükkânı işletir: hurma, ip, yağ ve dalış taşları; hepsinin fiyatı Sefrah altınıyla, pazarlığı Khetmar bakırıyla.", "Lleva los almacenes de la calle del puerto: dátiles, cuerda, aceite y piedras de buceo, todo con precio en oro de Sefrah y regateado en cobre de Khetmar.", "Cuida dos armazéns da rua do porto: tâmaras, corda, óleo e pedras de mergulho, tudo com preço em ouro de Sefrah e pechinchado em cobre de Khetmar.", "Держит лавку на портовой улице: финики, верёвка, масло и ныряльные камни, цены — в сефрахском золоте, торг — в кетмарской меди.", "Тримає крамницю на портовій вулиці: фініки, мотузка, олія й пірнальні камені, ціни — у сефрійському золоті, торг — у кетмарській міді."],
  "Merrab's dyer, her arms blue to the elbow, who dyes the divers' sea-green and swears it brings the pearls up faster.": ["メラブの染め師。腕は肘まで青い。潜り手たちの海緑を染め、それで真珠が早く上がってくると誓う。", "메라브의 염색장이. 팔꿈치까지 팔이 파랗다. 잠수부들의 바다빛 초록을 물들이며, 그러면 진주가 더 빨리 올라온다고 맹세한다.", "梅拉布的染匠,手臂一直蓝到手肘,给潜水人染海绿色,还发誓这样珍珠捞得更快。", "梅拉布的染匠,手臂一直藍到手肘,給潛水人染海綠色,還發誓這樣珍珠撈得更快。", "Thợ nhuộm của Merrab, tay xanh tới khuỷu, nhuộm màu xanh biển cho thợ lặn và thề rằng nó giúp ngọc lên nhanh hơn.", "Pencelup Merrab, lengannya biru sampai siku, yang mencelup hijau laut para penyelam dan bersumpah warna itu membuat mutiara naik lebih cepat.", "ช่างย้อมแห่งเมอร์รับ แขนเป็นสีน้ำเงินถึงข้อศอก ย้อมสีเขียวน้ำทะเลให้นักดำน้ำ และสาบานว่ามันทำให้ไข่มุกขึ้นมาเร็วขึ้น", "Merrab'ın boyacısı; kolları dirseğe kadar mavi, dalgıçların deniz yeşilini boyar ve incileri daha hızlı çıkardığına yemin eder.", "La tintorera de Merrab, con los brazos azules hasta el codo, que tiñe el verde mar de los buceadores y jura que hace subir las perlas más deprisa.", "A tintureira de Merrab, com os braços azuis até o cotovelo, que tinge o verde-mar dos mergulhadores e jura que faz as pérolas subirem mais depressa.", "Красильщица Мерраба, руки синие до локтя: красит ныряльщикам ткань в цвет морской волны и клянётся, что так жемчуг поднимается быстрее.", "Фарбувальниця Меррабу, руки сині до ліктя: фарбує пірнальникам тканину в колір морської хвилі й клянеться, що так перли піднімаються швидше."],
  "Builds and mends the diving boats in the yard by the harbour, in Meghavan teak, with a mouthful of nails.": ["港のそばの造船場で、メーガヴァン産のチークを使い、口いっぱいに釘をくわえて潜水船を造り、繕う。", "항구 옆 조선장에서 메가반 티크로, 입에 못을 한가득 문 채 잠수선을 짓고 고친다.", "在港边的船坞里用梅加万柚木造潜水船、修潜水船,嘴里含着一口钉子。", "在港邊的船塢裡用梅加萬柚木造潛水船、修潛水船,嘴裡含著一口釘子。", "Đóng và sửa thuyền lặn trong xưởng cạnh cảng, bằng gỗ tếch Meghavan, miệng ngậm đầy đinh.", "Membuat dan memperbaiki perahu selam di galangan dekat pelabuhan, dari jati Meghavan, dengan mulut penuh paku.", "ต่อและซ่อมเรือดำน้ำหามุกในลานข้างท่าเรือ ด้วยไม้สักเมฆาวัน ปากคาบตะปูเต็ม", "Limanın yanındaki tezgâhta, Meghavan tikinden, ağzı çivi dolu, dalış teknelerini yapar ve onarır.", "Construye y repara las barcas de buceo en el astillero junto al puerto, en teca de Meghavan, con la boca llena de clavos.", "Constrói e conserta os barcos de mergulho no estaleiro junto ao porto, em teca de Meghavan, com a boca cheia de pregos.", "Строит и чинит ныряльные лодки на верфи у гавани, из мегхаванского тика, с полным ртом гвоздей.", "Будує й лагодить пірнальні човни на верфі біля гавані, з мегхаванського тику, з повним ротом цвяхів."],
  "One of Merrab's divers, salt-cracked and sun-dark, a diving stone on a cord over the shoulder. Nobody's been down to the deep beds for weeks.": ["メラブの潜り手の一人。塩でひび割れ、日に焼け、肩には紐に通した潜水石。もう何週間も、誰も深い真珠床に潜っていない。", "메라브의 잠수부. 소금에 갈라지고 햇볕에 그을렸으며, 어깨에 줄에 꿴 잠수돌을 걸쳤다. 몇 주째 아무도 깊은 진주밭에 내려가지 않았다.", "梅拉布的潜水人之一,皮肤被盐裂开、被太阳晒黑,肩上挂着一块拴绳的潜水石。几个星期了,没人下过深珠床。", "梅拉布的潛水人之一,皮膚被鹽裂開、被太陽曬黑,肩上掛著一塊拴繩的潛水石。幾個星期了,沒人下過深珠床。", "Một thợ lặn Merrab, da nứt vì muối và sạm nắng, một hòn đá lặn xâu dây vắt qua vai. Đã nhiều tuần không ai xuống bãi ngọc sâu.", "Salah satu penyelam Merrab, kulitnya retak garam dan legam matahari, batu selam bertali tersampir di bahu. Sudah berminggu-minggu tak ada yang turun ke dasar laut dalam.", "หนึ่งในนักดำน้ำแห่งเมอร์รับ ผิวแตกด้วยเกลือ คล้ำแดด หินดำน้ำร้อยเชือกพาดบ่า ไม่มีใครลงไปแหล่งหอยมุกลึกมาหลายสัปดาห์แล้ว", "Merrab'ın dalgıçlarından biri; tuzdan çatlamış, güneşten kararmış, omzunda ipe bağlı bir dalış taşı. Haftalardır kimse derin yataklara inmedi.", "Uno de los buceadores de Merrab, agrietado de sal y moreno de sol, con una piedra de buceo en un cordel al hombro. Hace semanas que nadie baja a los bancos profundos.", "Um dos mergulhadores de Merrab, rachado de sal e queimado de sol, com uma pedra de mergulho num cordão ao ombro. Há semanas ninguém desce aos bancos fundos.", "Один из ныряльщиков Мерраба, потрескавшийся от соли и чёрный от солнца, с ныряльным камнем на шнуре через плечо. Уже несколько недель никто не спускался к глубоким отмелям.", "Один із пірнальників Меррабу, потрісканий від солі й чорний від сонця, з пірнальним каменем на шнурі через плече. Уже кілька тижнів ніхто не спускався до глибоких мілин."],
  "A soldier of the Copper Banner on harbour duty, sabre at the hip, eyes on the pearl boats and the dues box both.": ["港の警備についている銅の旗の兵士。腰にサーベル、目は真珠船と税箱の両方に向けている。", "항구 근무 중인 구리 깃발 병사. 허리에 사브르를 찼고, 눈은 진주 배와 세금 상자 양쪽을 지켜본다.", "一名在港口执勤的铜旗士兵,腰挎军刀,一双眼睛既盯着采珠船,也盯着税箱。", "一名在港口執勤的銅旗士兵,腰挎軍刀,一雙眼睛既盯著採珠船,也盯著稅箱。", "Một người lính Cờ Đồng trực ở cảng, kiếm cong bên hông, mắt dõi cả thuyền ngọc lẫn hòm thuế.", "Prajurit Panji Tembaga bertugas di pelabuhan, pedang di pinggang, matanya mengawasi perahu mutiara dan kotak bea sekaligus.", "ทหารธงทองแดงประจำท่าเรือ ดาบโค้งที่เอว ตาจับจ้องทั้งเรือหามุกและหีบค่าธรรมเนียม", "Limanda görevli bir Bakır Sancak askeri; belinde kılıç, gözü hem inci teknelerinde hem vergi sandığında.", "Un soldado del Estandarte de Cobre de servicio en el puerto, sable al cinto, con un ojo en las barcas perleras y otro en la caja de los derechos.", "Um soldado do Estandarte de Cobre de serviço no porto, sabre à cinta, com um olho nos barcos de pérolas e outro na caixa das taxas.", "Солдат Медного знамени на портовой службе, сабля у бедра, глаза и на жемчужных лодках, и на ящике сборов.", "Вояк Мідного стягу на портовій службі, шабля при боці, очі й на перлових човнах, і на скриньці зборів."],
  "Someone of the harbour town in white and sea-green, with salt in the hair and a shell on a string at the throat.": ["白と海緑をまとった港町の人。髪には塩、喉元には紐に通した貝殻。", "흰색과 바다빛 초록을 입은 항구 마을 사람. 머리카락엔 소금, 목에는 줄에 꿴 조개껍데기.", "港镇上的人,一身白与海绿,头发里有盐,脖子上用绳子挂着一枚贝壳。", "港鎮上的人,一身白與海綠,頭髮裡有鹽,脖子上用繩子掛著一枚貝殼。", "Một người ở thị trấn cảng mặc trắng và xanh biển, tóc vương muối, cổ đeo vỏ sò xâu dây.", "Warga kota pelabuhan berbaju putih dan hijau laut, garam di rambutnya dan kerang bertali di lehernya.", "ชาวเมืองท่าในชุดขาวและเขียวน้ำทะเล มีเกลือติดผม และเปลือกหอยร้อยเชือกที่คอ", "Beyaz ve deniz yeşili giysili, saçında tuz, boğazında ipe dizili bir deniz kabuğu olan bir liman kasabası sakini.", "Alguien del pueblo del puerto de blanco y verde mar, con sal en el pelo y una concha de un cordel al cuello.", "Alguém da cidade portuária de branco e verde-mar, com sal no cabelo e uma concha num cordão ao pescoço.", "Житель портового городка в белом и цвете морской волны, с солью в волосах и ракушкой на шнурке у горла.", "Мешканець портового містечка в білому й кольорі морської хвилі, із сіллю у волоссі й мушлею на шнурку біля горла."],
  "Elder of Tel Ashun, small and dusty, leaning on a staff cut from a roof beam older than she is. She speaks for the village and listens for the mound.": ["テル・アシュンの長老。小柄で埃にまみれ、自分より古い屋根の梁から切り出した杖にもたれている。村のために語り、丘のために耳を傾ける。", "텔 아슌의 장로. 작고 먼지투성이이며, 자기보다 오래된 지붕 들보를 잘라 만든 지팡이에 기대고 있다. 마을을 위해 말하고, 언덕을 위해 귀 기울인다.", "泰勒阿顺的长老,个子小,满身尘土,拄着一根用比她还老的房梁削成的拐杖。她替村子说话,也替土丘倾听。", "泰勒阿順的長老,個子小,滿身塵土,拄著一根用比她還老的房樑削成的拐杖。她替村子說話,也替土丘傾聽。", "Trưởng lão của Tel Ashun, nhỏ người và bám bụi, chống cây gậy cắt từ một xà nhà còn già hơn bà. Bà nói thay cho làng và lắng nghe thay cho gò đất.", "Tetua Tel Ashun, kecil dan berdebu, bersandar pada tongkat dari balok atap yang lebih tua darinya. Ia berbicara untuk desa dan mendengarkan untuk gundukan.", "ผู้อาวุโสแห่งเทล อาชุน ตัวเล็กเปื้อนฝุ่น พิงไม้เท้าที่ตัดจากขื่อหลังคาซึ่งเก่ากว่าตัวเธอ เธอพูดแทนหมู่บ้าน และฟังแทนเนิน", "Tel Ashun'un yaşlısı; ufak tefek ve tozlu, kendisinden eski bir çatı kirişinden kesilmiş bir değneğe yaslanıyor. Köy adına konuşur, höyük adına dinler.", "La anciana de Tel Ashun, menuda y polvorienta, apoyada en un bastón cortado de una viga más vieja que ella. Habla por la aldea y escucha por el montículo.", "A anciã de Tel Ashun, pequena e empoeirada, apoiada num cajado cortado de uma viga mais velha que ela. Fala pela aldeia e escuta pelo monte.", "Старейшина Тель-Ашуна, маленькая и пыльная, опирается на посох, вырезанный из потолочной балки старше её самой. Она говорит за деревню и слушает за холм.", "Старійшина Тель-Ашуна, маленька й запорошена, спирається на ціпок, вирізаний зі стельової балки, старшої за неї саму. Вона говорить за село й слухає за пагорб."],
  "Makes Tel Ashun's mudbricks, and has made them from the tell itself since the river clay ran out, because the tell is clay already, only older.": ["テル・アシュンの日干し煉瓦を作っている。川の粘土が尽きてからは丘そのものから作ってきた。丘はもともと粘土だ、ただ古いだけで。", "텔 아슌의 흙벽돌을 만든다. 강 진흙이 바닥난 뒤로는 언덕 자체로 만들어 왔다. 언덕은 이미 진흙이니까, 그저 더 오래됐을 뿐.", "做泰勒阿顺的泥砖。河泥用光以后,他就从土丘本身取土,因为土丘本来就是泥,只是更老罢了。", "做泰勒阿順的泥磚。河泥用光以後,他就從土丘本身取土,因為土丘本來就是泥,只是更老罷了。", "Làm gạch bùn cho Tel Ashun, và làm từ chính gò đất từ khi đất sét sông cạn, vì gò vốn là đất sét rồi, chỉ cổ hơn.", "Membuat bata lumpur Tel Ashun, dan membuatnya dari gundukan itu sendiri sejak tanah liat sungai habis, karena gundukan sudah berupa tanah liat, hanya lebih tua.", "ทำอิฐดินของเทล อาชุน และทำจากเนินเองตั้งแต่ดินเหนียวริมแม่น้ำหมด เพราะเนินก็เป็นดินเหนียวอยู่แล้ว แค่เก่ากว่า", "Tel Ashun'un kerpiçlerini yapar; nehir kili bittiğinden beri höyüğün kendisinden yapıyor, çünkü höyük zaten kil, yalnızca daha eski.", "Hace los adobes de Tel Ashun, y desde que se acabó el barro del río los hace con el propio montículo, porque el montículo ya es barro, solo que más viejo.", "Faz os adobes de Tel Ashun, e desde que o barro do rio acabou os faz do próprio monte, porque o monte já é barro, só que mais velho.", "Делает сырцовый кирпич Тель-Ашуна, и с тех пор, как кончилась речная глина, — из самого холма: холм и так глина, только старая.", "Робить саманну цеглу Тель-Ашуна, і відколи скінчилася річкова глина, — із самого пагорба: пагорб і так глина, тільки стара."],
  "A recorder of the Obsidian Legacy out of Tamesh, in black linen bordered with lapis, who has come to write the tell down before it's all bricks.": ["タメシュから来た黒曜の遺統の記録官。瑠璃色で縁取った黒い亜麻をまとい、丘がすべて煉瓦になる前に書き留めに来た。", "타메시에서 온 흑요 유산의 기록관. 청금석 빛으로 테를 두른 검은 아마옷을 입었고, 언덕이 전부 벽돌이 되기 전에 기록하러 왔다.", "从塔梅什来的黑曜遗脉记录官,身穿镶青金石色边的黑亚麻,赶在土丘全变成砖之前来把它记下来。", "從塔梅什來的黑曜遺脈記錄官,身穿鑲青金石色邊的黑亞麻,趕在土丘全變成磚之前來把它記下來。", "Một người ghi chép của Di Sản Hắc Diện từ Tamesh, mặc vải lanh đen viền xanh lam ngọc, đến để ghi lại gò đất trước khi nó thành gạch hết.", "Pencatat Warisan Obsidian dari Tamesh, berlinen hitam berpinggiran lapis, yang datang untuk mencatat gundukan itu sebelum semuanya jadi bata.", "ผู้บันทึกของมรดกออบซิเดียนจากทาเมช ในผ้าลินินดำขลิบสีลาพิส มาเพื่อจดบันทึกเนินไว้ก่อนที่มันจะกลายเป็นอิฐทั้งหมด", "Tamesh'ten gelen, lacivert taşı kenarlı kara keten giymiş bir Obsidyen Mirası kayıtçısı; höyük tümden tuğla olmadan onu kayda geçirmeye geldi.", "Una registradora del Legado de Obsidiana venida de Tamesh, de lino negro ribeteado de lapislázuli, que ha venido a poner el montículo por escrito antes de que todo sea ladrillo.", "Uma registradora do Legado de Obsidiana vinda de Tamesh, de linho negro debruado de lápis-lazúli, que veio pôr o monte por escrito antes que vire tudo tijolo.", "Летописица Обсидианового наследия из Тамеша, в чёрном льне с лазуритовой каймой, пришедшая записать холм, пока он весь не стал кирпичами.", "Літописиця Обсидіанової спадщини з Тамеша, у чорному льоні з лазуритовою облямівкою, що прийшла записати пагорб, поки він увесь не став цеглою."],
  "Throws pots from the tell's clay and sells them to the village that dug it up. Some of her pots are older than her; she sells those too.": ["丘の粘土で壺をひき、それを掘り出した村に売っている。中には彼女より古い壺もある。それも売る。", "언덕의 흙으로 그릇을 빚어 그걸 파낸 마을에 판다. 그녀보다 오래된 그릇도 몇 있는데, 그것도 판다.", "用土丘的黏土拉坯做罐,再卖给挖出这黏土的村子。她有些罐子比她还老,那些她也卖。", "用土丘的黏土拉坯做罐,再賣給挖出這黏土的村子。她有些罐子比她還老,那些她也賣。", "Nặn gốm từ đất sét của gò và bán cho chính ngôi làng đã đào nó lên. Vài chiếc bình còn già hơn bà; bà bán cả những chiếc đó.", "Membentuk tembikar dari tanah liat gundukan dan menjualnya kepada desa yang menggalinya. Beberapa tembikarnya lebih tua darinya; ia menjual itu juga.", "ปั้นหม้อจากดินเหนียวของเนิน แล้วขายให้หมู่บ้านที่ขุดมันขึ้นมา หม้อบางใบเก่ากว่าตัวเธอ เธอก็ขายด้วย", "Höyüğün kilinden çömlek çeker ve onu kazıp çıkaran köye satar. Bazı çömlekleri kendisinden eski; onları da satar.", "Tornea vasijas con el barro del montículo y se las vende a la aldea que lo sacó. Algunas de sus vasijas son más viejas que ella; esas también las vende.", "Torneia potes com o barro do monte e os vende à aldeia que o desenterrou. Alguns dos seus potes são mais velhos que ela; esses ela também vende.", "Лепит горшки из глины холма и продаёт их деревне, что её выкопала. Некоторые её горшки старше её самой; их она тоже продаёт.", "Ліпить горщики з глини пагорба й продає їх селу, яке її викопало. Деякі її горщики старші за неї саму; їх вона теж продає."],
  "A digger at the cut in the mound, with a mattock and a basket, grey with the dust of a hundred years at a time.": ["丘の切り通しで掘る作業者。つるはしと籠を持ち、一度に百年分の埃で灰色になっている。", "언덕 단면에서 일하는 인부. 곡괭이와 바구니를 들었고, 한 번에 백 년 치 먼지로 잿빛이 되었다.", "在土丘断面上干活的挖土人,拿着鹤嘴锄和篮子,一身灰扑扑的,一铲就是一百年的尘土。", "在土丘斷面上幹活的挖土人,拿著鶴嘴鋤和籃子,一身灰撲撲的,一鏟就是一百年的塵土。", "Một người đào ở vết cắt trên gò, cầm cuốc chim và giỏ, xám bụi của cả trăm năm mỗi lần.", "Penggali di galian gundukan, membawa beliung dan keranjang, kelabu oleh debu seratus tahun sekaligus.", "คนขุดที่รอยขุดบนเนิน ถือจอบและตะกร้า เทาด้วยฝุ่นทีละร้อยปี", "Höyükteki kesitte kazan, kazması ve sepetiyle, bir seferde yüz yılın tozuyla grileşmiş bir kazıcı.", "Un cavador en el corte del montículo, con azadón y cesta, gris del polvo de cien años de una vez.", "Um cavador no corte do monte, com enxadão e cesto, cinzento da poeira de cem anos de cada vez.", "Копатель у разреза в холме, с мотыгой и корзиной, серый от пыли сотни лет за раз.", "Копач біля розрізу в пагорбі, з мотикою й кошиком, сірий від пилу сотні років за раз."],
  "Someone of the village on the mound, in Tamesh's plain linen, which is what the masons' cousins wear.": ["丘の上の村の人。タメシュの質素な亜麻をまとっている。石工たちのいとこが着るものだ。", "언덕 위 마을 사람. 타메시의 수수한 아마옷을 입었다. 석공들의 사촌들이 입는 옷이다.", "土丘上村子里的人,穿着塔梅什的朴素亚麻,石匠们的表亲都这么穿。", "土丘上村子裡的人,穿著塔梅什的樸素亞麻,石匠們的表親都這麼穿。", "Một người ở ngôi làng trên gò, mặc vải lanh giản dị của Tamesh, thứ mà họ hàng của thợ đá vẫn mặc.", "Warga desa di atas gundukan, berlinen polos Tamesh, yang dipakai sepupu-sepupu para tukang batu.", "ชาวหมู่บ้านบนเนิน ในผ้าลินินเรียบๆ แบบทาเมช อย่างที่ญาติของช่างหินสวมกัน", "Höyükteki köyden biri; Tamesh'in sade keteninde, taşçıların kuzenlerinin giydiği gibi.", "Alguien de la aldea del montículo, con el lino sencillo de Tamesh, que es lo que visten los primos de los canteros.", "Alguém da aldeia do monte, no linho simples de Tamesh, que é o que vestem os primos dos pedreiros.", "Житель деревни на холме, в простом тамешском льне, какой носят двоюродные братья каменщиков.", "Мешканець села на пагорбі, у простому тамеському льоні, який носять двоюрідні брати каменярів."],
  "Keeper of Ennu's Well, who measures out the water by the tally stick, and has been measuring out less of it every week.": ["エンヌの井戸の守り手。割符で水を量り分けている。そして毎週、量り分ける水は減っている。", "엔누의 우물을 지키는 이. 눈금 막대로 물을 나누어 주는데, 주마다 나눠 주는 물이 줄고 있다.", "恩努井的守井人,用计数木签分水,而她分出去的水一周比一周少。", "恩努井的守井人,用計數木籤分水,而她分出去的水一週比一週少。", "Người giữ Giếng Ennu, chia nước theo que khắc, và mỗi tuần lại chia ra ít hơn.", "Penjaga Sumur Ennu, yang menakar air dengan batang hitung, dan menakar lebih sedikit setiap minggu.", "ผู้ดูแลบ่อน้ำเอนนู ผู้แบ่งน้ำตามไม้ขีดนับ และแบ่งได้น้อยลงทุกสัปดาห์", "Ennu Kuyusu'nun bekçisi; suyu çentik çubuğuyla paylaştırır ve her hafta daha azını paylaştırıyor.", "La guardiana del Pozo de Ennu, que reparte el agua por la tarja, y cada semana reparte menos.", "A guardiã do Poço de Ennu, que reparte a água pela talha, e a cada semana reparte menos.", "Хранительница Колодца Энну: отмеряет воду по бирке, и с каждой неделей отмеряет всё меньше.", "Хранителька Криниці Енну: відмірює воду за биркою, і з кожним тижнем відмірює дедалі менше."],
  "Master of a caravan of forty camels between Merrab and the steppe, who has paid for Ennu's water for twenty years and means to go on drinking it.": ["メラブと草原のあいだを行き来する四十頭のラクダの隊商の頭。二十年エンヌの水に金を払ってきて、これからも飲みつづけるつもりだ。", "메라브와 초원 사이를 오가는 낙타 마흔 마리 대상의 우두머리. 이십 년 동안 엔누의 물값을 치렀고, 앞으로도 계속 마실 작정이다.", "一支四十峰骆驼商队的首领,往来于梅拉布和草原之间,给恩努井的水付了二十年的钱,打算一直喝下去。", "一支四十峰駱駝商隊的首領,往來於梅拉布和草原之間,給恩努井的水付了二十年的錢,打算一直喝下去。", "Trưởng một đoàn lữ hành bốn mươi con lạc đà đi giữa Merrab và thảo nguyên, đã trả tiền nước của Ennu hai mươi năm và định uống tiếp.", "Pemimpin kafilah empat puluh unta antara Merrab dan padang rumput, yang sudah membayar air Ennu selama dua puluh tahun dan berniat terus meminumnya.", "หัวหน้ากองคาราวานอูฐสี่สิบตัวระหว่างเมอร์รับกับทุ่งหญ้า ผู้จ่ายค่าน้ำของเอนนูมายี่สิบปี และตั้งใจจะดื่มต่อไป", "Merrab ile bozkır arasında kırk develik bir kervanın başı; yirmi yıldır Ennu'nun suyunun parasını ödüyor ve içmeye devam etmek niyetinde.", "El jefe de una caravana de cuarenta camellos entre Merrab y la estepa, que lleva veinte años pagando el agua de Ennu y piensa seguir bebiéndola.", "O chefe de uma caravana de quarenta camelos entre Merrab e a estepe, que paga pela água de Ennu há vinte anos e pretende continuar a bebê-la.", "Хозяин каравана в сорок верблюдов между Меррабом и степью: двадцать лет платит за воду Энну и намерен пить её и дальше.", "Господар каравану на сорок верблюдів між Меррабом і степом: двадцять років платить за воду Енну й має намір пити її й надалі."],
  "Tends the date gardens round the pool, and talks to the palms. The palms have been answering less.": ["池のまわりのナツメヤシ園を世話し、ヤシに話しかける。ヤシの返事は近ごろ少なくなった。", "연못 둘레의 대추야자 정원을 돌보며 야자나무에게 말을 건다. 야자나무들의 대답이 줄어들고 있다.", "照料水池周围的椰枣园,还跟棕榈说话。棕榈的回应越来越少了。", "照料水池周圍的椰棗園,還跟棕櫚說話。棕櫚的回應越來越少了。", "Chăm sóc vườn chà là quanh hồ, và trò chuyện với những cây cọ. Cây cọ dạo này ít đáp lại hơn.", "Merawat kebun kurma di sekitar kolam, dan berbicara dengan pohon-pohon palem. Palem-palem makin jarang menjawab.", "ดูแลสวนอินทผลัมรอบสระ และพูดคุยกับต้นปาล์ม ต้นปาล์มตอบน้อยลงเรื่อยๆ", "Havuzun çevresindeki hurma bahçelerine bakar ve hurmalarla konuşur. Hurmalar daha az cevap veriyor.", "Cuida los huertos de dátiles alrededor de la poza y habla con las palmeras. Las palmeras le contestan cada vez menos.", "Cuida dos pomares de tâmaras em volta do lago e conversa com as palmeiras. As palmeiras têm respondido menos.", "Ухаживает за финиковыми садами вокруг пруда и разговаривает с пальмами. Пальмы отвечают всё реже.", "Доглядає фінікові сади довкола ставка й розмовляє з пальмами. Пальми відповідають дедалі рідше."],
  "Sells dates, flatbread and water skins from a stall by the pool, and the water at a price nobody is supposed to call a price.": ["池のそばの屋台でナツメヤシと平焼きパンと水袋を売り、水も売る。誰も値段と呼んではいけないことになっている値段で。", "연못가 가판대에서 대추야자와 납작빵과 물주머니를 팔고, 물도 판다. 아무도 값이라고 불러서는 안 되는 값에.", "在水池边的摊子上卖椰枣、烤饼和水袋,水也卖,价钱是一个谁都不该叫它价钱的价钱。", "在水池邊的攤子上賣椰棗、烤餅和水袋,水也賣,價錢是一個誰都不該叫它價錢的價錢。", "Bán chà là, bánh mì dẹt và túi đựng nước ở một sạp cạnh hồ, và cả nước, với một cái giá mà không ai được gọi là giá.", "Menjual kurma, roti pipih, dan kantong air di lapak dekat kolam, dan airnya juga, dengan harga yang tak boleh disebut harga.", "ขายอินทผลัม ขนมปังแผ่น และถุงน้ำที่แผงริมสระ และขายน้ำด้วย ในราคาที่ไม่มีใครควรเรียกว่าราคา", "Havuzun yanındaki bir tezgâhta hurma, yufka ve su tulumu satar; suyu da, kimsenin fiyat dememesi gereken bir fiyata.", "Vende dátiles, pan plano y odres en un puesto junto a la poza, y el agua, a un precio que nadie debe llamar precio.", "Vende tâmaras, pão chato e odres numa barraca junto ao lago, e a água também, a um preço que ninguém deve chamar de preço.", "Продаёт финики, лепёшки и бурдюки с лотка у пруда, а заодно и воду — по цене, которую никто не должен называть ценой.", "Продає фініки, коржі й бурдюки з ятки біля ставка, а заразом і воду — за ціною, яку ніхто не повинен називати ціною."],
  "A herd with the caravan's camels, who has opinions about every one of them and shares none of them with the camels.": ["隊商のラクダの番をしている者。一頭一頭について意見があるが、ラクダには一つも話さない。", "대상의 낙타를 돌보는 이. 낙타 한 마리 한 마리에 대해 의견이 있지만, 낙타에게는 하나도 말하지 않는다.", "看管商队骆驼的驼夫,对每一峰骆驼都有看法,可一句也不跟骆驼说。", "看管商隊駱駝的駝夫,對每一峰駱駝都有看法,可一句也不跟駱駝說。", "Một người chăn lạc đà của đoàn lữ hành, có ý kiến về từng con và chẳng chia sẻ ý nào với lũ lạc đà.", "Penggembala unta kafilah, yang punya pendapat tentang setiap unta dan tak membaginya dengan unta-unta itu.", "คนเลี้ยงอูฐของกองคาราวาน มีความเห็นต่ออูฐทุกตัว และไม่เคยบอกอูฐสักข้อ", "Kervanın develerine bakan, her biri hakkında fikri olan ve hiçbirini develerle paylaşmayan bir çoban.", "Un camellero de la caravana, que tiene opinión de cada uno de los camellos y no comparte ninguna con ellos.", "Um cameleiro da caravana, que tem opinião sobre cada um dos camelos e não partilha nenhuma com eles.", "Погонщик караванных верблюдов: у него есть мнение о каждом, но верблюдам он его не сообщает.", "Погонич караванних верблюдів: має думку про кожного, але верблюдам її не повідомляє."],
  "Someone of the oasis in Zuri indigo, a water jar on the hip, watching the level of the pool.": ["ズーリの藍をまとったオアシスの人。腰に水瓶をかかえ、池の水位を見つめている。", "주리 쪽빛을 입은 오아시스 사람. 허리에 물항아리를 끼고 연못 수위를 지켜본다.", "绿洲上的人,穿着祖里人的靛蓝,腰间挎着水罐,盯着水池的水位。", "綠洲上的人,穿著祖里人的靛藍,腰間挎著水罐,盯著水池的水位。", "Một người ở ốc đảo mặc chàm Zuri, vò nước bên hông, dõi theo mực nước hồ.", "Warga oasis bernila Zuri, kendi air di pinggang, mengawasi permukaan kolam.", "ชาวโอเอซิสในชุดครามแบบซูรี โอ่งน้ำที่สะโพก จับตาระดับน้ำในสระ", "Zuri çividi giymiş, belinde su testisi, havuzun seviyesini izleyen bir vaha sakini.", "Alguien del oasis vestido de añil zuri, con una tinaja a la cadera, vigilando el nivel de la poza.", "Alguém do oásis em anil zuri, com uma talha na cintura, vigiando o nível do lago.", "Житель оазиса в индиго зури, с кувшином у бедра, следящий за уровнем пруда.", "Мешканець оазису в індиго зурі, з глеком біля стегна, що стежить за рівнем ставка."],
  "Master of the Gullwick packet, red-faced from forty years of wind, who has been to every port on the chart and three that aren't.": ["ガルウィック定期船の船長。四十年の風で顔は赤い。海図にあるすべての港と、海図にない三つの港に行ったことがある。", "걸윅 정기선의 선장. 사십 년 바람에 얼굴이 붉다. 해도에 있는 모든 항구와, 해도에 없는 세 곳에 다녀왔다.", "鸥湾邮船的船长,四十年的海风把他的脸吹得通红。海图上的每个港口他都去过,海图上没有的也去过三个。", "鷗灣郵船的船長,四十年的海風把他的臉吹得通紅。海圖上的每個港口他都去過,海圖上沒有的也去過三個。", "Thuyền trưởng tàu chở khách Gullwick, mặt đỏ vì bốn mươi năm gió, đã đến mọi cảng trên hải đồ và ba cảng không có trên đó.", "Nakhoda kapal paket Gullwick, wajahnya merah oleh empat puluh tahun angin, yang sudah ke setiap pelabuhan di peta dan tiga yang tidak.", "นายเรือโดยสารแห่งกัลวิก หน้าแดงจากลมสี่สิบปี เคยไปมาแล้วทุกเมืองท่าบนแผนที่ และอีกสามแห่งที่ไม่มีในแผนที่", "Gullwick posta teknesinin reisi; kırk yıllık rüzgârdan yüzü kızarmış, haritadaki her limana ve haritada olmayan üçüne gitmiş.", "El patrón del paquebote de Gullwick, colorado de cuarenta años de viento, que ha estado en todos los puertos de la carta y en tres que no salen.", "O mestre do paquete de Gullwick, de rosto vermelho de quarenta anos de vento, que já esteve em todos os portos da carta e em três que não estão.", "Шкипер галлвикского пакетбота, красный от сорока лет ветра: бывал во всех портах на карте и в трёх, которых на ней нет.", "Шкіпер галлвіцького пакетбота, червоний від сорока років вітру: бував у всіх портах на мапі й у трьох, яких на ній немає."],
  "Rows the Saltreach packet out to the ships, and writes every passenger in the Ledger, coming and going.": ["ソルトリーチの定期船を漕いで船まで出し、行きも帰りも乗客を一人残らず台帳に記す。", "솔트리치 정기선을 저어 배들로 나가며, 오가는 승객을 빠짐없이 장부에 적는다.", "划着盐滩港的邮船把人送到大船上,每个乘客来来去去都记进册子。", "划著鹽灘港的郵船把人送到大船上,每個乘客來來去去都記進冊子。", "Chèo thuyền chở khách Saltreach ra tàu lớn, và ghi mọi hành khách vào Sổ, lúc đi lẫn lúc về.", "Mendayung kapal paket Saltreach ke kapal-kapal, dan mencatat setiap penumpang di Buku, datang maupun pergi.", "พายเรือโดยสารแห่งซอลต์รีชออกไปยังเรือใหญ่ และจดผู้โดยสารทุกคนลงสมุด ทั้งขาไปและขากลับ", "Saltreach posta teknesini gemilere kadar kürekler ve her yolcuyu, gelirken de giderken de Defter'e yazar.", "Rema el paquebote de Saltreach hasta los barcos y anota a cada pasajero en el Libro, a la ida y a la vuelta.", "Rema o paquete de Saltreach até os navios e escreve cada passageiro no Livro, na ida e na volta.", "Возит на вёслах солтричский пакетбот к кораблям и вписывает каждого пассажира в Книгу, туда и обратно.", "Везе на веслах солтрічський пакетбот до кораблів і вписує кожного пасажира до Книги, туди й назад."],
  "Captain of a trading dhow out of Merrab, who carries pearls east and passengers wherever they'll pay to go.": ["メラブから出る交易用ダウ船の船長。真珠を東へ、乗客を金を払う行き先ならどこへでも運ぶ。", "메라브에서 출항하는 교역용 다우선의 선장. 진주는 동쪽으로, 승객은 돈만 내면 어디든 실어 나른다.", "一艘从梅拉布出航的贸易三角帆船的船长,把珍珠运往东方,把乘客送到他们肯付钱去的任何地方。", "一艘從梅拉布出航的貿易三角帆船的船長,把珍珠運往東方,把乘客送到他們肯付錢去的任何地方。", "Thuyền trưởng một chiếc thuyền buồm dhow buôn bán từ Merrab, chở ngọc trai về phía đông và chở khách tới bất cứ đâu họ chịu trả tiền.", "Kapten kapal dhow dagang dari Merrab, yang membawa mutiara ke timur dan penumpang ke mana pun mereka mau bayar.", "กัปตันเรือเดาว์ค้าขายจากเมอร์รับ ขนไข่มุกไปทางตะวันออก และพาผู้โดยสารไปทุกที่ที่พวกเขายอมจ่าย", "Merrab'dan kalkan bir ticaret dhow'unun kaptanı; incileri doğuya, yolcuları da parasını verdikleri her yere taşır.", "La capitana de un dhow mercante de Merrab, que lleva perlas al este y pasajeros adonde paguen por ir.", "A capitã de um dhow mercante de Merrab, que leva pérolas para o leste e passageiros aonde pagarem para ir.", "Капитан торговой доу из Мерраба: возит жемчуг на восток, а пассажиров — куда заплатят.", "Капітанка торговельної доу з Меррабу: возить перли на схід, а пасажирів — куди заплатять."],
  "The free port's pilot, who brings every ship in past the shoals, and takes passengers out on the packet when there's room among the books.": ["自由港の水先案内人。すべての船を浅瀬の先へ導き入れ、本の積み荷の合間に余地があれば定期船で乗客を運び出す。", "자유항의 도선사. 모든 배를 여울 너머로 끌어들이고, 책 짐 사이에 자리가 있으면 정기선에 승객을 태워 나간다.", "自由港的引航员,带每条船绕过浅滩进港;书堆里还有空位的话,就用邮船载乘客出海。", "自由港的引航員,帶每條船繞過淺灘進港;書堆裡還有空位的話,就用郵船載乘客出海。", "Hoa tiêu của thương cảng tự do, đưa mọi con tàu vào qua bãi cạn, và chở khách ra trên thuyền khi còn chỗ giữa những chồng sách.", "Pandu pelabuhan bebas, yang membawa setiap kapal masuk melewati beting, dan membawa penumpang keluar dengan kapal paket bila ada tempat di antara buku-buku.", "ผู้นำร่องของเมืองท่าเสรี ผู้นำเรือทุกลำผ่านสันดอนเข้ามา และพาผู้โดยสารออกไปด้วยเรือโดยสารเมื่อยังมีที่ว่างระหว่างหนังสือ", "Özgür limanın kılavuzu; her gemiyi sığlıkların ötesinden içeri alır, kitapların arasında yer olduğunda yolcuları posta teknesiyle dışarı taşır.", "El práctico del puerto franco, que mete cada barco pasando los bajíos y saca pasajeros en el paquebote cuando hay sitio entre los libros.", "O prático do porto livre, que traz cada navio para dentro passando os baixios e leva passageiros no paquete quando há lugar entre os livros.", "Лоцман вольного порта: проводит каждый корабль мимо мелей и вывозит пассажиров на пакетботе, когда среди книг найдётся место.", "Лоцман вільного порту: проводить кожен корабель повз мілини й вивозить пасажирів пакетботом, коли серед книжок знайдеться місце."],
  "Every boat in or out of Gullwick goes past my window. I know who's late, who's lying, and who's both.": ["ガルウィックに出入りする船はみんな私の窓の前を通る。誰が遅れていて、誰が嘘をついていて、誰がその両方か、全部分かるよ。", "걸윅을 드나드는 배는 전부 내 창문 앞을 지나가. 누가 늦었는지, 누가 거짓말하는지, 누가 둘 다인지 다 알아.", "进出鸥湾的每条船都打我窗前过。谁晚了,谁撒谎,谁两样都占,我一清二楚。", "進出鷗灣的每條船都打我窗前過。誰晚了,誰撒謊,誰兩樣都占,我一清二楚。", "Mọi con thuyền ra vào Gullwick đều đi ngang cửa sổ của tôi. Tôi biết ai trễ, ai nói dối, và ai cả hai.", "Setiap perahu yang keluar masuk Gullwick lewat di depan jendelaku. Aku tahu siapa yang terlambat, siapa yang berbohong, dan siapa yang dua-duanya.", "เรือทุกลำที่เข้าออกกัลวิกผ่านหน้าต่างฉัน ฉันรู้ว่าใครมาช้า ใครโกหก และใครทั้งสองอย่าง", "Gullwick'e girip çıkan her tekne penceremin önünden geçer. Kim geç kalıyor, kim yalan söylüyor, kim ikisini birden yapıyor, bilirim.", "Cada barca que entra o sale de Gullwick pasa por delante de mi ventana. Sé quién llega tarde, quién miente y quién las dos cosas.", "Todo barco que entra ou sai de Gullwick passa pela minha janela. Sei quem está atrasado, quem está mentindo e quem está as duas coisas.", "Каждая лодка, что входит в Галлвик или выходит, проходит мимо моего окна. Я знаю, кто опаздывает, кто врёт и кто и то и другое.", "Кожен човен, що заходить у Галлвік чи виходить, пропливає повз моє вікно. Я знаю, хто спізнюється, хто бреше, а хто і те, і те."],
  "The Light's mine to see kept. Ossian keeps it. Somebody keeps putting it out. That's three people, and only two of them are honest.": ["灯台がちゃんと守られているか見るのは私の役目。守っているのはオシアン。そして誰かが消しつづけている。三人いて、正直なのは二人だけってわけさ。", "등대가 제대로 지켜지는지 보는 건 내 일이야. 지키는 건 오시안이고. 그리고 누군가 계속 불을 꺼. 세 사람인데, 정직한 건 둘뿐이지.", "灯塔有没有守好,归我管。守灯的是奥西安。有人老把灯弄灭。这就是三个人,其中只有两个是老实的。", "燈塔有沒有守好,歸我管。守燈的是奧西安。有人老把燈弄滅。這就是三個人,其中只有兩個是老實的。", "Trông cho Đèn được giữ là việc của tôi. Ossian giữ nó. Có kẻ cứ làm nó tắt. Thế là ba người, và chỉ hai trong số đó lương thiện.", "Memastikan Mercusuar terjaga itu tugasku. Ossian yang menjaganya. Seseorang terus memadamkannya. Itu tiga orang, dan cuma dua yang jujur.", "การดูให้ประภาคารถูกดูแลเป็นหน้าที่ฉัน ออสเซียนดูแลมัน มีใครบางคนคอยดับมัน นั่นสามคน และซื่อสัตย์อยู่แค่สอง", "Fenerin bakılmasını gözetmek benim işim. Ona Ossian bakar. Biri de onu söndürüp duruyor. Bu üç kişi eder ve yalnızca ikisi dürüst.", "Que el faro se mantenga es cosa mía. Ossian lo mantiene. Alguien no para de apagarlo. Eso son tres personas, y solo dos son honradas.", "Cuidar que o farol seja mantido é comigo. Ossian o mantém. Alguém vive apagando-o. São três pessoas, e só duas são honestas.", "Следить, чтобы маяк горел, — моё дело. Поддерживает его Оссиан. А кто-то его гасит. Это три человека, и честных среди них только двое.", "Пильнувати, щоб маяк горів, — моя справа. Підтримує його Оссіан. А хтось його гасить. Це троє людей, і чесних серед них лише двоє."],
  "The Collector wants a new harbour wall. The fishers want to eat. The sea wants the wall. I want a quiet week, and I'll want it for ever.": ["徴税官は新しい防波堤がほしい。漁師たちは食べたい。海は堤がほしい。私は静かな一週間がほしいけど、いつまでもほしがるだけだろうね。", "징수관은 새 항구 방벽을 원하고, 어부들은 먹기를 원하고, 바다는 방벽을 원해. 나는 조용한 한 주를 원하는데, 영원히 원하기만 하겠지.", "税务官想要一道新防波墙。渔民想吃饱。大海想要那道墙。我想要清静一个礼拜,怕是要想一辈子了。", "稅務官想要一道新防波牆。漁民想吃飽。大海想要那道牆。我想要清靜一個禮拜,怕是要想一輩子了。", "Quan thu thuế muốn một bức tường cảng mới. Dân chài muốn được ăn. Biển muốn bức tường. Tôi muốn một tuần yên ổn, và tôi sẽ muốn nó mãi mãi.", "Pemungut ingin tembok pelabuhan baru. Para nelayan ingin makan. Laut ingin temboknya. Aku ingin seminggu yang tenang, dan aku akan menginginkannya selamanya.", "เจ้าพนักงานเก็บภาษีอยากได้กำแพงท่าเรือใหม่ ชาวประมงอยากกินอิ่ม ทะเลอยากได้กำแพง ฉันอยากได้สัปดาห์ที่สงบสักสัปดาห์ และคงอยากไปตลอดกาล", "Tahsildar yeni bir liman duvarı istiyor. Balıkçılar yemek istiyor. Deniz duvarı istiyor. Ben sessiz bir hafta istiyorum ve sonsuza dek isteyip duracağım.", "El Recaudador quiere un muro nuevo para el puerto. Los pescadores quieren comer. El mar quiere el muro. Yo quiero una semana tranquila, y la querré siempre.", "O Coletor quer um muro novo para o porto. Os pescadores querem comer. O mar quer o muro. Eu quero uma semana sossegada, e vou querê-la para sempre.", "Сборщик хочет новую портовую стену. Рыбаки хотят есть. Море хочет стену. А я хочу тихую неделю и буду хотеть её вечно.", "Збирач хоче нову портову стіну. Рибалки хочуть їсти. Море хоче стіну. А я хочу тихий тиждень і хотітиму його вічно."],
  "The harbour wall is falling into the sea, stone by stone. Dues build walls. Sentiment doesn't.": ["防波堤は石ひとつずつ海に崩れている。堤を築くのは税だ。情ではない。", "항구 방벽이 돌 하나씩 바다로 무너지고 있소. 방벽을 쌓는 건 세금이오. 감상이 아니라.", "港口的防波墙正一块石头一块石头地往海里塌。修墙靠的是税,不是感情。", "港口的防波牆正一塊石頭一塊石頭地往海裡塌。修牆靠的是稅,不是感情。", "Tường cảng đang đổ xuống biển, từng hòn đá một. Thuế xây nên tường. Tình cảm thì không.", "Tembok pelabuhan runtuh ke laut, batu demi batu. Bea membangun tembok. Perasaan tidak.", "กำแพงท่าเรือกำลังพังลงทะเลทีละก้อน ค่าธรรมเนียมสร้างกำแพง ความรู้สึกสร้างไม่ได้", "Liman duvarı taş taş denize çöküyor. Duvarı vergiler yapar. Duygular yapmaz.", "El muro del puerto se cae al mar, piedra a piedra. Los derechos levantan muros. Los sentimientos, no.", "O muro do porto está caindo no mar, pedra por pedra. Taxas erguem muros. Sentimentos, não.", "Портовая стена падает в море камень за камнем. Стены строят сборы. Чувства — нет.", "Портова стіна падає в море камінь за каменем. Стіни будують збори. Почуття — ні."],
  "The fishers say the dues are too high. The dues are exactly as high as the wall is long, and the wall is very long.": ["漁師たちは税が高すぎると言う。税は堤の長さとちょうど同じだけ高い。そして堤はとても長い。", "어부들은 세금이 너무 높다고 하오. 세금은 방벽 길이만큼 정확히 높소. 그리고 방벽은 아주 길지.", "渔民说税太高。税恰恰和墙一样长那么高,而那道墙非常长。", "漁民說稅太高。稅恰恰和牆一樣長那麼高,而那道牆非常長。", "Dân chài bảo thuế quá cao. Thuế cao đúng bằng tường dài, mà tường thì rất dài.", "Para nelayan bilang bea terlalu tinggi. Bea itu persis setinggi tembok itu panjang, dan temboknya sangat panjang.", "ชาวประมงว่าค่าธรรมเนียมสูงเกินไป ค่าธรรมเนียมสูงพอดีกับความยาวของกำแพง และกำแพงก็ยาวมาก", "Balıkçılar vergilerin çok yüksek olduğunu söylüyor. Vergiler tam olarak duvarın uzunluğu kadar yüksek ve duvar çok uzun.", "Los pescadores dicen que los derechos son demasiado altos. Los derechos son exactamente tan altos como largo es el muro, y el muro es muy largo.", "Os pescadores dizem que as taxas são altas demais. As taxas são exatamente tão altas quanto o muro é comprido, e o muro é muito comprido.", "Рыбаки говорят, что сборы слишком высоки. Сборы ровно так высоки, как длинна стена, а стена очень длинная.", "Рибалки кажуть, що збори зависокі. Збори рівно такі високі, яка довга стіна, а стіна дуже довга."],
  "I'm not loved. Collectors aren't. I'm right, which is worse.": ["私は好かれていない。徴税官というのはそういうものだ。しかも正しい。そのほうが始末が悪い。", "나는 사랑받지 못하오. 징수관은 원래 그렇지. 게다가 나는 옳소. 그게 더 나쁘지.", "没人喜欢我。税务官都这样。而我还是对的,那就更糟了。", "沒人喜歡我。稅務官都這樣。而我還是對的,那就更糟了。", "Tôi không được yêu mến. Quan thu thuế đều thế. Tôi lại đúng, thế còn tệ hơn.", "Aku tak disukai. Pemungut memang tidak. Aku benar, dan itu lebih buruk.", "ไม่มีใครรักผม เจ้าพนักงานเก็บภาษีก็เป็นอย่างนี้ ผมถูก ซึ่งแย่กว่า", "Sevilmem. Tahsildarlar sevilmez. Haklıyım, ki bu daha kötü.", "No me quieren. A los recaudadores no se los quiere. Tengo razón, que es peor.", "Não sou amado. Coletores não são. Tenho razão, o que é pior.", "Меня не любят. Сборщиков не любят. Я прав, а это хуже.", "Мене не люблять. Збирачів не люблять. Я маю рацію, а це гірше."],
  "Thirty years I've kept her lit. Dusk to dawn, every night. You learn her moods: a lamp's a living thing, near enough.": ["三十年、あの灯をともしてきた。夕暮れから夜明けまで、毎晩な。気分ってものが分かってくる。灯はほとんど生き物さ。", "삼십 년 동안 저 불을 밝혀 왔지. 해 질 녘부터 새벽까지, 매일 밤. 그 기분을 알게 돼. 등불은 거의 살아 있는 거야.", "三十年了,我一直让她亮着。从黄昏到天明,夜夜如此。你会摸清她的脾气:灯差不多就是个活物。", "三十年了,我一直讓她亮著。從黃昏到天明,夜夜如此。你會摸清她的脾氣:燈差不多就是個活物。", "Ba mươi năm tôi giữ cho nàng sáng. Từ chạng vạng tới bình minh, mọi đêm. Rồi anh hiểu tính khí nàng: ngọn đèn gần như là một sinh vật sống.", "Tiga puluh tahun aku menjaganya tetap menyala. Senja sampai fajar, setiap malam. Kau belajar suasana hatinya: lampu itu nyaris makhluk hidup.", "สามสิบปีที่ผมดูแลให้เธอสว่าง ตั้งแต่พลบค่ำจนรุ่งเช้า ทุกคืน คุณจะรู้อารมณ์ของเธอ ตะเกียงก็เกือบเป็นสิ่งมีชีวิตนั่นแหละ", "Otuz yıldır onu yanık tutuyorum. Akşamdan şafağa, her gece. Huylarını öğrenirsin: bir lamba neredeyse canlı bir şeydir.", "Treinta años lo he tenido encendido. Del ocaso al alba, cada noche. Aprendes sus humores: una lámpara es casi un ser vivo.", "Trinta anos eu o mantive aceso. Do anoitecer ao amanhecer, toda noite. Você aprende os humores dele: uma lâmpada é quase um ser vivo.", "Тридцать лет я держу её зажжённой. От заката до рассвета, каждую ночь. Узнаёшь её нрав: лампа — почти живое существо.", "Тридцять років я тримаю її запаленою. Від заходу до світанку, щоночі. Пізнаєш її вдачу: лампа — майже жива істота."],
  "Saltmarrow lost the Gullwing on the rocks before there was a light here. They built her after. Some nights I think of that.": ["ここに灯がなかったころ、ソルトマロウはガルウィング号を岩で失った。灯台はそのあとで建てられたんだ。夜によっては、そのことを考える。", "여기 등대가 없던 시절, 솔트매로는 갈매기날개호를 바위에서 잃었어. 등대는 그 뒤에 세웠지. 어떤 밤엔 그 생각을 해.", "这里还没有灯的时候,盐髓港的“鸥翼号”就撞上礁石沉了。灯塔是那之后才建的。有些夜里我会想起这事。", "這裡還沒有燈的時候,鹽髓港的「鷗翼號」就撞上礁石沉了。燈塔是那之後才建的。有些夜裡我會想起這事。", "Saltmarrow mất tàu Gullwing trên đá ngầm khi ở đây chưa có đèn. Người ta xây đèn sau đó. Có những đêm tôi nghĩ về chuyện ấy.", "Saltmarrow kehilangan Gullwing di karang sebelum ada lampu di sini. Mercusuar dibangun setelahnya. Beberapa malam aku memikirkannya.", "ซอลต์แมร์โรว์เสียเรือกัลวิงที่โขดหินก่อนที่นี่จะมีประภาคาร พวกเขาสร้างมันขึ้นทีหลัง บางคืนผมก็นึกถึงเรื่องนั้น", "Burada daha fener yokken Saltmarrow Gullwing'i kayalarda kaybetti. Feneri ondan sonra yaptılar. Bazı geceler bunu düşünürüm.", "Saltmarrow perdió el Gullwing en las rocas antes de que hubiera faro aquí. Lo construyeron después. Algunas noches pienso en eso.", "Saltmarrow perdeu o Gullwing nas rochas antes de haver luz aqui. O farol foi construído depois. Algumas noites penso nisso.", "Солтмэрроу потерял «Гуллвинг» на скалах, когда здесь ещё не было огня. Маяк построили после. Иной ночью я об этом думаю.", "Солтмерроу втратив «Гуллвінг» на скелях, коли тут ще не було вогню. Маяк збудували потім. Іноді вночі я про це думаю."],
  "Oil, wick, glass, and a keeper who doesn't sleep. That's all a lighthouse is.": ["油と芯とガラス、それに眠らない灯台守。灯台なんてそれだけのものさ。", "기름, 심지, 유리, 그리고 잠들지 않는 등대지기. 등대란 그게 전부야.", "油、灯芯、玻璃,再加一个不睡觉的守灯人。灯塔就是这么回事。", "油、燈芯、玻璃,再加一個不睡覺的守燈人。燈塔就是這麼回事。", "Dầu, bấc, kính, và một người giữ đèn không ngủ. Hải đăng chỉ có vậy.", "Minyak, sumbu, kaca, dan penjaga yang tak tidur. Itulah mercusuar.", "น้ำมัน ไส้ตะเกียง กระจก และผู้เฝ้าที่ไม่นอน ประภาคารก็มีแค่นั้น", "Yağ, fitil, cam ve uyumayan bir bekçi. Deniz feneri bundan ibaret.", "Aceite, mecha, cristal y un farero que no duerme. Un faro no es más que eso.", "Óleo, pavio, vidro e um faroleiro que não dorme. Um farol não é mais que isso.", "Масло, фитиль, стекло и смотритель, который не спит. Вот и весь маяк.", "Олія, ґніт, скло й доглядач, що не спить. Ось і весь маяк."],
  "Sit down, love, you're letting the weather in. Stew's the same as yesterday's, only better.": ["座りなよ、あんた、外の天気が入ってくるじゃないか。シチューは昨日と同じ。ただもっとおいしい。", "앉아요, 자기, 날씨 들어오잖아요. 스튜는 어제랑 같아요, 더 맛있을 뿐.", "坐下吧,亲爱的,你把风雨都放进来了。炖菜跟昨天的一样,只是更好吃。", "坐下吧,親愛的,你把風雨都放進來了。燉菜跟昨天的一樣,只是更好吃。", "Ngồi đi cưng, cưng để gió mưa lùa vào đấy. Món hầm vẫn như hôm qua, chỉ ngon hơn.", "Duduklah, Sayang, kau membiarkan cuaca masuk. Semurnya sama dengan kemarin, cuma lebih enak.", "นั่งลงสิจ๊ะ เธอปล่อยลมฝนเข้ามาแล้ว สตูว์เหมือนเมื่อวาน แค่อร่อยกว่า", "Otur, canım, havayı içeri sokuyorsun. Yahni dünküyle aynı, yalnızca daha iyi.", "Siéntate, cariño, que dejas entrar el tiempo. El guiso es el mismo de ayer, solo que mejor.", "Senta, querido, você está deixando o tempo entrar. O ensopado é o mesmo de ontem, só que melhor.", "Садись, милок, погоду в дом напускаешь. Похлёбка та же, что вчера, только лучше.", "Сідай, любчику, погоду в хату напускаєш. Юшка та сама, що вчора, тільки краща."],
  "Fishers at the window, the Collector's men by the door, and nobody sits in between. I put the stew in between.": ["窓際には漁師、戸口には徴税官の手下、そのあいだには誰も座らない。だからあいだにはシチューを置くのさ。", "창가엔 어부들, 문가엔 징수관 패거리, 그 사이엔 아무도 안 앉아요. 그래서 사이에 스튜를 놓죠.", "窗边坐渔民,门边坐税务官的人,中间谁也不坐。我就把炖菜摆在中间。", "窗邊坐漁民,門邊坐稅務官的人,中間誰也不坐。我就把燉菜擺在中間。", "Dân chài ngồi bên cửa sổ, người của Quan thu thuế ngồi cạnh cửa, chẳng ai ngồi ở giữa. Tôi đặt nồi hầm vào giữa.", "Nelayan di dekat jendela, anak buah Pemungut di dekat pintu, dan tak ada yang duduk di antaranya. Aku taruh semur di antaranya.", "ชาวประมงนั่งริมหน้าต่าง คนของเจ้าพนักงานเก็บภาษีนั่งข้างประตู ไม่มีใครนั่งตรงกลาง ฉันเลยวางสตูว์ไว้ตรงกลาง", "Pencerede balıkçılar, kapının yanında Tahsildar'ın adamları, arada kimse oturmaz. Araya yahniyi koyarım.", "Los pescadores en la ventana, los hombres del Recaudador junto a la puerta, y nadie se sienta en medio. En medio pongo el guiso.", "Os pescadores na janela, os homens do Coletor junto à porta, e ninguém senta no meio. No meio eu ponho o ensopado.", "Рыбаки у окна, люди сборщика у двери, а посередине никто не садится. Посередине я ставлю похлёбку.", "Рибалки біля вікна, люди збирача біля дверей, а посередині ніхто не сідає. Посередині я ставлю юшку."],
  "Rope, tar, hooks, floats, oil. Everything a boat needs except luck. Luck's at the inn, I'm told.": ["縄、タール、釣り針、浮き、油。運以外なら船に要るものは何でもある。運は宿にあるって聞いたよ。", "밧줄, 타르, 낚싯바늘, 부표, 기름. 배에 필요한 건 운 빼고 다 있소. 운은 여관에 있다고 들었소.", "绳子、沥青、鱼钩、浮子、油。船要的东西样样都有,除了运气。听说运气在客栈里。", "繩子、瀝青、魚鉤、浮子、油。船要的東西樣樣都有,除了運氣。聽說運氣在客棧裡。", "Dây thừng, nhựa đường, lưỡi câu, phao, dầu. Mọi thứ thuyền cần trừ may mắn. Nghe nói may mắn ở quán trọ.", "Tali, ter, kail, pelampung, minyak. Semua yang dibutuhkan perahu kecuali keberuntungan. Keberuntungan ada di penginapan, katanya.", "เชือก น้ำมันดิน เบ็ด ทุ่น น้ำมัน ทุกอย่างที่เรือต้องการยกเว้นโชค ได้ยินว่าโชคอยู่ที่โรงเตี๊ยม", "İp, katran, olta iğnesi, şamandıra, yağ. Bir teknenin şanstan başka ihtiyacı olan her şey. Şans handaymış, öyle diyorlar.", "Cuerda, brea, anzuelos, flotadores, aceite. Todo lo que necesita una barca menos suerte. La suerte está en la posada, me dicen.", "Corda, piche, anzóis, boias, óleo. Tudo de que um barco precisa, menos sorte. A sorte fica na estalagem, me dizem.", "Верёвка, дёготь, крючки, поплавки, масло. Всё, что нужно лодке, кроме удачи. Удача, говорят, в трактире.", "Мотузка, дьоготь, гачки, поплавці, олія. Усе, що потрібно човнові, крім удачі. Удача, кажуть, у корчмі."],
  "Half my customers are on the slate since the dues went up. A slate doesn't float, I tell them. They laugh. I don't.": ["税が上がってから、客の半分はつけ払いだ。つけは浮かないぞって言ってやる。連中は笑う。俺は笑わない。", "세금이 오른 뒤로 손님 절반이 외상이오. 외상 장부는 물에 안 뜬다고 말해 주지. 그들은 웃소. 나는 안 웃고.", "税一涨,我一半的主顾都赊账了。我跟他们说,账板可浮不起来。他们笑。我笑不出来。", "稅一漲,我一半的主顧都賒帳了。我跟他們說,帳板可浮不起來。他們笑。我笑不出來。", "Từ khi thuế tăng, nửa số khách của tôi ghi nợ. Tôi bảo họ, sổ nợ không nổi được đâu. Họ cười. Tôi thì không.", "Separuh pelangganku berutang sejak bea naik. Catatan utang tak bisa mengapung, kubilang. Mereka tertawa. Aku tidak.", "ลูกค้าครึ่งหนึ่งติดหนี้ตั้งแต่ค่าธรรมเนียมขึ้น ผมบอกพวกเขาว่าบัญชีหนี้ลอยน้ำไม่ได้นะ พวกเขาหัวเราะ ผมไม่หัวเราะ", "Vergiler arttığından beri müşterilerimin yarısı veresiye. Veresiye defteri yüzmez, diyorum. Gülüyorlar. Ben gülmüyorum.", "La mitad de mis clientes compra fiado desde que subieron los derechos. Lo fiado no flota, les digo. Ellos se ríen. Yo no.", "Metade dos meus fregueses compra fiado desde que as taxas subiram. Fiado não boia, digo a eles. Eles riem. Eu não.", "С тех пор как подняли сборы, половина покупателей берёт в долг. Долг не держится на плаву, говорю я им. Они смеются. Я нет.", "Відколи підняли збори, половина покупців бере в борг. Борг не тримається на плаву, кажу я їм. Вони сміються. Я ні."],
  "Fresh this morning! Well. This morning's this morning. Yesterday's is cheaper.": ["今朝揚がったばかり!まあね。今朝のは今朝の。昨日のは安いよ。", "오늘 아침 거예요! 뭐, 오늘 아침 건 오늘 아침 거고. 어제 건 더 싸요.", "今早刚到的!呃,今早的是今早的。昨天的便宜些。", "今早剛到的!呃,今早的是今早的。昨天的便宜些。", "Tươi sáng nay! Thì. Hàng sáng nay là sáng nay. Hàng hôm qua rẻ hơn.", "Segar pagi ini! Yah. Yang pagi ini ya pagi ini. Yang kemarin lebih murah.", "สดเมื่อเช้า! ก็นะ ของเมื่อเช้าก็ของเมื่อเช้า ของเมื่อวานถูกกว่า", "Bu sabah taze! Yani. Bu sabahki bu sabahki. Dünkü daha ucuz.", "¡Fresco de esta mañana! Bueno. Lo de esta mañana es de esta mañana. Lo de ayer, más barato.", "Fresco desta manhã! Bem. O desta manhã é desta manhã. O de ontem é mais barato.", "Свежее, утреннее! Ну. Утреннее — утреннее. Вчерашнее дешевле.", "Свіже, ранкове! Ну. Ранкове — ранкове. Учорашнє дешевше."],
  "Half the boats are tied up. Can't pay the landing dues, so they don't land. So I've nothing to sell. So nobody pays me. Round it goes.": ["船の半分はもやいっぱなし。陸揚げ料が払えないから陸揚げしない。だから売るものがない。だから誰も私に払わない。ぐるぐる回るのさ。", "배 절반이 묶여 있어요. 양륙료를 못 내니 뭍에 안 올리죠. 그러니 팔 게 없고. 그러니 아무도 나한테 돈을 안 내고. 돌고 도는 거죠.", "一半的船都拴着不动。付不起卸货费,就不卸货。我就没东西卖。就没人付我钱。就这么转圈。", "一半的船都拴著不動。付不起卸貨費,就不卸貨。我就沒東西賣。就沒人付我錢。就這麼轉圈。", "Nửa số thuyền đang cột lại. Không trả nổi phí bốc dỡ thì không cập bờ. Thế là tôi chẳng có gì bán. Thế là chẳng ai trả tiền cho tôi. Cứ thế quay vòng.", "Separuh perahu ditambat. Tak sanggup bayar bea bongkar, jadi tak membongkar. Jadi aku tak punya apa-apa untuk dijual. Jadi tak ada yang membayarku. Begitu terus berputar.", "เรือครึ่งหนึ่งผูกไว้เฉยๆ จ่ายค่าขึ้นฝั่งไม่ไหวก็ไม่ขึ้นฝั่ง ฉันก็ไม่มีอะไรขาย ก็ไม่มีใครจ่ายเงินฉัน วนไปอย่างนี้", "Teknelerin yarısı bağlı. Boşaltma vergisini ödeyemiyorlar, o yüzden boşaltmıyorlar. O yüzden satacak bir şeyim yok. O yüzden kimse bana ödemiyor. Dönüp duruyor.", "La mitad de las barcas están amarradas. No pueden pagar el desembarco, así que no desembarcan. Así que no tengo nada que vender. Así que nadie me paga. Y vuelta a empezar.", "Metade dos barcos está amarrada. Não podem pagar o desembarque, então não desembarcam. Então não tenho o que vender. Então ninguém me paga. E assim vai.", "Половина лодок на приколе. Не могут заплатить выгрузной сбор, вот и не выгружаются. Вот мне и нечего продавать. Вот никто мне и не платит. И так по кругу.", "Половина човнів на приколі. Не можуть сплатити вивантажувальний збір, то й не вивантажуються. То мені й нічого продавати. То ніхто мені й не платить. І так по колу."],
  "Walk backwards, twist, walk backwards. A cable's three hundred paces, and I've walked every one of them twice.": ["後ろへ歩き、よって、また後ろへ歩く。太綱一本は三百歩、その一歩一歩を俺は二度ずつ歩いてきた。", "뒷걸음질, 꼬고, 뒷걸음질. 굵은 밧줄 하나가 삼백 걸음이고, 나는 그 걸음걸음을 두 번씩 걸었지.", "倒着走,捻,倒着走。一根缆绳三百步,每一步我都走过两遍。", "倒著走,捻,倒著走。一根纜繩三百步,每一步我都走過兩遍。", "Đi lùi, xoắn, đi lùi. Một sợi cáp dài ba trăm bước, và tôi đã đi mỗi bước hai lần.", "Mundur, pilin, mundur. Satu tambang tiga ratus langkah, dan aku sudah menapaki setiap langkahnya dua kali.", "เดินถอยหลัง บิด เดินถอยหลัง เชือกเคเบิลหนึ่งเส้นยาวสามร้อยก้าว และผมเดินทุกก้าวมาแล้วสองรอบ", "Geri yürü, bük, geri yürü. Bir halat üç yüz adım ve her birini iki kez yürüdüm.", "Andar hacia atrás, torcer, andar hacia atrás. Un cable son trescientos pasos, y los he andado todos dos veces.", "Andar de costas, torcer, andar de costas. Um cabo tem trezentos passos, e eu andei cada um deles duas vezes.", "Шаг назад, скрутить, шаг назад. Канат — это триста шагов, и я прошёл каждый из них дважды.", "Крок назад, скрутити, крок назад. Канат — це триста кроків, і я пройшов кожен із них двічі."],
  "The Light's oil comes in on rope I laid, the boats are tied up with rope I laid, and the Collector's men hang their lanterns on rope I laid. I'm everyone's, me.": ["灯台の油は俺のなった縄で運び込まれ、船は俺のなった縄でつながれ、徴税官の手下は俺のなった縄でランタンを吊るす。俺はみんなのものさ。", "등대 기름은 내가 꼰 밧줄로 들여오고, 배는 내가 꼰 밧줄로 묶고, 징수관 패거리는 내가 꼰 밧줄에 등불을 걸지. 나는 모두의 것이야.", "灯塔的油是用我搓的绳子运进来的,船是用我搓的绳子拴的,税务官的人也是用我搓的绳子挂灯笼。我啊,是大家的。", "燈塔的油是用我搓的繩子運進來的,船是用我搓的繩子拴的,稅務官的人也是用我搓的繩子掛燈籠。我啊,是大家的。", "Dầu của Đèn được đưa vào bằng dây tôi bện, thuyền buộc bằng dây tôi bện, người của Quan thu thuế treo đèn lồng bằng dây tôi bện. Tôi là của mọi người.", "Minyak Mercusuar datang dengan tali pilinanku, perahu ditambat dengan tali pilinanku, dan anak buah Pemungut menggantung lentera mereka dengan tali pilinanku. Aku milik semua orang.", "น้ำมันของประภาคารขนมาด้วยเชือกที่ผมฟั่น เรือผูกด้วยเชือกที่ผมฟั่น คนของเจ้าพนักงานเก็บภาษีแขวนตะเกียงด้วยเชือกที่ผมฟั่น ผมเป็นของทุกคน", "Fenerin yağı benim büktüğüm halatla gelir, tekneler benim büktüğüm halatla bağlanır, Tahsildar'ın adamları fenerlerini benim büktüğüm halata asar. Ben herkesinim.", "El aceite del faro llega con cuerda que torcí yo, las barcas se amarran con cuerda que torcí yo, y los hombres del Recaudador cuelgan sus faroles de cuerda que torcí yo. Soy de todos, yo.", "O óleo do farol chega em corda que eu torci, os barcos são amarrados com corda que eu torci, e os homens do Coletor penduram as lanternas em corda que eu torci. Eu sou de todo mundo.", "Масло для маяка везут на моих канатах, лодки привязаны моими канатами, люди сборщика вешают фонари на мои канаты. Я, выходит, общий.", "Олію для маяка везуть на моїх канатах, човни прив'язані моїми канатами, люди збирача вішають ліхтарі на мої канати. Я, виходить, спільний."],
  "Every family's gansey has its own pattern. Ropes, ladders, nets, waves. If the sea gives one back, we know whose it is.": ["どの家のガンジーにも自分たちの模様がある。縄、梯子、網、波。海が誰かを返してよこしたら、それが誰か分かるんだよ。", "집집마다 건지 스웨터에 자기 무늬가 있어요. 밧줄, 사다리, 그물, 파도. 바다가 하나를 돌려보내면, 누구네인지 알 수 있죠.", "每家的渔夫毛衣都有自己的花纹:绳纹、梯纹、网纹、浪纹。要是大海送回来一个,我们就知道是谁家的。", "每家的漁夫毛衣都有自己的花紋:繩紋、梯紋、網紋、浪紋。要是大海送回來一個,我們就知道是誰家的。", "Áo gansey của mỗi nhà có hoa văn riêng. Dây thừng, thang, lưới, sóng. Nếu biển trả lại một người, chúng tôi biết đó là người nhà ai.", "Sweter gansey tiap keluarga punya polanya sendiri. Tali, tangga, jala, ombak. Kalau laut mengembalikan seseorang, kami tahu milik siapa.", "เสื้อแกนซีของแต่ละตระกูลมีลายของตัวเอง เชือก บันได อวน คลื่น ถ้าทะเลส่งใครกลับมา เราก็รู้ว่าเป็นของบ้านไหน", "Her ailenin ganseyinin kendi deseni vardır. Halatlar, merdivenler, ağlar, dalgalar. Deniz birini geri verirse, kimin olduğunu biliriz.", "El gansey de cada familia tiene su dibujo. Cuerdas, escaleras, redes, olas. Si el mar devuelve a alguien, sabemos de quién es.", "O gansey de cada família tem seu padrão. Cordas, escadas, redes, ondas. Se o mar devolve alguém, sabemos de quem é.", "У каждой семьи свой узор на гернси. Канаты, лесенки, сети, волны. Если море вернёт кого-то, мы знаем, чей он.", "У кожної родини свій візерунок на гернсі. Канати, драбинки, сіті, хвилі. Якщо море поверне когось, ми знаємо, чий він."],
  "My husband went down off Wrack Point the year the Light was dark for a storm. Twenty years. I don't go out on the point.": ["夫は、嵐で灯台が消えた年にレック岬の沖で沈んだ。二十年になる。私は岬には出ないよ。", "남편은 폭풍 때문에 등대가 꺼졌던 해에 렉 곶 앞바다에서 가라앉았어요. 이십 년이죠. 난 곶에 안 나가요.", "我男人在灯塔因为风暴熄掉的那年,在残骸岬外沉了。二十年了。我不去那个岬角。", "我男人在燈塔因為風暴熄掉的那年,在殘骸岬外沉了。二十年了。我不去那個岬角。", "Chồng tôi chìm ngoài mũi Wrack năm Đèn tắt vì bão. Hai mươi năm rồi. Tôi không ra mũi đất ấy.", "Suamiku tenggelam di lepas Tanjung Wrack pada tahun Mercusuar padam karena badai. Dua puluh tahun. Aku tak pergi ke tanjung itu.", "สามีฉันจมนอกแหลมแร็กในปีที่ประภาคารดับเพราะพายุ ยี่สิบปีแล้ว ฉันไม่ออกไปที่แหลมนั้น", "Kocam, fenerin fırtınada karanlık kaldığı yıl Wrack Burnu açığında battı. Yirmi yıl. Ben buruna çıkmam.", "Mi marido se hundió frente a la Punta Wrack el año que el faro se apagó por una tormenta. Veinte años. Yo no salgo a la punta.", "Meu marido afundou na Ponta Wrack no ano em que o farol se apagou por causa de uma tempestade. Vinte anos. Eu não vou à ponta.", "Мой муж утонул у мыса Рэк в тот год, когда маяк погас из-за бури. Двадцать лет. Я на мыс не хожу.", "Мій чоловік утонув біля мису Рек того року, коли маяк погас через бурю. Двадцять років. Я на мис не ходжу."],
  "Kit's boat's tied up. Can't pay the dues, can't fish; can't fish, can't pay. He's young. Young men find other things to do.": ["キットの船はもやったまま。税が払えなきゃ漁に出られない。漁に出られなきゃ払えない。あの子は若い。若い男はほかにすることを見つけるもんさ。", "킷의 배는 묶여 있어요. 세금을 못 내면 고기를 못 잡고, 고기를 못 잡으면 못 내고. 그 애는 젊어요. 젊은 사내들은 다른 할 일을 찾아내죠.", "基特的船拴着。交不起税就不能打鱼,不能打鱼就交不起税。他年轻。年轻人总会找点别的事干。", "基特的船拴著。交不起稅就不能打魚,不能打魚就交不起稅。他年輕。年輕人總會找點別的事幹。", "Thuyền của Kit đang cột. Không trả được thuế thì không đánh cá được; không đánh cá thì không trả được. Nó còn trẻ. Đàn ông trẻ sẽ tìm ra việc khác để làm.", "Perahu Kit ditambat. Tak bisa bayar bea, tak bisa melaut; tak bisa melaut, tak bisa bayar. Ia masih muda. Pemuda selalu menemukan hal lain untuk dikerjakan.", "เรือของคิตผูกไว้ จ่ายค่าธรรมเนียมไม่ได้ก็ออกหาปลาไม่ได้ ออกหาปลาไม่ได้ก็จ่ายไม่ได้ เขายังหนุ่ม ผู้ชายหนุ่มก็หาอย่างอื่นทำ", "Kit'in teknesi bağlı. Vergiyi ödeyemezsen balığa çıkamazsın; balığa çıkamazsan ödeyemezsin. Genç o. Genç adamlar yapacak başka şeyler bulur.", "La barca de Kit está amarrada. No puede pagar los derechos, no puede pescar; no puede pescar, no puede pagar. Es joven. Los jóvenes encuentran otras cosas que hacer.", "O barco de Kit está amarrado. Não pode pagar as taxas, não pode pescar; não pode pescar, não pode pagar. Ele é jovem. Os rapazes encontram outras coisas para fazer.", "Лодка Кита на приколе. Не заплатишь сбор — не порыбачишь; не порыбачишь — не заплатишь. Он молод. Молодые находят себе другие занятия.", "Човен Кіта на приколі. Не сплатиш збору — не порибалиш; не порибалиш — не сплатиш. Він молодий. Молоді знаходять собі інші заняття."],
  "Landing dues, berth dues, and now harbour improvement. I've improved nothing but my vocabulary.": ["陸揚げ料に停泊料、今度は港湾改良ときた。改良されたのは俺の悪態の語彙だけだ。", "양륙료, 정박료, 이제는 항만 개량이래. 개량된 건 내 욕 실력뿐이야.", "卸货费、泊位费,现在又来个港口改良。改良的只有我骂人的词儿。", "卸貨費、泊位費,現在又來個港口改良。改良的只有我罵人的詞兒。", "Phí bốc dỡ, phí bến, giờ thêm cải tạo cảng. Tôi chẳng cải tạo được gì ngoài vốn từ chửi bới.", "Bea bongkar, bea tambat, dan sekarang perbaikan pelabuhan. Yang membaik cuma kosakata makianku.", "ค่าขึ้นฝั่ง ค่าท่าจอด แล้วตอนนี้ค่าปรับปรุงท่าเรือ ที่ปรับปรุงขึ้นมีแต่คลังคำสบถของผม", "Boşaltma vergisi, rıhtım vergisi, şimdi de liman iyileştirmesi. Ben yalnızca küfür dağarcığımı iyileştirdim.", "Derechos de desembarco, de atraque, y ahora mejora del puerto. Lo único que he mejorado es mi vocabulario.", "Taxa de desembarque, taxa de atracação, e agora melhoria do porto. Só melhorei meu vocabulário.", "Выгрузной сбор, причальный сбор, а теперь ещё благоустройство гавани. Благоустроил я только свой словарный запас.", "Вивантажувальний збір, причальний збір, а тепер ще й упорядкування гавані. Упорядкував я лише свій словниковий запас."],
  "Don't go out on Wrack Point at night. Not for any reason. Not for any reason you'd want to tell the watch.": ["夜はレック岬に出るな。どんな理由があってもだ。夜警に話したくなるような理由ならなおさらな。", "밤에는 렉 곶에 나가지 마. 무슨 이유로든. 경비대에 말하고 싶어질 이유라면 더더욱.", "夜里别去残骸岬。不管什么理由。尤其是那种你会想告诉巡夜人的理由。", "夜裡別去殘骸岬。不管什麼理由。尤其是那種你會想告訴巡夜人的理由。", "Đừng ra mũi Wrack vào ban đêm. Vì bất cứ lý do gì. Nhất là lý do mà anh muốn kể với lính gác.", "Jangan ke Tanjung Wrack malam-malam. Dengan alasan apa pun. Terutama alasan yang ingin kau ceritakan ke penjaga.", "อย่าออกไปแหลมแร็กตอนกลางคืน ไม่ว่าด้วยเหตุผลอะไร ไม่ว่าเหตุผลไหนที่คุณอยากบอกยาม", "Gece Wrack Burnu'na çıkma. Hiçbir sebeple. Nöbetçilere anlatmak isteyeceğin hiçbir sebeple.", "No salgas a la Punta Wrack de noche. Por ningún motivo. Por ningún motivo que quisieras contarle a la guardia.", "Não vá à Ponta Wrack de noite. Por motivo nenhum. Por nenhum motivo que você queira contar à guarda.", "Не ходи ночью на мыс Рэк. Ни по какой причине. Ни по какой, о которой захотелось бы рассказать страже.", "Не ходи вночі на мис Рек. З жодної причини. З жодної, про яку захотілося б розповісти варті."],
  "The Collector pays us. The fishers feed us. You can see the difficulty.": ["給金をくれるのは徴税官、飯を食わせてくれるのは漁師。難しいところだろう。", "돈은 징수관이 주고, 밥은 어부들이 먹여 주지. 곤란한 거 알겠지.", "付我们钱的是税务官,管我们饭的是渔民。你明白难处在哪儿了吧。", "付我們錢的是稅務官,管我們飯的是漁民。你明白難處在哪兒了吧。", "Quan thu thuế trả lương cho chúng tôi. Dân chài nuôi chúng tôi. Anh thấy cái khó rồi đấy.", "Pemungut yang menggaji kami. Para nelayan yang memberi kami makan. Kau lihat kesulitannya.", "เจ้าพนักงานเก็บภาษีจ่ายเงินเรา ชาวประมงเลี้ยงข้าวเรา คุณก็เห็นความลำบาก", "Bize Tahsildar para verir. Balıkçılar bizi doyurur. Zorluğu görüyorsun.", "El Recaudador nos paga. Los pescadores nos dan de comer. Ya ves la dificultad.", "O Coletor nos paga. Os pescadores nos alimentam. Você vê a dificuldade.", "Платит нам сборщик. Кормят нас рыбаки. Видишь, в чём загвоздка.", "Платить нам збирач. Годують нас рибалки. Бачиш, у чому заковика."],
  "Quiet tonight. Too quiet. The Light's lit, at least. So far.": ["今夜は静かだ。静かすぎる。少なくとも灯台はついてる。今のところは。", "오늘 밤은 조용하군. 너무 조용해. 적어도 등대는 켜져 있어. 아직까지는.", "今晚很静。太静了。至少灯塔亮着。到目前为止。", "今晚很靜。太靜了。至少燈塔亮著。到目前為止。", "Đêm nay yên tĩnh. Quá yên tĩnh. Ít ra Đèn vẫn sáng. Cho tới giờ.", "Sepi malam ini. Terlalu sepi. Setidaknya Mercusuar menyala. Sejauh ini.", "คืนนี้เงียบ เงียบเกินไป อย่างน้อยประภาคารก็สว่าง จนถึงตอนนี้", "Bu gece sessiz. Fazla sessiz. Fener yanıyor, en azından. Şimdilik.", "Tranquilo esta noche. Demasiado. El faro está encendido, al menos. Por ahora.", "Quieto esta noite. Quieto demais. O farol está aceso, pelo menos. Por enquanto.", "Тихо сегодня. Слишком тихо. Маяк хотя бы горит. Пока что.", "Тихо сьогодні. Аж надто тихо. Маяк принаймні горить. Поки що."],
  "Saltmarrow's further along the coast. They say they're the real harbour. They also say their tithe stops storms.": ["ソルトマロウは海岸のもっと先だ。あそこは自分たちこそ本物の港だと言う。十分の一税で嵐が止まるとも言うけどね。", "솔트매로는 해안을 따라 더 가면 있어. 거기 사람들은 자기네가 진짜 항구래. 십일조로 폭풍을 막는다고도 하고.", "盐髓港在海岸更远处。他们说自己才是真正的港口。他们还说他们的什一税能挡住风暴。", "鹽髓港在海岸更遠處。他們說自己才是真正的港口。他們還說他們的什一稅能擋住風暴。", "Saltmarrow ở xa hơn dọc bờ biển. Họ bảo họ mới là cảng thật. Họ cũng bảo phần thuế dâng biển của họ ngăn được bão.", "Saltmarrow lebih jauh di sepanjang pantai. Mereka bilang merekalah pelabuhan sejati. Mereka juga bilang persepuluhan mereka menghentikan badai.", "ซอลต์แมร์โรว์อยู่ไกลออกไปตามชายฝั่ง พวกเขาว่าพวกเขาคือท่าเรือตัวจริง พวกเขายังว่าส่วนสิบของพวกเขาหยุดพายุได้ด้วย", "Saltmarrow kıyı boyunca daha ileride. Asıl limanın kendileri olduğunu söylerler. Öşürlerinin fırtınaları durdurduğunu da söylerler.", "Saltmarrow está más allá por la costa. Dicen que ellos son el puerto de verdad. También dicen que su diezmo detiene las tormentas.", "Saltmarrow fica mais adiante na costa. Dizem que eles são o porto de verdade. Também dizem que o dízimo deles para as tempestades.", "Солтмэрроу дальше по берегу. Там говорят, что настоящая гавань — они. Ещё говорят, что их десятина останавливает бури.", "Солтмерроу далі по берегу. Там кажуть, що справжня гавань — вони. Ще кажуть, що їхня десятина зупиняє бурі."],
  "The packet goes everywhere now. My cousin went to the Isles and came back with a hat. Just a hat. Says it was worth it.": ["今じゃ定期船はどこへでも行く。いとこは島々へ行って帽子を持って帰ってきた。帽子だけさ。それだけの価値はあったって言うんだ。", "이제 정기선이 어디든 가. 내 사촌은 섬들에 갔다가 모자 하나 들고 돌아왔어. 그냥 모자. 그럴 만한 가치가 있었대.", "现在邮船哪儿都去。我表亲去了群岛,带回来一顶帽子。就一顶帽子。他说值了。", "現在郵船哪兒都去。我表親去了群島,帶回來一頂帽子。就一頂帽子。他說值了。", "Giờ thuyền chở khách đi khắp nơi. Anh họ tôi tới Quần đảo rồi về với một cái mũ. Chỉ một cái mũ. Bảo là đáng.", "Kapal paket sekarang ke mana-mana. Sepupuku pergi ke Kepulauan dan pulang membawa topi. Cuma topi. Katanya sepadan.", "ตอนนี้เรือโดยสารไปทุกที่ ลูกพี่ลูกน้องฉันไปหมู่เกาะแล้วกลับมาพร้อมหมวกใบหนึ่ง แค่หมวก บอกว่าคุ้ม", "Posta teknesi artık her yere gidiyor. Kuzenim Adalar'a gidip bir şapkayla döndü. Sadece bir şapka. Değdi diyor.", "El paquebote va ahora a todas partes. Mi primo fue a las Islas y volvió con un sombrero. Solo un sombrero. Dice que valió la pena.", "O paquete vai a todo lugar agora. Meu primo foi às Ilhas e voltou com um chapéu. Só um chapéu. Diz que valeu a pena.", "Пакетбот теперь ходит везде. Мой двоюродный брат съездил на Острова и вернулся со шляпой. Просто шляпой. Говорит, оно того стоило.", "Пакетбот тепер ходить усюди. Мій двоюрідний брат з'їздив на Острови й повернувся з капелюхом. Просто капелюхом. Каже, воно було того варте."],
  "Hollyhock's just east. Their gardens, our fish. We get on, mostly. Mostly about the fish.": ["ホリホックはすぐ東だ。あっちは庭、こっちは魚。だいたい仲良くやってる。だいたいは魚のことでね。", "할리혹은 바로 동쪽이야. 그쪽은 정원, 우리는 생선. 대체로 잘 지내. 대체로 생선 얘기로.", "蜀葵村就在东边。他们种园子,我们打鱼。大体上处得不错。大体上是为了鱼。", "蜀葵村就在東邊。他們種園子,我們打魚。大體上處得不錯。大體上是為了魚。", "Hollyhock ngay phía đông. Vườn của họ, cá của chúng tôi. Phần lớn thì hòa thuận. Phần lớn là chuyện cá.", "Hollyhock tepat di timur. Kebun mereka, ikan kami. Kami akur, kebanyakan. Kebanyakan soal ikan.", "ฮอลลีฮ็อกอยู่ทางตะวันออกนี่เอง สวนของเขา ปลาของเรา ส่วนใหญ่ก็เข้ากันได้ ส่วนใหญ่เรื่องปลา", "Hollyhock hemen doğuda. Onların bahçeleri, bizim balıklarımız. Genelde iyi geçiniriz. Genelde balık yüzünden.", "Hollyhock está justo al este. Sus huertos, nuestro pescado. Nos llevamos bien, casi siempre. Casi siempre por el pescado.", "Hollyhock fica logo a leste. Os jardins deles, o nosso peixe. A gente se dá bem, quase sempre. Quase sempre por causa do peixe.", "Холлихок сразу к востоку. Их сады, наша рыба. Ладим, в основном. В основном из-за рыбы.", "Голлігок одразу на схід. Їхні сади, наша риба. Ладнаємо, здебільшого. Здебільшого через рибу."],
  "Every pound of salt that leaves Saltreach is weighed, sealed and written in the Ledger. The salt duty is King Pell's: the one office Her Radiance gave him to keep. We keep it exactly.": ["ソルトリーチを出る塩は一ポンド残らず量られ、封をされ、台帳に記される。塩税はペル王のもの。光輝なる女王陛下が王にお任せになった唯一の職務だ。我々はそれを厳密に守る。", "솔트리치를 떠나는 소금은 한 파운드도 빠짐없이 무게를 달고, 봉인하고, 장부에 기록하오. 소금세는 펠 왕의 것이오. 빛나는 여왕 폐하께서 왕께 맡기신 단 하나의 직무지. 우리는 그것을 정확히 지키오.", "离开盐滩港的每一磅盐都要过秤、封印、记入册子。盐税归佩尔国王:那是光辉陛下交给他掌管的唯一职务。我们一丝不苟地守着它。", "離開鹽灘港的每一磅鹽都要過秤、封印、記入冊子。鹽稅歸佩爾國王:那是光輝陛下交給他掌管的唯一職務。我們一絲不苟地守著它。", "Mỗi cân muối rời Saltreach đều được cân, niêm phong và ghi vào Sổ. Thuế muối là của Vua Pell: chức phận duy nhất Đức Rạng Ngời giao cho ngài giữ. Chúng tôi giữ nó chính xác.", "Setiap pon garam yang meninggalkan Saltreach ditimbang, disegel, dan dicatat di Buku. Bea garam milik Raja Pell: satu-satunya jabatan yang Yang Bercahaya berikan untuk ia pegang. Kami menjaganya dengan tepat.", "เกลือทุกปอนด์ที่ออกจากซอลต์รีชถูกชั่ง ผนึก และจดลงสมุด ภาษีเกลือเป็นของกษัตริย์เพลล์ หน้าที่เดียวที่พระราชินีผู้เรืองรองทรงมอบให้พระองค์ดูแล เราดูแลมันอย่างเที่ยงตรง", "Saltreach'ten çıkan her libre tuz tartılır, mühürlenir ve Defter'e yazılır. Tuz vergisi Kral Pell'indir: Işıltılı Majesteleri'nin ona bıraktığı tek makam. Onu tam olarak koruruz.", "Cada libra de sal que sale de Saltreach se pesa, se sella y se anota en el Libro. El impuesto de la sal es del rey Pell: el único oficio que Su Radiancia le dio a guardar. Lo guardamos con exactitud.", "Cada libra de sal que deixa Saltreach é pesada, selada e escrita no Livro. O imposto do sal é do rei Pell: o único ofício que Sua Radiância lhe deu para guardar. Nós o guardamos com exatidão.", "Каждый фунт соли, покидающий Солтрич, взвешен, опечатан и записан в Книгу. Соляной сбор — дело короля Пелла: единственная должность, которую Её Сияние оставила ему. Мы ведём его в точности.", "Кожен фунт солі, що покидає Солтріч, зважено, опечатано й записано до Книги. Соляний збір — справа короля Пелла: єдина посада, яку Її Сяйво залишила йому. Ми ведемо його достеменно."],
  "A panner says the Salt-House cheats. I show him the Ledger. The Ledger is never wrong; it's written.": ["塩田の者が、塩館はごまかしていると言う。私は台帳を見せる。台帳は決して間違わない。書かれているのだから。", "염부가 소금관이 속인다고 하오. 나는 장부를 보여 주지. 장부는 절대 틀리지 않소. 적혀 있으니까.", "有盐工说盐务所耍诈。我就给他看册子。册子从不出错;它是写下来的。", "有鹽工說鹽務所耍詐。我就給他看冊子。冊子從不出錯;它是寫下來的。", "Một người làm muối bảo Nhà Muối gian lận. Tôi cho anh ta xem Sổ. Sổ không bao giờ sai; nó đã được viết.", "Seorang petani garam bilang Rumah Garam curang. Kutunjukkan Buku padanya. Buku tak pernah salah; ia tertulis.", "ชาวนาเกลือคนหนึ่งว่าโรงเกลือโกง ผมให้เขาดูสมุด สมุดไม่เคยผิด มันถูกเขียนไว้แล้ว", "Bir tuzcu Tuz Evi'nin hile yaptığını söylüyor. Ona Defter'i gösteririm. Defter asla yanılmaz; yazılmıştır.", "Un salinero dice que la Casa de la Sal hace trampa. Le enseño el Libro. El Libro nunca se equivoca; está escrito.", "Um salineiro diz que a Casa do Sal trapaceia. Eu lhe mostro o Livro. O Livro nunca erra; está escrito.", "Солевар говорит, что Соляной дом жульничает. Я показываю ему Книгу. Книга никогда не ошибается: она записана.", "Солевар каже, що Соляний дім шахрує. Я показую йому Книгу. Книга ніколи не помиляється: вона записана."],
  "The King reads every column of the Ledger of Salt himself. He has ink on his fingers from it. He is very kind about it, which is worse.": ["王は塩の台帳のすべての欄をご自身でお読みになる。そのせいで指にインクがついておられる。それについて大変お優しい。そのほうがかえってこたえる。", "왕께서는 소금 장부의 모든 칸을 직접 읽으시오. 그 때문에 손가락에 잉크가 묻어 계시지. 그 일에 아주 친절하시오. 그게 더 무섭소.", "国王亲自看《盐册》的每一栏,手指都被墨染了。他对此非常和善,这反而更糟。", "國王親自看《鹽冊》的每一欄,手指都被墨染了。他對此非常和善,這反而更糟。", "Nhà Vua tự mình đọc mọi cột của Sổ Muối. Ngón tay ngài dính mực vì nó. Ngài rất tử tế về chuyện ấy, thế còn tệ hơn.", "Raja membaca sendiri setiap kolom Buku Garam. Jarinya bernoda tinta karenanya. Ia sangat baik soal itu, dan itu lebih buruk.", "กษัตริย์ทรงอ่านทุกคอลัมน์ของสมุดบัญชีเกลือด้วยพระองค์เอง นิ้วของพระองค์เปื้อนหมึกจากมัน พระองค์ทรงใจดีมากในเรื่องนี้ ซึ่งยิ่งแย่", "Kral Tuz Defteri'nin her sütununu kendisi okur. Parmaklarında ondan mürekkep var. Bu konuda çok naziktir, ki bu daha kötü.", "El Rey lee él mismo cada columna del Libro de la Sal. Tiene tinta en los dedos por eso. Es muy amable al respecto, que es peor.", "O Rei lê pessoalmente cada coluna do Livro do Sal. Tem tinta nos dedos por causa disso. É muito gentil a respeito, o que é pior.", "Король сам читает каждую графу Книги соли. У него от неё чернила на пальцах. Он очень добр на этот счёт, что хуже всего.", "Король сам читає кожну графу Книги солі. У нього від неї чорнило на пальцях. Він дуже добрий із цього приводу, що найгірше."],
  "Fifty years I've raked these pans. The salt's the same. The sea's the same. The duty's grown every year, and nobody can tell me why.": ["五十年、この塩田をかいてきた。塩は同じ。海も同じ。税だけが毎年増えて、誰もその理由を言えないんだ。", "오십 년을 이 염전을 긁어 왔어. 소금도 같고, 바다도 같아. 세금만 해마다 늘었는데, 아무도 이유를 말 못 해.", "这些盐田我耙了五十年。盐还是那盐,海还是那海。税年年涨,谁也说不出为什么。", "這些鹽田我耙了五十年。鹽還是那鹽,海還是那海。稅年年漲,誰也說不出為什麼。", "Năm mươi năm tôi cào những ruộng muối này. Muối vẫn thế. Biển vẫn thế. Thuế năm nào cũng tăng, và chẳng ai nói được vì sao.", "Lima puluh tahun aku menggaru petak-petak ini. Garamnya sama. Lautnya sama. Beanya naik tiap tahun, dan tak ada yang bisa bilang kenapa.", "ห้าสิบปีที่ฉันคราดนาเกลือพวกนี้ เกลือก็เหมือนเดิม ทะเลก็เหมือนเดิม ภาษีขึ้นทุกปี และไม่มีใครบอกได้ว่าทำไม", "Elli yıldır bu tuzlaları tırmıklıyorum. Tuz aynı. Deniz aynı. Vergi her yıl arttı ve kimse bana nedenini söyleyemiyor.", "Cincuenta años llevo rastrillando estas salinas. La sal es la misma. El mar es el mismo. El impuesto ha crecido cada año, y nadie sabe decirme por qué.", "Cinquenta anos rodando estas salinas. O sal é o mesmo. O mar é o mesmo. O imposto cresceu todo ano, e ninguém sabe me dizer por quê.", "Пятьдесят лет я гребу эти бассейны. Соль та же. Море то же. Сбор растёт каждый год, и никто не может сказать мне почему.", "П'ятдесят років я гребу ці басейни. Сіль та сама. Море те саме. Збір росте щороку, і ніхто не може сказати мені чому."],
  "The Assessor writes everything down. So we've learnt what not to say. That's what the Ledger teaches, if you let it.": ["査定官はなんでも書き留める。だから私たちは何を言わずにおくかを覚えた。台帳が教えてくれるのはそれさ、教わるつもりがあればね。", "감정관은 뭐든 적어. 그래서 우리는 무엇을 말하지 말아야 할지 배웠지. 장부가 가르쳐 주는 건 그거야, 배울 생각만 있다면.", "估税官什么都记下来。所以我们学会了什么话不能说。册子教的就是这个,只要你肯学。", "估稅官什麼都記下來。所以我們學會了什麼話不能說。冊子教的就是這個,只要你肯學。", "Quan định giá ghi lại mọi thứ. Nên chúng tôi đã học được điều gì không nên nói. Đó là bài học Sổ dạy, nếu anh để nó dạy.", "Penaksir mencatat segalanya. Jadi kami belajar apa yang tak boleh dikatakan. Itulah yang diajarkan Buku, kalau kau membiarkannya.", "เจ้าพนักงานประเมินจดทุกอย่าง เราจึงเรียนรู้ว่าอะไรไม่ควรพูด นั่นคือสิ่งที่สมุดสอน ถ้าคุณยอมให้มันสอน", "Değerleyici her şeyi yazar. Biz de neyi söylememek gerektiğini öğrendik. Defter'in öğrettiği budur, izin verirsen.", "El Tasador lo apunta todo. Así que hemos aprendido qué no decir. Eso es lo que enseña el Libro, si le dejas.", "O Avaliador anota tudo. Então aprendemos o que não dizer. É isso que o Livro ensina, se você deixar.", "Оценщик всё записывает. Вот мы и научились, о чём молчать. Этому Книга и учит, если позволить.", "Оцінювач усе записує. От ми й навчилися, про що мовчати. Цього Книга й навчає, якщо дозволити."],
  "The pans' weights are ours: we weigh before the Salt-House does, so we know what we're owed. Usually we're owed more than we get.": ["塩田の分銅は俺たちのものだ。塩館より先に量っておけば、いくらもらえるはずか分かる。たいていは、もらえるはずより少ないがね。", "염전 저울추는 우리 거요. 소금관보다 먼저 달아 두면 우리 몫이 얼마인지 알지. 대개 받을 몫보다 덜 받지만.", "盐田的砝码是我们自己的:我们抢在盐务所之前称,就知道该得多少。通常该得的比拿到的多。", "鹽田的砝碼是我們自己的:我們搶在鹽務所之前稱,就知道該得多少。通常該得的比拿到的多。", "Quả cân của ruộng muối là của chúng tôi: chúng tôi cân trước Nhà Muối, để biết mình đáng được bao nhiêu. Thường thì đáng được nhiều hơn số nhận.", "Anak timbangan petak garam milik kami: kami menimbang sebelum Rumah Garam, jadi kami tahu hak kami. Biasanya hak kami lebih banyak dari yang kami dapat.", "ลูกตุ้มของนาเกลือเป็นของเรา เราชั่งก่อนโรงเกลือ จะได้รู้ว่าเราควรได้เท่าไร ปกติเราควรได้มากกว่าที่ได้", "Tuzlaların ağırlıkları bizimdir: Tuz Evi'nden önce tartarız ki ne kadar alacaklı olduğumuzu bilelim. Genelde aldığımızdan fazlasına alacaklıyız.", "Las pesas de las salinas son nuestras: pesamos antes que la Casa de la Sal, así sabemos lo que se nos debe. Por lo general se nos debe más de lo que recibimos.", "Os pesos das salinas são nossos: pesamos antes da Casa do Sal, assim sabemos o que nos é devido. Geralmente nos devem mais do que recebemos.", "Гири солеварен наши: мы взвешиваем раньше Соляного дома, чтобы знать, что нам причитается. Обычно причитается больше, чем мы получаем.", "Гирі соляних басейнів наші: ми зважуємо раніше за Соляний дім, щоб знати, що нам належить. Зазвичай належить більше, ніж ми отримуємо."],
  "Brine in, sun on, rake it, sack it, weigh it, seal it. The sun does most of the work. The Salt-House takes most of the salt.": ["塩水を入れ、日に当て、かき、袋に詰め、量り、封をする。仕事のほとんどはお天道様がやる。塩のほとんどは塩館が持っていく。", "소금물 넣고, 볕 쬐고, 긁고, 자루에 담고, 달고, 봉하고. 일은 대부분 해가 하지. 소금은 대부분 소금관이 가져가고.", "引卤、晒日、耙盐、装袋、过秤、封口。活儿大多是太阳干的。盐大多被盐务所拿走。", "引滷、曬日、耙鹽、裝袋、過秤、封口。活兒大多是太陽幹的。鹽大多被鹽務所拿走。", "Cho nước muối vào, phơi nắng, cào, đóng bao, cân, niêm phong. Mặt trời làm phần lớn công việc. Nhà Muối lấy phần lớn muối.", "Air garam masuk, matahari bersinar, garu, masukkan karung, timbang, segel. Matahari yang paling banyak bekerja. Rumah Garam yang paling banyak mengambil garam.", "ปล่อยน้ำเค็มเข้า ตากแดด คราด ใส่กระสอบ ชั่ง ผนึก ดวงอาทิตย์ทำงานส่วนใหญ่ โรงเกลือเอาเกลือไปส่วนใหญ่", "Tuzlu su gir, güneş vur, tırmıkla, çuvalla, tart, mühürle. İşin çoğunu güneş yapar. Tuzun çoğunu Tuz Evi alır.", "Entra la salmuera, sale el sol, rastrilla, ensaca, pesa, sella. El sol hace casi todo el trabajo. La Casa de la Sal se lleva casi toda la sal.", "Entra a salmoura, vem o sol, rode, ensaque, pese, sele. O sol faz quase todo o trabalho. A Casa do Sal leva quase todo o sal.", "Рассол залить, солнце светит, сгрести, в мешок, взвесить, опечатать. Почти всю работу делает солнце. Почти всю соль забирает Соляной дом.", "Розсіл залити, сонце світить, згорнути, у мішок, зважити, опечатати. Майже всю роботу робить сонце. Майже всю сіль забирає Соляний дім."],
  "One measure of small beer, as the Law asks. Herring's as much as you like; the Law hasn't said anything about herring yet.": ["弱い麦酒は掟どおり一杯だけ。ニシンは好きなだけどうぞ。掟はまだニシンのことは何も言ってないからね。", "약한 맥주는 율법대로 한 잔. 청어는 원하는 만큼요. 율법은 아직 청어에 대해 아무 말도 안 했거든요.", "淡啤酒按律法只给一份。鲱鱼你想吃多少吃多少;律法还没提过鲱鱼。", "淡啤酒按律法只給一份。鯡魚你想吃多少吃多少;律法還沒提過鯡魚。", "Một chén bia nhẹ, như Luật đòi hỏi. Cá trích thì bao nhiêu tùy thích; Luật chưa nói gì về cá trích.", "Satu takar bir ringan, sesuai Hukum. Haring sebanyak yang kau mau; Hukum belum bilang apa-apa soal haring.", "เบียร์อ่อนหนึ่งถ้วย ตามที่กฎกำหนด ปลาแฮร์ริ่งเอาเท่าไรก็ได้ กฎยังไม่ได้พูดถึงปลาแฮร์ริ่งเลย", "Bir ölçü hafif bira, Yasa'nın istediği gibi. Ringa istediğin kadar; Yasa ringa hakkında henüz bir şey demedi.", "Una medida de cerveza floja, como pide la Ley. Arenque, todo el que quieras; la Ley aún no ha dicho nada del arenque.", "Uma medida de cerveja fraca, como pede a Lei. Arenque, quanto quiser; a Lei ainda não disse nada sobre arenque.", "Одна мера слабого пива, как велит Закон. Сельди — сколько хочешь; о сельди Закон пока ничего не сказал.", "Одна міра слабкого пива, як велить Закон. Оселедців — скільки хочеш; про оселедці Закон поки нічого не сказав."],
  "The panners drink at the back, the Salt-House men at the front. Nobody drinks much. The Ledger's open at both ends.": ["塩田の者は奥で、塩館の連中は手前で飲む。誰もたいして飲まない。台帳は両方の端で開いているからね。", "염부들은 안쪽에서, 소금관 사람들은 앞쪽에서 마셔요. 아무도 많이 안 마시죠. 장부가 양쪽 끝에 다 펼쳐져 있으니까.", "盐工坐在里头喝,盐务所的人坐在前头喝。谁都喝不多。册子两头都摊开着。", "鹽工坐在裡頭喝,鹽務所的人坐在前頭喝。誰都喝不多。冊子兩頭都攤開著。", "Người làm muối uống ở phía sau, người Nhà Muối ở phía trước. Chẳng ai uống nhiều. Sổ mở ở cả hai đầu.", "Para petani garam minum di belakang, orang Rumah Garam di depan. Tak ada yang minum banyak. Buku terbuka di kedua ujung.", "ชาวนาเกลือดื่มอยู่ด้านหลัง คนของโรงเกลืออยู่ด้านหน้า ไม่มีใครดื่มมาก สมุดเปิดอยู่ทั้งสองด้าน", "Tuzcular arkada içer, Tuz Evi'nin adamları önde. Kimse çok içmez. Defter iki uçta da açık.", "Los salineros beben al fondo, los de la Casa de la Sal delante. Nadie bebe mucho. El Libro está abierto por los dos extremos.", "Os salineiros bebem nos fundos, os homens da Casa do Sal na frente. Ninguém bebe muito. O Livro está aberto nas duas pontas.", "Солевары пьют в глубине, люди Соляного дома — у входа. Никто не пьёт много. Книга открыта с обоих концов.", "Солевари п'ють углибині, люди Соляного дому — біля входу. Ніхто не п'є багато. Книга відкрита з обох кінців."],
  "Bread of the one kind, at the one price. Salt herring, which isn't in the Law, so I can charge what I like. I don't. Somebody might write it down.": ["一種類一値段のパン。塩ニシンは掟にないから好きな値をつけていい。でもつけない。誰かが書き留めるかもしれないからな。", "한 종류 한 가격의 빵. 소금 청어는 율법에 없으니 내 맘대로 값을 매겨도 되지. 안 그러오. 누가 적을지도 모르니까.", "只有一种、只卖一个价的面包。腌鲱鱼律法里没写,我想要多少就要多少。我不这么干。说不定会有人记下来。", "只有一種、只賣一個價的麵包。醃鯡魚律法裡沒寫,我想要多少就要多少。我不這麼幹。說不定會有人記下來。", "Bánh mì một loại, một giá. Cá trích muối không có trong Luật, nên tôi muốn bán bao nhiêu cũng được. Tôi không làm thế. Biết đâu có người ghi lại.", "Roti satu jenis, satu harga. Haring asin tak ada di Hukum, jadi aku boleh pasang harga sesukaku. Tidak kulakukan. Bisa saja ada yang mencatatnya.", "ขนมปังชนิดเดียว ราคาเดียว ปลาแฮร์ริ่งเค็มไม่อยู่ในกฎ ผมจะคิดราคาเท่าไรก็ได้ แต่ผมไม่ทำ เผื่อมีใครจดไว้", "Tek çeşit ekmek, tek fiyata. Tuzlu ringa Yasa'da yok, yani istediğimi isteyebilirim. İstemem. Biri yazabilir.", "Pan de una sola clase, a un solo precio. Arenque salado, que no está en la Ley, así que puedo cobrar lo que quiera. No lo hago. Alguien podría apuntarlo.", "Pão de um só tipo, a um só preço. Arenque salgado, que não está na Lei, então posso cobrar o que quiser. Não cobro. Alguém pode anotar.", "Хлеб одного сорта, по одной цене. Солёная сельдь в Законе не значится, так что могу просить сколько угодно. Не прошу. Вдруг кто-нибудь запишет.", "Хліб одного сорту, за однією ціною. Солоних оселедців у Законі немає, тож можу правити скільки завгодно. Не правлю. Раптом хтось запише."],
  "Salt-white for the pans, violet for the Salt-House. The Sumptuary Office lets a port have one violet, one finger wide. I make the most of the finger.": ["塩田には塩白、塩館には紫。奢侈取締局が港に許すのは指一本幅の紫ひとつだけ。その指一本を精一杯活かすのさ。", "염전엔 소금 같은 흰색, 소금관엔 보라색. 사치단속청은 항구에 손가락 하나 너비의 보라 하나만 허락해요. 난 그 손가락 하나를 최대한 살리죠.", "盐田穿盐白,盐务所穿紫。禁奢署只许港口用一种紫,一指宽。我把那一指用到了极致。", "鹽田穿鹽白,鹽務所穿紫。禁奢署只許港口用一種紫,一指寬。我把那一指用到了極致。", "Trắng muối cho ruộng muối, tím cho Nhà Muối. Sở Kiểm soát Xa xỉ cho một bến cảng một màu tím, rộng một ngón tay. Tôi tận dụng hết ngón tay ấy.", "Putih garam untuk petak, ungu untuk Rumah Garam. Kantor Kemewahan mengizinkan pelabuhan satu ungu, selebar satu jari. Kumanfaatkan jari itu sebaik-baiknya.", "ขาวเกลือสำหรับนาเกลือ ม่วงสำหรับโรงเกลือ สำนักควบคุมความฟุ่มเฟือยอนุญาตให้เมืองท่ามีสีม่วงหนึ่งสี กว้างหนึ่งนิ้ว ฉันใช้นิ้วนั้นให้คุ้มที่สุด", "Tuzlalar için tuz beyazı, Tuz Evi için mor. İsraf Dairesi bir limana bir mor izin verir, bir parmak eninde. O parmağı sonuna kadar kullanırım.", "Blanco sal para las salinas, violeta para la Casa de la Sal. La Oficina Suntuaria deja a un puerto un violeta, de un dedo de ancho. Yo le saco todo el partido al dedo.", "Branco-sal para as salinas, violeta para a Casa do Sal. O Ofício Suntuário permite a um porto um violeta, da largura de um dedo. Eu aproveito o dedo ao máximo.", "Белый, как соль, — для бассейнов, фиолетовый — для Соляного дома. Управление роскоши дозволяет порту один фиолетовый, в палец шириной. Я выжимаю из этого пальца всё.", "Білий, як сіль, — для басейнів, фіолетовий — для Соляного дому. Управління розкоші дозволяє портові один фіолетовий, завширшки в палець. Я вичавлюю з цього пальця все."],
  "Rake it into ridges, let the wind take the wet. The glare'll blind you by noon if you don't keep the coif low.": ["畝にかき寄せて、湿り気は風に持っていかせる。頭巾を深くかぶってないと、昼には照り返しで目がやられるよ。", "이랑지게 긁어모으고, 습기는 바람이 가져가게 둬. 두건을 깊이 쓰지 않으면 한낮엔 반사광에 눈이 멀 거야.", "耙成垄,让风把湿气带走。头巾不压低点,到中午反光就能把你晃瞎。", "耙成壟,讓風把濕氣帶走。頭巾不壓低點,到中午反光就能把你晃瞎。", "Cào thành luống, để gió lấy hơi ẩm đi. Không kéo khăn trùm thấp thì tới trưa ánh chói làm mù mắt.", "Garu jadi pematang, biarkan angin mengambil basahnya. Silaunya akan membutakanmu menjelang siang kalau tudungmu tak kau turunkan.", "คราดให้เป็นสัน ปล่อยให้ลมพาความชื้นไป ถ้าไม่ดึงหมวกคลุมต่ำ แสงจ้าจะทำให้ตาบอดตอนเที่ยง", "Sırtlar halinde tırmıkla, ıslaklığı rüzgâr alsın. Başlığı aşağıda tutmazsan öğlene parıltı seni kör eder.", "Rastríllala en caballones y deja que el viento se lleve la humedad. Si no llevas la cofia baja, el resplandor te ciega a mediodía.", "Rode em leiras e deixe o vento levar a umidade. Se não mantiver a touca baixa, o brilho te cega ao meio-dia.", "Сгребай в гряды, пусть ветер заберёт сырость. Если не надвинешь чепец пониже, к полудню блеск ослепит.", "Згрібай у гряди, хай вітер забере вогкість. Якщо не насунеш очіпок нижче, до полудня блиск осліпить."],
  "We pay the King's salt on every sack. Then the King's salt is weighed again in the capital. It never weighs the same twice. Funny, that.": ["袋ごとに王の塩税を払う。そのあと都でまた王の塩が量られる。二度同じ重さになったためしがない。おかしな話だろ。", "자루마다 왕의 소금세를 내지. 그러고 나서 수도에서 왕의 소금을 또 달아. 두 번 같은 무게가 나온 적이 없어. 희한하지.", "每一袋都要交王家盐税。然后王家的盐到了王都还要再称一遍。从来没有两次称得一样。有意思吧。", "每一袋都要交王家鹽稅。然後王家的鹽到了王都還要再稱一遍。從來沒有兩次稱得一樣。有意思吧。", "Chúng tôi nộp muối của Nhà Vua trên mọi bao. Rồi muối của Nhà Vua lại được cân lần nữa ở kinh đô. Chẳng bao giờ nặng như nhau hai lần. Lạ thật.", "Kami bayar garam Raja untuk setiap karung. Lalu garam Raja ditimbang lagi di ibu kota. Tak pernah sama beratnya dua kali. Lucu, ya.", "เราจ่ายภาษีเกลือของกษัตริย์ทุกกระสอบ แล้วเกลือของกษัตริย์ก็ถูกชั่งอีกครั้งที่เมืองหลวง ไม่เคยหนักเท่ากันสองครั้ง ตลกดีนะ", "Her çuval için Kral'ın tuzunu öderiz. Sonra Kral'ın tuzu başkentte yeniden tartılır. Hiç iki kez aynı çekmez. Tuhaf, değil mi.", "Pagamos la sal del Rey por cada saco. Luego la sal del Rey se vuelve a pesar en la capital. Nunca pesa igual dos veces. Curioso, eso.", "Pagamos o sal do Rei em cada saco. Depois o sal do Rei é pesado de novo na capital. Nunca pesa igual duas vezes. Curioso, isso.", "Мы платим королевскую соль с каждого мешка. Потом королевскую соль ещё раз взвешивают в столице. Ни разу не весит одинаково. Забавно.", "Ми сплачуємо королівську сіль із кожного мішка. Потім королівську сіль ще раз зважують у столиці. Жодного разу не важить однаково. Кумедно."],
  "Every sack sealed, every seal checked, every boat written down. That's Saltreach.": ["袋はみな封印され、封印はみな確かめられ、船はみな書き留められる。それがソルトリーチだ。", "모든 자루는 봉인되고, 모든 봉인은 확인되고, 모든 배는 기록된다. 그게 솔트리치다.", "每袋封印,每个封印都查,每条船都记下。这就是盐滩港。", "每袋封印,每個封印都查,每條船都記下。這就是鹽灘港。", "Mọi bao được niêm phong, mọi niêm phong được kiểm, mọi thuyền được ghi lại. Đó là Saltreach.", "Setiap karung disegel, setiap segel diperiksa, setiap perahu dicatat. Itulah Saltreach.", "ทุกกระสอบถูกผนึก ทุกผนึกถูกตรวจ ทุกเรือถูกจด นั่นคือซอลต์รีช", "Her çuval mühürlü, her mühür denetli, her tekne kayıtlı. İşte Saltreach.", "Cada saco sellado, cada sello revisado, cada barca anotada. Eso es Saltreach.", "Cada saco selado, cada selo conferido, cada barco anotado. Isso é Saltreach.", "Каждый мешок опечатан, каждая печать проверена, каждая лодка записана. Вот он, Солтрич.", "Кожен мішок опечатано, кожну печатку перевірено, кожен човен записано. Ось він, Солтріч."],
  "Move along, citizen. Or stay. Either way, you're in the Ledger.": ["さあ行け、市民。それとも残るか。どちらにせよ、お前は台帳に載っている。", "가시오, 시민. 아니면 남든가. 어느 쪽이든 당신은 장부에 있소.", "走吧,市民。或者留下。不管哪样,你都在册子里了。", "走吧,市民。或者留下。不管哪樣,你都在冊子裡了。", "Đi đi, công dân. Hoặc ở lại. Đằng nào thì anh cũng có trong Sổ.", "Silakan jalan, warga. Atau tinggal. Bagaimanapun, kau ada di Buku.", "เดินไปได้แล้ว พลเมือง หรือจะอยู่ก็ได้ ยังไงคุณก็อยู่ในสมุดแล้ว", "Yürü, vatandaş. Ya da kal. Her iki durumda da Defter'desin.", "Circule, ciudadano. O quédese. En cualquier caso, está en el Libro.", "Circulando, cidadão. Ou fique. De qualquer jeito, você está no Livro.", "Проходите, горожанин. Или останьтесь. Так или иначе, вы в Книге.", "Проходьте, городянине. Або залиштеся. Так чи інакше, ви в Книзі."],
  "Seven prayers a week, one at the Salt-House. That's how we count them here.": ["週に七度の祈り、そのうち一度は塩館で。ここではそう数えるんだ。", "일주일에 기도 일곱 번, 그중 한 번은 소금관에서. 여기선 그렇게 세요.", "一周七次祷告,有一次在盐务所。我们这儿就是这么算的。", "一週七次禱告,有一次在鹽務所。我們這兒就是這麼算的。", "Bảy lời cầu nguyện mỗi tuần, một lần ở Nhà Muối. Ở đây chúng tôi đếm như thế.", "Tujuh doa seminggu, satu di Rumah Garam. Begitulah kami menghitungnya di sini.", "สวดเจ็ดครั้งต่อสัปดาห์ หนึ่งครั้งที่โรงเกลือ ที่นี่เรานับกันอย่างนั้น", "Haftada yedi dua, biri Tuz Evi'nde. Burada böyle sayarız.", "Siete oraciones a la semana, una en la Casa de la Sal. Así las contamos aquí.", "Sete orações por semana, uma na Casa do Sal. É assim que contamos aqui.", "Семь молитв в неделю, одна — в Соляном доме. Так мы их здесь считаем.", "Сім молитов на тиждень, одна — у Соляному домі. Так ми їх тут рахуємо."],
  "The capital's just north. You can see the towers from the pans on a clear day. They can see us too, which is the point.": ["都はすぐ北だ。晴れた日には塩田から塔が見える。向こうからもこっちが見える。それが肝心なのさ。", "수도는 바로 북쪽이에요. 맑은 날엔 염전에서 탑들이 보여요. 저쪽에서도 우릴 볼 수 있죠. 그게 요점이고요.", "王都就在北边。天晴时从盐田能看见那些塔。他们也看得见我们,这才是要紧的。", "王都就在北邊。天晴時從鹽田能看見那些塔。他們也看得見我們,這才是要緊的。", "Kinh đô ngay phía bắc. Ngày trời trong có thể thấy những ngọn tháp từ ruộng muối. Họ cũng thấy chúng tôi, mà đó mới là điều chính.", "Ibu kota tepat di utara. Di hari cerah menara-menaranya terlihat dari petak garam. Mereka juga bisa melihat kami, dan itulah intinya.", "เมืองหลวงอยู่ทางเหนือนี่เอง วันฟ้าใสมองเห็นหอคอยจากนาเกลือ พวกเขาก็มองเห็นเราเหมือนกัน ซึ่งนั่นแหละคือประเด็น", "Başkent hemen kuzeyde. Açık bir günde tuzlalardan kuleler görünür. Onlar da bizi görebilir, asıl mesele de bu.", "La capital está justo al norte. En un día claro se ven las torres desde las salinas. Ellos también nos ven, que es de lo que se trata.", "A capital fica logo ao norte. Num dia claro dá para ver as torres das salinas. Eles também nos veem, que é o que importa.", "Столица сразу к северу. В ясный день с бассейнов видны башни. Нас оттуда тоже видно, в этом-то и суть.", "Столиця одразу на північ. У ясний день із басейнів видно вежі. Нас звідти теж видно, у цьому й суть."],
  "I was born in Saltreach. I think. The Ledger says so, and the Ledger is never wrong.": ["私はソルトリーチで生まれた。たぶん。台帳がそう言っているし、台帳は決して間違わない。", "난 솔트리치에서 태어났어요. 아마도. 장부가 그렇다고 하고, 장부는 절대 틀리지 않으니까.", "我生在盐滩港。我想是吧。册子上这么写,而册子从来不会错。", "我生在鹽灘港。我想是吧。冊子上這麼寫,而冊子從來不會錯。", "Tôi sinh ra ở Saltreach. Tôi nghĩ vậy. Sổ nói thế, mà Sổ thì không bao giờ sai.", "Aku lahir di Saltreach. Kurasa. Buku bilang begitu, dan Buku tak pernah salah.", "ฉันเกิดที่ซอลต์รีช มั้ง สมุดบอกอย่างนั้น และสมุดไม่เคยผิด", "Saltreach'te doğdum. Sanırım. Defter öyle diyor ve Defter asla yanılmaz.", "Nací en Saltreach. Creo. Lo dice el Libro, y el Libro nunca se equivoca.", "Nasci em Saltreach. Acho. O Livro diz que sim, e o Livro nunca erra.", "Я родился в Солтриче. Кажется. Так сказано в Книге, а Книга никогда не ошибается.", "Я народився в Солтрічі. Здається. Так сказано в Книзі, а Книга ніколи не помиляється."],
  "Ten fathoms on one breath, and back up with a basket of shells. I've done it twenty years. My ears have stopped thanking me.": ["ひと息で十尋潜って、貝の籠を持って上がる。二十年やってきた。耳はもう礼を言ってくれなくなったよ。", "한 숨에 열 길을 내려갔다가 조개 바구니를 들고 올라오지. 이십 년을 해 왔어. 내 귀는 이제 고마워하지 않아.", "一口气潜到十寻,再提着一篮贝壳上来。我干了二十年。我的耳朵早就不谢我了。", "一口氣潛到十尋,再提著一籃貝殼上來。我幹了二十年。我的耳朵早就不謝我了。", "Mười sải trên một hơi thở, rồi trồi lên với một giỏ vỏ sò. Tôi đã làm thế hai mươi năm. Tai tôi thôi cảm ơn tôi rồi.", "Sepuluh depa dengan satu napas, lalu naik membawa sekeranjang kerang. Dua puluh tahun aku melakukannya. Telingaku sudah berhenti berterima kasih.", "สิบวาด้วยลมหายใจเดียว แล้วขึ้นมาพร้อมตะกร้าหอย ฉันทำมายี่สิบปี หูฉันเลิกขอบคุณฉันแล้ว", "Tek nefeste on kulaç, sonra bir sepet kabukla yukarı. Yirmi yıldır yapıyorum. Kulaklarım bana teşekkür etmeyi bıraktı.", "Diez brazas con un solo aliento, y arriba otra vez con una cesta de conchas. Llevo veinte años. Mis oídos ya no me lo agradecen.", "Dez braças num só fôlego, e de volta com um cesto de conchas. Faço isso há vinte anos. Meus ouvidos pararam de me agradecer.", "Десять саженей на одном вдохе и обратно с корзиной раковин. Двадцать лет так. Уши мои больше меня не благодарят.", "Десять сажнів на одному вдиху й назад із кошиком мушель. Двадцять років так. Вуха мої більше мені не дякують."],
  "The deep beds are the good ones. Nobody's been down for weeks. Something down there has learnt we come up tired.": ["深い真珠床がいい床なんだ。もう何週間も誰も潜ってない。下にいる何かが、私たちが疲れて上がってくるのを覚えちまったんだよ。", "깊은 진주밭이 좋은 곳이야. 몇 주째 아무도 안 내려갔어. 저 아래 무언가가 우리가 지쳐서 올라온다는 걸 알아 버렸거든.", "深珠床才是好的。几个星期没人下去了。下面有个东西学会了:我们上来时都累了。", "深珠床才是好的。幾個星期沒人下去了。下面有個東西學會了:我們上來時都累了。", "Bãi ngọc sâu mới là bãi tốt. Nhiều tuần chẳng ai xuống. Có thứ gì dưới đó đã biết chúng tôi ngoi lên lúc mệt.", "Dasar laut dalam itulah yang bagus. Berminggu-minggu tak ada yang turun. Sesuatu di bawah sana sudah tahu kami naik dalam keadaan lelah.", "แหล่งหอยมุกลึกคือแหล่งที่ดี ไม่มีใครลงไปมาหลายสัปดาห์แล้ว มีอะไรบางอย่างข้างล่างนั่นเรียนรู้ว่าเราขึ้นมาตอนเหนื่อย", "İyi yataklar derin olanlardır. Haftalardır kimse inmedi. Aşağıdaki bir şey yorgun çıktığımızı öğrendi.", "Los bancos profundos son los buenos. Hace semanas que nadie baja. Algo ahí abajo ha aprendido que subimos cansados.", "Os bancos fundos são os bons. Há semanas ninguém desce. Alguma coisa lá embaixo aprendeu que subimos cansados.", "Хорошие отмели — глубокие. Уже несколько недель никто туда не спускался. Что-то там внизу усвоило, что мы поднимаемся усталыми.", "Добрі мілини — глибокі. Уже кілька тижнів ніхто туди не спускався. Щось там унизу засвоїло, що ми виринаємо втомленими."],
  "The Gilded Court lends the boats, buys the pearls and keeps the book. Without the Court, the divers would be fishing for sardines.": ["金色の宮廷が船を貸し、真珠を買い、帳簿をつける。宮廷がなければ、潜り手たちはイワシでも獲っているだろう。", "황금 궁정이 배를 빌려주고, 진주를 사고, 장부를 쥐지. 궁정이 없으면 잠수부들은 정어리나 잡고 있을 거요.", "镀金宫廷借船、收珍珠、记账。没有宫廷,潜水人只能去捞沙丁鱼。", "鍍金宮廷借船、收珍珠、記帳。沒有宮廷,潛水人只能去撈沙丁魚。", "Triều Mạ Vàng cho mượn thuyền, mua ngọc và giữ sổ. Không có Triều, thợ lặn sẽ đi bắt cá mòi.", "Istana Bersepuh meminjamkan perahu, membeli mutiara, dan memegang buku. Tanpa Istana, para penyelam akan menangkap sarden.", "ราชสำนักปิดทองให้ยืมเรือ ซื้อไข่มุก และถือสมุดบัญชี ถ้าไม่มีราชสำนัก นักดำน้ำคงต้องจับปลาซาร์ดีน", "Yaldızlı Saray tekneleri ödünç verir, incileri alır ve defteri tutar. Saray olmasa dalgıçlar sardalye avlıyor olurdu.", "La Corte Dorada presta las barcas, compra las perlas y lleva el libro. Sin la Corte, los buceadores estarían pescando sardinas.", "A Corte Dourada empresta os barcos, compra as pérolas e guarda o livro. Sem a Corte, os mergulhadores estariam pescando sardinhas.", "Позолоченный двор ссужает лодки, скупает жемчуг и ведёт книгу. Без Двора ныряльщики ловили бы сардину.", "Позолочений двір позичає човни, скуповує перли й веде книгу. Без Двору пірнальники ловили б сардину."],
  "A pearl is a debt the sea pays back slowly. I merely keep the accounts.": ["真珠とは、海がゆっくりと返す借りだ。私は帳簿をつけているにすぎない。", "진주란 바다가 천천히 갚는 빚이오. 나는 그저 장부를 적을 뿐이지.", "珍珠是大海慢慢偿还的一笔债。我不过是记账罢了。", "珍珠是大海慢慢償還的一筆債。我不過是記帳罷了。", "Một viên ngọc là món nợ biển trả dần. Tôi chỉ giữ sổ sách.", "Mutiara adalah utang yang dibayar laut perlahan. Aku hanya memegang pembukuannya.", "ไข่มุกคือหนี้ที่ทะเลค่อยๆ ใช้คืน ผมแค่ทำบัญชี", "İnci, denizin yavaş yavaş geri ödediği bir borçtur. Ben yalnızca hesapları tutarım.", "Una perla es una deuda que el mar devuelve despacio. Yo solo llevo las cuentas.", "Uma pérola é uma dívida que o mar paga devagar. Eu apenas cuido das contas.", "Жемчужина — это долг, который море возвращает медленно. Я лишь веду счета.", "Перлина — це борг, який море повертає повільно. Я лише веду рахунки."],
  "Khetmar's harbour, Khetmar's dues. The Marshal wants a port on the east coast. The Marshal has one. It's hot.": ["ケトマルの港、ケトマルの税。元帥は東海岸に港をお望みだった。元帥は港を手に入れた。暑いがな。", "케트마르의 항구, 케트마르의 세금. 원수께선 동쪽 해안에 항구를 원하셨지. 원수께선 하나 가지셨어. 덥지.", "克特马尔的港口,克特马尔的税。元帅想在东海岸要个港口。元帅有了一个。热得很。", "克特馬爾的港口,克特馬爾的稅。元帥想在東海岸要個港口。元帥有了一個。熱得很。", "Cảng của Khetmar, thuế của Khetmar. Thống chế muốn một cảng ở bờ biển phía đông. Thống chế có một cái rồi. Nóng.", "Pelabuhan Khetmar, bea Khetmar. Marsekal menginginkan pelabuhan di pantai timur. Marsekal sudah punya satu. Panas.", "ท่าเรือของเคทมาร์ ค่าธรรมเนียมของเคทมาร์ จอมพลอยากได้เมืองท่าบนชายฝั่งตะวันออก จอมพลได้แล้ว มันร้อน", "Khetmar'ın limanı, Khetmar'ın vergileri. Mareşal doğu kıyısında bir liman istiyordu. Mareşal'in bir limanı var. Sıcak.", "El puerto de Khetmar, los derechos de Khetmar. El Mariscal quería un puerto en la costa este. El Mariscal tiene uno. Hace calor.", "O porto de Khetmar, as taxas de Khetmar. O Marechal queria um porto na costa leste. O Marechal tem um. É quente.", "Гавань Кетмара, сборы Кетмара. Маршал хотел порт на восточном побережье. У маршала есть порт. Жарко.", "Гавань Кетмара, збори Кетмара. Маршал хотів порт на східному узбережжі. У маршала є порт. Спекотно."],
  "Boats from Meghavan bring teak and rice; boats from Merrab take pearls and salt. The Banner takes a tenth of both, politely.": ["メーガヴァンの船はチークと米を運んでくる。メラブの船は真珠と塩を運んでいく。旗はその両方から十分の一を、礼儀正しくいただく。", "메가반의 배들은 티크와 쌀을 가져오고, 메라브의 배들은 진주와 소금을 가져가지. 깃발은 둘 다에서 십분의 일을, 공손하게 떼어 가고.", "梅加万的船运来柚木和稻米;梅拉布的船运走珍珠和盐。铜旗从两样里都抽一成,彬彬有礼。", "梅加萬的船運來柚木和稻米;梅拉布的船運走珍珠和鹽。銅旗從兩樣裡都抽一成,彬彬有禮。", "Thuyền từ Meghavan mang tếch và gạo tới; thuyền từ Merrab chở ngọc và muối đi. Cờ lấy một phần mười của cả hai, một cách lịch sự.", "Perahu dari Meghavan membawa jati dan beras; perahu dari Merrab membawa mutiara dan garam. Panji mengambil sepersepuluh dari keduanya, dengan sopan.", "เรือจากเมฆาวันนำไม้สักและข้าวมา เรือจากเมอร์รับนำไข่มุกและเกลือไป ธงเก็บหนึ่งในสิบจากทั้งสองอย่าง อย่างสุภาพ", "Meghavan'dan gelen tekneler tik ve pirinç getirir; Merrab'dan çıkanlar inci ve tuz götürür. Sancak ikisinden de onda birini kibarca alır.", "Las barcas de Meghavan traen teca y arroz; las de Merrab se llevan perlas y sal. El Estandarte se queda un diezmo de ambas, con educación.", "Os barcos de Meghavan trazem teca e arroz; os de Merrab levam pérolas e sal. O Estandarte fica com um décimo de ambos, educadamente.", "Лодки из Мегхавана везут тик и рис; лодки из Мерраба увозят жемчуг и соль. Знамя берёт десятую часть того и другого, вежливо.", "Човни з Мегхавану везуть тик і рис; човни з Меррабу вивозять перли й сіль. Стяг бере десяту частину того й того, чемно."],
  "Eat, eat, you look like a diver after a dry week. Pay when you're paid. The factor hates that.": ["食べな、食べな、潜れない週のあとの潜り手みたいな顔してるよ。お代は払ってもらったら払えばいい。代理商はそれが大嫌いなのさ。", "먹어, 먹어, 공친 한 주를 보낸 잠수부 같은 얼굴이네. 돈은 받으면 내. 중개인은 그걸 질색하지.", "吃吧吃吧,你这样子像个白干了一礼拜的潜水人。等你拿到钱再付。代理商最恨这个。", "吃吧吃吧,你這樣子像個白幹了一禮拜的潛水人。等你拿到錢再付。代理商最恨這個。", "Ăn đi, ăn đi, trông cưng như thợ lặn sau một tuần trắng tay. Khi nào được trả thì trả. Viên đại lý ghét thế lắm.", "Makan, makan, kau seperti penyelam setelah seminggu tanpa hasil. Bayar kalau kau dibayar. Si agen benci itu.", "กินสิ กินเข้าไป เธอดูเหมือนนักดำน้ำหลังสัปดาห์ที่ไม่ได้อะไรเลย ได้เงินเมื่อไรค่อยจ่าย ตัวแทนเกลียดเรื่องนี้", "Ye, ye, kuru bir haftadan sonraki dalgıç gibi görünüyorsun. Sana ödendiğinde ödersin. Kâhya bundan nefret eder.", "Come, come, que pareces un buceador tras una semana en seco. Paga cuando te paguen. Al factor le revienta.", "Coma, coma, você parece um mergulhador depois de uma semana seca. Pague quando lhe pagarem. O feitor detesta isso.", "Ешь, ешь, у тебя вид ныряльщика после пустой недели. Заплатишь, когда тебе заплатят. Фактор это ненавидит.", "Їж, їж, у тебе вигляд пірнальника після порожнього тижня. Заплатиш, коли тобі заплатять. Фактор це ненавидить."],
  "The divers' tables are by the window, so they can see the beds. They haven't been looking lately.": ["潜り手の席は窓際。真珠床が見えるようにね。近ごろは誰も見ていないけど。", "잠수부들 자리는 창가야. 진주밭이 보이게. 요즘은 아무도 안 내다보지만.", "潜水人的桌子在窗边,好看得见珠床。最近他们都不怎么看了。", "潛水人的桌子在窗邊,好看得見珠床。最近他們都不怎麼看了。", "Bàn của thợ lặn ở cạnh cửa sổ, để họ nhìn thấy bãi ngọc. Dạo này họ chẳng nhìn nữa.", "Meja para penyelam di dekat jendela, supaya mereka bisa melihat dasar laut. Akhir-akhir ini mereka tak melihat.", "โต๊ะของนักดำน้ำอยู่ริมหน้าต่าง เพื่อให้มองเห็นแหล่งหอยมุก ช่วงนี้พวกเขาไม่ได้มอง", "Dalgıçların masaları pencere kenarında, yatakları görebilsinler diye. Son zamanlarda bakmıyorlar.", "Las mesas de los buceadores están junto a la ventana, para que vean los bancos. Últimamente no miran.", "As mesas dos mergulhadores ficam junto à janela, para que vejam os bancos. Ultimamente eles não olham.", "Столы ныряльщиков у окна, чтобы видеть отмели. Последнее время они туда не смотрят.", "Столи пірнальників біля вікна, щоб бачити мілини. Останнім часом вони туди не дивляться."],
  "Diving stones, nose-clips, rope, dates. Gold or copper, I'll take either, and argue about both.": ["潜水石、鼻ばさみ、縄、ナツメヤシ。金貨でも銅貨でも受け取るし、どっちでも値切り合いはするよ。", "잠수돌, 코집게, 밧줄, 대추야자. 금화든 동전이든 다 받고, 둘 다 흥정하지.", "潜水石、鼻夹、绳子、椰枣。金币铜板我都收,两样都讲价。", "潛水石、鼻夾、繩子、椰棗。金幣銅板我都收,兩樣都講價。", "Đá lặn, kẹp mũi, dây thừng, chà là. Vàng hay đồng, tôi nhận cả, và mặc cả cả hai.", "Batu selam, penjepit hidung, tali, kurma. Emas atau tembaga, kuterima keduanya, dan kutawar keduanya.", "หินดำน้ำ ที่หนีบจมูก เชือก อินทผลัม ทองหรือทองแดง ผมรับหมด และต่อรองทั้งคู่", "Dalış taşları, burun mandalları, ip, hurma. Altın da bakır da alırım, ikisinde de pazarlık ederim.", "Piedras de buceo, pinzas de nariz, cuerda, dátiles. Oro o cobre, acepto los dos, y regateo por ambos.", "Pedras de mergulho, prendedores de nariz, corda, tâmaras. Ouro ou cobre, aceito os dois, e pechincho pelos dois.", "Ныряльные камни, носовые зажимы, верёвка, финики. Золото или медь — возьму любое и поторгуюсь за оба.", "Пірнальні камені, носові затискачі, мотузка, фініки. Золото чи мідь — візьму будь-що й поторгуюся за обидва."],
  "Sea-green for the divers. Brings the pearls up faster, my grandmother said. She also said it brought her husband home, so she wasn't always right.": ["潜り手には海緑。真珠が早く上がるって祖母は言ってた。それで夫が帰ってきたとも言ってたから、いつも正しかったわけじゃないね。", "잠수부들한텐 바다빛 초록. 진주를 더 빨리 올려 준다고 할머니가 그랬지. 그걸로 남편도 돌아왔다고 했으니, 할머니가 늘 옳았던 건 아니야.", "潜水人穿海绿色。我奶奶说这样珍珠捞得快。她还说这颜色让她男人回了家,所以她也不总是对的。", "潛水人穿海綠色。我奶奶說這樣珍珠撈得快。她還說這顏色讓她男人回了家,所以她也不總是對的。", "Màu xanh biển cho thợ lặn. Bà tôi bảo nó giúp ngọc lên nhanh hơn. Bà cũng bảo nó đưa chồng bà về nhà, nên bà không phải lúc nào cũng đúng.", "Hijau laut untuk para penyelam. Membuat mutiara naik lebih cepat, kata nenekku. Ia juga bilang warna itu membawa suaminya pulang, jadi ia tak selalu benar.", "สีเขียวน้ำทะเลสำหรับนักดำน้ำ ยายบอกว่ามันทำให้ไข่มุกขึ้นมาเร็วขึ้น ยายยังบอกว่ามันพาสามีกลับบ้าน ยายเลยไม่ได้ถูกเสมอไป", "Dalgıçlara deniz yeşili. İncileri daha hızlı çıkarır, derdi ninem. Kocasını eve getirdiğini de söylerdi, yani hep haklı değildi.", "Verde mar para los buceadores. Hace subir las perlas más deprisa, decía mi abuela. También decía que le traía al marido a casa, así que no siempre acertaba.", "Verde-mar para os mergulhadores. Faz as pérolas subirem mais depressa, dizia minha avó. Também dizia que trazia o marido de volta, então nem sempre acertava.", "Цвет морской волны — для ныряльщиков. Бабушка говорила, так жемчуг поднимается быстрее. Ещё она говорила, что так муж возвращается домой, так что права была не всегда.", "Колір морської хвилі — для пірнальників. Бабуся казала, так перли піднімаються швидше. Ще вона казала, що так чоловік повертається додому, тож не завжди мала рацію."],
  "Meghavan teak, Merrab hands. A diving boat lasts thirty years if the divers do.": ["メーガヴァンのチークにメラブの手。潜り手が持つなら、潜水船は三十年持つ。", "메가반 티크에 메라브의 손. 잠수부가 버티면 잠수선은 삼십 년을 가지.", "梅加万的柚木,梅拉布的手艺。只要潜水人撑得住,潜水船能用三十年。", "梅加萬的柚木,梅拉布的手藝。只要潛水人撐得住,潛水船能用三十年。", "Gỗ tếch Meghavan, bàn tay Merrab. Một chiếc thuyền lặn bền ba mươi năm nếu thợ lặn cũng bền như thế.", "Jati Meghavan, tangan Merrab. Perahu selam bertahan tiga puluh tahun kalau penyelamnya juga.", "ไม้สักเมฆาวัน มือเมอร์รับ เรือดำน้ำหามุกอยู่ได้สามสิบปี ถ้านักดำน้ำอยู่ได้", "Meghavan tiki, Merrab elleri. Dalgıçlar dayanırsa bir dalış teknesi otuz yıl dayanır.", "Teca de Meghavan, manos de Merrab. Una barca de buceo dura treinta años si los buceadores duran.", "Teca de Meghavan, mãos de Merrab. Um barco de mergulho dura trinta anos se os mergulhadores durarem.", "Мегхаванский тик, меррабские руки. Ныряльная лодка служит тридцать лет, если ныряльщики выдержат.", "Мегхаванський тик, меррабські руки. Пірнальний човен служить тридцять років, якщо пірнальники витримають."],
  "Half the boats are up on the trestles, mending. No diving, no money; no money, no mending. I mend them anyway.": ["船の半分は架台の上で修理中だ。潜れなきゃ金がない、金がなきゃ修理できない。それでも俺は直すがね。", "배 절반이 받침대 위에서 수리 중이오. 잠수를 못 하면 돈이 없고, 돈이 없으면 수리도 못 하지. 그래도 나는 고치오.", "一半的船架在支架上修。不能潜水就没钱,没钱就修不了。我照样修。", "一半的船架在支架上修。不能潛水就沒錢,沒錢就修不了。我照樣修。", "Nửa số thuyền nằm trên giá chờ sửa. Không lặn thì không tiền; không tiền thì không sửa. Tôi vẫn cứ sửa.", "Separuh perahu ada di atas kuda-kuda, diperbaiki. Tak menyelam, tak ada uang; tak ada uang, tak ada perbaikan. Aku tetap memperbaikinya.", "เรือครึ่งหนึ่งอยู่บนขาหยั่งรอซ่อม ไม่ได้ดำน้ำก็ไม่มีเงิน ไม่มีเงินก็ไม่ได้ซ่อม ผมก็ซ่อมอยู่ดี", "Teknelerin yarısı sehpalarda, onarımda. Dalış yoksa para yok; para yoksa onarım yok. Ben yine de onarırım.", "La mitad de las barcas están en los caballetes, en reparación. Sin buceo no hay dinero; sin dinero, no hay reparación. Yo las reparo igual.", "Metade dos barcos está nos cavaletes, em conserto. Sem mergulho, sem dinheiro; sem dinheiro, sem conserto. Eu conserto assim mesmo.", "Половина лодок на козлах, в починке. Нет ныряния — нет денег; нет денег — нет починки. Я всё равно чиню.", "Половина човнів на козлах, у лагодженні. Нема пірнання — нема грошей; нема грошей — нема лагодження. Я однаково лагоджу."],
  "We dive the shallow beds now. Small shells, small pearls, small money. The debt doesn't get any smaller.": ["今は浅い床にしか潜らない。小さい貝、小さい真珠、少ない金。借りだけは少しも小さくならない。", "이젠 얕은 진주밭만 들어가. 작은 조개, 작은 진주, 적은 돈. 빚은 조금도 작아지지 않고.", "现在我们只潜浅珠床。小贝壳,小珍珠,小钱。债可一点没变小。", "現在我們只潛淺珠床。小貝殼,小珍珠,小錢。債可一點沒變小。", "Giờ chúng tôi lặn bãi cạn. Vỏ nhỏ, ngọc nhỏ, tiền nhỏ. Món nợ thì chẳng nhỏ đi chút nào.", "Kami menyelam di dasar dangkal sekarang. Kerang kecil, mutiara kecil, uang kecil. Utangnya tak jadi lebih kecil.", "ตอนนี้เราดำแค่แหล่งตื้น หอยเล็ก ไข่มุกเล็ก เงินน้อย หนี้ไม่ได้เล็กลงเลย", "Artık sığ yatakları dalıyoruz. Küçük kabuklar, küçük inciler, küçük para. Borç hiç küçülmüyor.", "Ahora buceamos los bancos someros. Conchas pequeñas, perlas pequeñas, poco dinero. La deuda no se hace más pequeña.", "Agora mergulhamos os bancos rasos. Conchas pequenas, pérolas pequenas, pouco dinheiro. A dívida não diminui nada.", "Теперь ныряем на мелкие отмели. Мелкие раковины, мелкий жемчуг, мелкие деньги. Долг мельче не становится.", "Тепер пірнаємо на мілкі мілини. Дрібні мушлі, дрібні перли, дрібні гроші. Борг дрібнішим не стає."],
  "Old Saltjaw. We called him that when he was smaller. He's not smaller now.": ["古顎のソルトジョー。あいつが小さかったころにそう呼んだんだ。今はもう小さくない。", "늙은 솔트조. 그놈이 작을 때 그렇게 불렀지. 지금은 작지 않아.", "老盐颚。它还小的时候我们就这么叫它。现在它可不小了。", "老鹽顎。它還小的時候我們就這麼叫它。現在它可不小了。", "Lão Hàm Muối. Chúng tôi gọi nó thế khi nó còn nhỏ. Giờ nó không nhỏ nữa.", "Si Tua Rahang Garam. Kami menamainya begitu waktu ia masih kecil. Sekarang ia tak kecil lagi.", "เจ้าขากรรไกรเกลือเฒ่า เราเรียกมันอย่างนั้นตอนมันยังตัวเล็ก ตอนนี้มันไม่เล็กแล้ว", "Yaşlı Tuzçene. Ona küçükken öyle derdik. Artık küçük değil.", "El viejo Quijada de Sal. Lo llamábamos así cuando era más pequeño. Ya no es pequeño.", "O velho Queixada de Sal. Chamávamos assim quando ele era menor. Agora não é menor.", "Старый Солечелюст. Мы так его прозвали, когда он был поменьше. Теперь он не поменьше.", "Старий Солещелепий. Ми так його прозвали, коли він був меншим. Тепер він не менший."],
  "Copper Banner, harbour duty. The sea's the only thing round here that doesn't pay the Marshal.": ["銅の旗、港湾勤務。このあたりで元帥に払わないのは海だけだ。", "구리 깃발, 항구 근무. 이 근방에서 원수께 돈을 안 내는 건 바다뿐이야.", "铜旗,港口执勤。这一带不给元帅交钱的只有大海。", "銅旗,港口執勤。這一帶不給元帥交錢的只有大海。", "Cờ Đồng, trực cảng. Biển là thứ duy nhất quanh đây không nộp tiền cho Thống chế.", "Panji Tembaga, tugas pelabuhan. Laut satu-satunya hal di sekitar sini yang tak membayar Marsekal.", "ธงทองแดง ประจำท่าเรือ ทะเลเป็นสิ่งเดียวแถวนี้ที่ไม่จ่ายเงินให้จอมพล", "Bakır Sancak, liman görevi. Buralarda Mareşal'e ödeme yapmayan tek şey deniz.", "Estandarte de Cobre, servicio en el puerto. El mar es lo único por aquí que no le paga al Mariscal.", "Estandarte de Cobre, serviço no porto. O mar é a única coisa por aqui que não paga ao Marechal.", "Медное знамя, портовая служба. Море — единственное здесь, что не платит маршалу.", "Мідний стяг, портова служба. Море — єдине тут, що не платить маршалові."],
  "Watch your purse on the quay. Not because of thieves: because of Hashim.": ["岸壁では財布に気をつけろ。泥棒のせいじゃない。ハシムのせいだ。", "부두에선 지갑 조심해. 도둑 때문이 아니라 하심 때문에.", "在码头上看好你的钱袋。不是因为小偷,是因为哈希姆。", "在碼頭上看好你的錢袋。不是因為小偷,是因為哈希姆。", "Giữ túi tiền trên bến. Không phải vì kẻ trộm: vì Hashim.", "Jaga dompetmu di dermaga. Bukan karena pencuri: karena Hashim.", "ระวังกระเป๋าเงินบนท่าเรือ ไม่ใช่เพราะขโมย เพราะฮาชิม", "Rıhtımda kesene dikkat et. Hırsızlar yüzünden değil: Hashim yüzünden.", "Vigila la bolsa en el muelle. No por los ladrones: por Hashim.", "Cuide da bolsa no cais. Não por causa dos ladrões: por causa de Hashim.", "Береги кошелёк на причале. Не из-за воров — из-за Хашима.", "Бережи гаманець на причалі. Не через злодіїв — через Хашима."],
  "Everybody in Merrab owes the factor something. Even the factor's cook. Especially the factor's cook.": ["メラブじゅうの誰もが代理商に何か借りがある。代理商の料理人でさえ。いや、料理人こそ。", "메라브 사람은 누구나 중개인에게 빚이 있어. 중개인의 요리사조차. 특히 중개인의 요리사가.", "梅拉布人人都欠代理商点什么。连代理商的厨子也欠。尤其是代理商的厨子。", "梅拉布人人都欠代理商點什麼。連代理商的廚子也欠。尤其是代理商的廚子。", "Ở Merrab ai cũng nợ viên đại lý thứ gì đó. Kể cả đầu bếp của ông ta. Nhất là đầu bếp của ông ta.", "Semua orang di Merrab berutang sesuatu pada si agen. Bahkan juru masak si agen. Terutama juru masak si agen.", "ทุกคนในเมอร์รับติดหนี้ตัวแทนอะไรสักอย่าง แม้แต่พ่อครัวของตัวแทน โดยเฉพาะพ่อครัวของตัวแทน", "Merrab'da herkes kâhyaya bir şey borçlu. Kâhyanın aşçısı bile. Özellikle kâhyanın aşçısı.", "En Merrab todo el mundo le debe algo al factor. Hasta el cocinero del factor. Sobre todo el cocinero del factor.", "Em Merrab todo mundo deve alguma coisa ao feitor. Até o cozinheiro do feitor. Principalmente o cozinheiro do feitor.", "В Меррабе каждый что-нибудь должен фактору. Даже повар фактора. Особенно повар фактора.", "У Меррабі кожен щось винен факторові. Навіть кухар фактора. Особливо кухар фактора."],
  "Khetmar's up the road. Meghavan's across the water. We're in between, which is where the money goes past.": ["ケトマルは街道の先。メーガヴァンは海の向こう。私たちはそのあいだ、金が通り過ぎていくところさ。", "케트마르는 길 따라 위쪽, 메가반은 물 건너. 우리는 그 사이, 돈이 지나가는 자리야.", "克特马尔在路那头,梅加万在海对面。我们夹在中间,钱就从这儿过。", "克特馬爾在路那頭,梅加萬在海對面。我們夾在中間,錢就從這兒過。", "Khetmar ở trên đường. Meghavan ở bên kia mặt nước. Chúng tôi ở giữa, nơi tiền bạc đi ngang qua.", "Khetmar di ujung jalan. Meghavan di seberang air. Kami di antaranya, tempat uang lewat.", "เคทมาร์อยู่ตามถนนขึ้นไป เมฆาวันอยู่อีกฝั่งน้ำ เราอยู่ตรงกลาง ซึ่งเป็นที่ที่เงินผ่านไป", "Khetmar yolun yukarısında. Meghavan suyun karşısında. Biz arasındayız, paranın geçip gittiği yer.", "Khetmar está camino arriba. Meghavan, al otro lado del agua. Nosotros en medio, que es por donde pasa el dinero.", "Khetmar fica estrada acima. Meghavan, do outro lado da água. Nós no meio, que é por onde o dinheiro passa.", "Кетмар — вверх по дороге. Мегхаван — за водой. Мы посередине, там, где проходят деньги.", "Кетмар — угору дорогою. Мегхаван — за водою. Ми посередині, там, де проходять гроші."],
  "The pearls go to Sefrah, the divers stay here. That's the trade.": ["真珠はセフラへ行き、潜り手はここに残る。それが商売ってもんさ。", "진주는 세프라로 가고, 잠수부는 여기 남아. 그게 장사야.", "珍珠去了塞弗拉,潜水人留在这儿。生意就是这样。", "珍珠去了塞弗拉,潛水人留在這兒。生意就是這樣。", "Ngọc đi Sefrah, thợ lặn ở lại đây. Buôn bán là thế.", "Mutiara pergi ke Sefrah, penyelam tinggal di sini. Begitulah dagangnya.", "ไข่มุกไปเซฟราห์ นักดำน้ำอยู่ที่นี่ การค้าก็เป็นอย่างนี้", "İnciler Sefrah'a gider, dalgıçlar burada kalır. Ticaret budur.", "Las perlas se van a Sefrah, los buceadores se quedan aquí. Así es el negocio.", "As pérolas vão para Sefrah, os mergulhadores ficam aqui. É o negócio.", "Жемчуг уходит в Сефру, ныряльщики остаются здесь. Такая торговля.", "Перли йдуть до Сефри, пірнальники лишаються тут. Така торгівля."],
  "The tell is our grandmothers' houses, and theirs, and theirs, all the way down. Every village here was built on the last.": ["この丘は私たちの祖母たちの家、そのまた祖母たち、そのまた祖母たちの家が、底までずっと重なったもの。ここの村はどれも前の村の上に建てられたんだよ。", "이 언덕은 우리 할머니들의 집, 그분들의 할머니들, 또 그 할머니들의 집이 바닥까지 쌓인 거야. 여기 마을은 모두 앞 마을 위에 지어졌지.", "这土丘就是我们祖母们的房子,还有她们祖母的,再往上辈的,一直堆到底。这里的每个村子都建在上一个村子上面。", "這土丘就是我們祖母們的房子,還有她們祖母的,再往上輩的,一直堆到底。這裡的每個村子都建在上一個村子上面。", "Gò đất là nhà của các bà chúng tôi, và của các bà họ, và của các bà nữa, chồng tới tận đáy. Mỗi ngôi làng ở đây đều xây trên ngôi làng trước.", "Gundukan ini adalah rumah nenek-nenek kami, dan nenek mereka, dan nenek mereka lagi, sampai ke dasar. Setiap desa di sini dibangun di atas desa sebelumnya.", "เนินนี้คือบ้านของยายของเรา และของยายของพวกเธอ และของยายของยายอีก ซ้อนลงไปถึงก้น ทุกหมู่บ้านที่นี่สร้างบนหมู่บ้านก่อนหน้า", "Höyük, ninelerimizin evleri, onların ninelerinin ve onlarınkinin, ta dibe kadar. Buradaki her köy bir öncekinin üstüne kuruldu.", "El montículo son las casas de nuestras abuelas, y de las suyas, y de las suyas, hasta el fondo. Cada aldea de aquí se construyó sobre la anterior.", "O monte são as casas das nossas avós, e das avós delas, e das delas, até o fundo. Cada aldeia daqui foi construída sobre a anterior.", "Холм — это дома наших бабушек, и их бабушек, и их бабушек, до самого низа. Каждая деревня здесь стоит на предыдущей.", "Пагорб — це хати наших бабусь, і їхніх бабусь, і їхніх, до самого низу. Кожне село тут стоїть на попередньому."],
  "We need bricks. The river clay's gone. The tell's clay. You see the difficulty, and so does everybody, every morning.": ["煉瓦が要る。川の粘土はもうない。丘は粘土だ。難しさが分かるだろう。みんなも分かっている、毎朝ね。", "벽돌이 필요해. 강 진흙은 없어졌어. 언덕은 진흙이고. 어려움을 알겠지. 모두가 알아, 매일 아침.", "我们需要砖。河泥没了。土丘就是泥。你看出难处了,大家也都看得出,每天早上都看得出。", "我們需要磚。河泥沒了。土丘就是泥。你看出難處了,大家也都看得出,每天早上都看得出。", "Chúng tôi cần gạch. Đất sét sông hết rồi. Gò là đất sét. Anh thấy cái khó rồi, và ai cũng thấy, mỗi sáng.", "Kami butuh bata. Tanah liat sungai sudah habis. Gundukan itu tanah liat. Kau lihat kesulitannya, dan semua orang juga, setiap pagi.", "เราต้องการอิฐ ดินเหนียวริมแม่น้ำหมดแล้ว เนินคือดินเหนียว คุณเห็นความลำบาก และทุกคนก็เห็น ทุกเช้า", "Tuğlaya ihtiyacımız var. Nehir kili bitti. Höyük kil. Zorluğu görüyorsun, herkes de görüyor, her sabah.", "Necesitamos ladrillos. El barro del río se acabó. El montículo es barro. Ves la dificultad, y todo el mundo la ve, cada mañana.", "Precisamos de tijolos. O barro do rio acabou. O monte é barro. Você vê a dificuldade, e todo mundo vê, toda manhã.", "Нам нужен кирпич. Речная глина кончилась. Холм — глина. Ты видишь, в чём трудность, и все видят, каждое утро.", "Нам потрібна цегла. Річкова глина скінчилася. Пагорб — глина. Ти бачиш, у чому складність, і всі бачать, щоранку."],
  "Water, straw, tell clay, a mould and the sun. A hundred bricks a day. The tell's been here a thousand years; it can spare a hundred bricks.": ["水、藁、丘の粘土、型枠、そしてお日様。一日に煉瓦百個。丘は千年ここにある。煉瓦百個くらい分けてくれるさ。", "물, 짚, 언덕 흙, 틀, 그리고 해. 하루에 벽돌 백 장. 언덕은 천 년을 여기 있었어. 벽돌 백 장쯤은 내줄 수 있지.", "水、麦秆、土丘的泥、一个模子,还有太阳。一天一百块砖。土丘在这儿一千年了,匀出一百块砖不算什么。", "水、麥稈、土丘的泥、一個模子,還有太陽。一天一百塊磚。土丘在這兒一千年了,勻出一百塊磚不算什麼。", "Nước, rơm, đất sét của gò, một cái khuôn và mặt trời. Một trăm viên gạch mỗi ngày. Gò đã ở đây một nghìn năm; nó cho được một trăm viên gạch.", "Air, jerami, tanah liat gundukan, cetakan, dan matahari. Seratus bata sehari. Gundukan ini sudah seribu tahun di sini; ia bisa merelakan seratus bata.", "น้ำ ฟาง ดินเหนียวของเนิน แม่พิมพ์ และดวงอาทิตย์ อิฐวันละร้อยก้อน เนินอยู่ที่นี่มาพันปี สละอิฐร้อยก้อนได้", "Su, saman, höyük kili, bir kalıp ve güneş. Günde yüz tuğla. Höyük bin yıldır burada; yüz tuğlayı esirgemez.", "Agua, paja, barro del montículo, un molde y el sol. Cien ladrillos al día. El montículo lleva aquí mil años; puede prestar cien ladrillos.", "Água, palha, barro do monte, um molde e o sol. Cem tijolos por dia. O monte está aqui há mil anos; pode ceder cem tijolos.", "Вода, солома, глина с холма, форма и солнце. Сотня кирпичей в день. Холм стоит тут тысячу лет; сотню кирпичей он уступит.", "Вода, солома, глина з пагорба, форма й сонце. Сотня цеглин на день. Пагорб стоїть тут тисячу років; сотню цеглин він поступиться."],
  "My bricks are the best in the east because the clay's been made once already. Twice, some of it.": ["俺の煉瓦が東でいちばんなのは、粘土がもう一度作られたものだからさ。二度のもある。", "내 벽돌이 동쪽에서 최고인 건 흙이 이미 한 번 만들어진 거라서야. 어떤 건 두 번.", "我的砖是东边最好的,因为这泥已经做过一回砖了。有些还做过两回。", "我的磚是東邊最好的,因為這泥已經做過一回磚了。有些還做過兩回。", "Gạch của tôi tốt nhất miền đông vì đất sét đã được làm một lần rồi. Có chỗ là hai lần.", "Bataku terbaik di timur karena tanah liatnya sudah pernah dibuat sekali. Sebagian dua kali.", "อิฐของผมดีที่สุดในแถบตะวันออก เพราะดินเหนียวเคยถูกทำเป็นอิฐมาแล้วครั้งหนึ่ง บางส่วนสองครั้ง", "Tuğlalarım doğunun en iyisidir, çünkü kil zaten bir kez yapılmış. Bir kısmı iki kez.", "Mis ladrillos son los mejores del este porque el barro ya se hizo una vez. Parte de él, dos.", "Meus tijolos são os melhores do leste porque o barro já foi feito uma vez. Parte dele, duas.", "Мои кирпичи лучшие на востоке, потому что глина уже раз была кирпичом. Кое-какая — дважды.", "Мої цеглини найкращі на сході, бо глина вже раз була цеглою. Дещо — двічі."],
  "The Obsidian Legacy keeps every monument in Kharaveth. A tell is a monument nobody meant to build.": ["黒曜の遺統はカラヴェスのあらゆる遺跡を守っています。丘とは、誰も建てるつもりのなかった遺跡です。", "흑요 유산은 카라베스의 모든 기념물을 지킵니다. 언덕이란 아무도 지을 생각이 없었던 기념물이지요.", "黑曜遗脉守护卡拉维斯的每一处古迹。土丘是一处谁也没打算建的古迹。", "黑曜遺脈守護卡拉維斯的每一處古蹟。土丘是一處誰也沒打算建的古蹟。", "Di Sản Hắc Diện gìn giữ mọi tượng đài ở Kharaveth. Một gò đất là tượng đài không ai định xây.", "Warisan Obsidian menjaga setiap monumen di Kharaveth. Gundukan adalah monumen yang tak seorang pun berniat membangunnya.", "มรดกออบซิเดียนดูแลอนุสรณ์สถานทุกแห่งในคาราเวธ เนินคืออนุสรณ์สถานที่ไม่มีใครตั้งใจจะสร้าง", "Obsidyen Mirası Kharaveth'teki her anıtı korur. Bir höyük, kimsenin yapmayı amaçlamadığı bir anıttır.", "El Legado de Obsidiana guarda todos los monumentos de Kharaveth. Un montículo es un monumento que nadie quiso construir.", "O Legado de Obsidiana guarda todos os monumentos de Kharaveth. Um monte é um monumento que ninguém quis construir.", "Обсидиановое наследие хранит каждый памятник Харавета. Холм — памятник, который никто не собирался строить.", "Обсидіанова спадщина береже кожну пам'ятку Харавета. Пагорб — пам'ятка, яку ніхто не збирався будувати."],
  "I write each layer before it's dug. Ash, floor, ash, floor. Sometimes a doorway. Once, a child's toy.": ["掘られる前に、層をひとつずつ書き留めます。灰、床、灰、床。ときどき戸口。一度は子どものおもちゃ。", "파내기 전에 층마다 기록합니다. 재, 바닥, 재, 바닥. 가끔은 문간. 한 번은 아이 장난감.", "每一层被挖掉之前我都记下来。灰烬、地面、灰烬、地面。有时是一道门口。有一次,是一个孩子的玩具。", "每一層被挖掉之前我都記下來。灰燼、地面、灰燼、地面。有時是一道門口。有一次,是一個孩子的玩具。", "Tôi ghi lại từng lớp trước khi nó bị đào. Tro, nền, tro, nền. Đôi khi một ô cửa. Một lần, đồ chơi của một đứa trẻ.", "Aku mencatat setiap lapisan sebelum digali. Abu, lantai, abu, lantai. Kadang ambang pintu. Sekali, mainan anak.", "ฉันจดแต่ละชั้นก่อนถูกขุด เถ้า พื้น เถ้า พื้น บางครั้งเป็นวงกบประตู ครั้งหนึ่ง ของเล่นเด็ก", "Her katmanı kazılmadan önce yazarım. Kül, taban, kül, taban. Bazen bir kapı aralığı. Bir kez, bir çocuk oyuncağı.", "Anoto cada capa antes de que la caven. Ceniza, suelo, ceniza, suelo. A veces un umbral. Una vez, un juguete de niño.", "Anoto cada camada antes de ser escavada. Cinza, piso, cinza, piso. Às vezes uma soleira. Uma vez, o brinquedo de uma criança.", "Я записываю каждый слой, прежде чем его выкопают. Пепел, пол, пепел, пол. Иногда дверной проём. Однажды — детская игрушка.", "Я записую кожен шар, перш ніж його викопають. Попіл, долівка, попіл, долівка. Іноді дверний отвір. Одного разу — дитяча іграшка."],
  "Pots from the tell's clay. And pots from the tell: we dig those up too, sometimes whole. They hold water better than mine.": ["丘の粘土で作った壺。それから丘から出た壺。そっちも掘り出すの、ときどき欠けずにね。私のよりよく水が漏れないのよ。", "언덕 흙으로 빚은 그릇. 그리고 언덕에서 나온 그릇. 그것도 파내요, 가끔은 멀쩡하게. 내 것보다 물을 더 잘 담아요.", "土丘泥做的罐子。还有从土丘里出来的罐子:那些我们也挖得到,有时还是完整的。它们比我做的更能盛水。", "土丘泥做的罐子。還有從土丘裡出來的罐子:那些我們也挖得到,有時還是完整的。它們比我做的更能盛水。", "Bình làm từ đất sét của gò. Và bình từ trong gò: chúng tôi cũng đào được, đôi khi còn nguyên. Chúng giữ nước tốt hơn bình của tôi.", "Tembikar dari tanah liat gundukan. Dan tembikar dari gundukan: kami juga menggalinya, kadang utuh. Lebih kedap air daripada buatanku.", "หม้อจากดินเหนียวของเนิน และหม้อจากในเนิน เราขุดพวกนั้นขึ้นมาด้วย บางทีก็ยังสมบูรณ์ มันเก็บน้ำได้ดีกว่าของฉัน", "Höyüğün kilinden çömlekler. Bir de höyükten çıkan çömlekler: onları da kazıp çıkarıyoruz, bazen bütün olarak. Suyu benimkilerden iyi tutarlar.", "Vasijas del barro del montículo. Y vasijas del montículo: también las desenterramos, a veces enteras. Retienen el agua mejor que las mías.", "Potes do barro do monte. E potes do monte: também os desenterramos, às vezes inteiros. Seguram a água melhor que os meus.", "Горшки из глины холма. И горшки из холма: их мы тоже выкапываем, иногда целыми. Воду они держат лучше моих.", "Горщики з глини пагорба. І горщики з пагорба: їх ми теж викопуємо, іноді цілими. Воду вони тримають краще за мої."],
  "Dig, basket, carry, tip. Every basket's a year, the recorder says. I've carried a hundred years this morning.": ["掘って、籠に入れて、運んで、捨てる。籠ひとつが一年だって記録官は言う。今朝だけで百年運んだよ。", "파고, 바구니에 담고, 나르고, 쏟고. 바구니 하나가 일 년이래, 기록관 말로는. 오늘 아침에만 백 년을 날랐지.", "挖、装篮、搬、倒。记录官说,一篮就是一年。今天早上我已经搬了一百年。", "挖、裝籃、搬、倒。記錄官說,一籃就是一年。今天早上我已經搬了一百年。", "Đào, cho vào giỏ, khiêng, đổ. Mỗi giỏ là một năm, người ghi chép nói. Sáng nay tôi đã khiêng một trăm năm.", "Gali, keranjang, angkut, tuang. Setiap keranjang setahun, kata si pencatat. Pagi ini aku sudah mengangkut seratus tahun.", "ขุด ใส่ตะกร้า แบก เท ผู้บันทึกว่าตะกร้าหนึ่งคือหนึ่งปี เช้านี้ผมแบกไปแล้วร้อยปี", "Kaz, sepete koy, taşı, boşalt. Her sepet bir yıl, diyor kayıtçı. Bu sabah yüz yıl taşıdım.", "Cavar, cesta, cargar, vaciar. Cada cesta es un año, dice la registradora. Esta mañana he cargado cien años.", "Cavar, cesto, carregar, despejar. Cada cesto é um ano, diz a registradora. Esta manhã carreguei cem anos.", "Копай, в корзину, неси, высыпай. Каждая корзина — год, говорит летописица. Этим утром я перетаскал сто лет.", "Копай, у кошик, неси, висипай. Кожен кошик — рік, каже літописиця. Цього ранку я перетягав сто років."],
  "Found a hearth yesterday. Ash still black in it. Somebody cooked there before Khetmar had a wall.": ["昨日、炉を見つけたんだ。灰がまだ黒かった。ケトマルに城壁ができる前に、誰かがそこで料理してたんだな。", "어제 화덕을 찾았어. 재가 아직 검더라. 케트마르에 성벽이 생기기도 전에 누군가 거기서 밥을 했던 거지.", "昨天挖到一个灶台,里面的灰还是黑的。在克特马尔有城墙之前,就有人在那儿做过饭。", "昨天挖到一個灶台,裡面的灰還是黑的。在克特馬爾有城牆之前,就有人在那兒做過飯。", "Hôm qua tìm thấy một cái bếp. Tro trong đó vẫn đen. Ai đó đã nấu ăn ở đấy trước khi Khetmar có tường thành.", "Kemarin menemukan tungku. Abunya masih hitam. Seseorang memasak di situ sebelum Khetmar punya tembok.", "เมื่อวานเจอเตาไฟ เถ้ายังดำอยู่ มีใครสักคนทำอาหารที่นั่นก่อนเคทมาร์จะมีกำแพง", "Dün bir ocak bulduk. İçindeki kül hâlâ kara. Khetmar'ın surları olmadan önce biri orada yemek pişirmiş.", "Ayer encontré un hogar. La ceniza aún negra. Alguien cocinó ahí antes de que Khetmar tuviera muralla.", "Ontem achei uma lareira. A cinza ainda preta. Alguém cozinhou ali antes de Khetmar ter muralha.", "Вчера нашёл очаг. Пепел в нём ещё чёрный. Кто-то стряпал там, когда у Кетмара ещё не было стены.", "Учора знайшов вогнище. Попіл у ньому ще чорний. Хтось куховарив там, коли в Кетмара ще не було стіни."],
  "My house is new bricks from old clay. My grandmother's house is under it. Her grandmother's is under hers.": ["私の家は古い粘土の新しい煉瓦。その下に祖母の家があって、祖母の家の下にはそのまた祖母の家がある。", "우리 집은 오래된 흙으로 만든 새 벽돌이야. 그 아래 할머니 집이 있고, 할머니 집 아래 할머니의 할머니 집이 있어.", "我的房子是用老泥做的新砖。下面是我祖母的房子。她的房子下面是她祖母的。", "我的房子是用老泥做的新磚。下面是我祖母的房子。她的房子下面是她祖母的。", "Nhà tôi là gạch mới từ đất sét cũ. Nhà bà tôi nằm bên dưới. Nhà bà của bà nằm dưới nhà bà.", "Rumahku bata baru dari tanah liat lama. Rumah nenekku di bawahnya. Rumah neneknya di bawah rumahnya.", "บ้านฉันคืออิฐใหม่จากดินเก่า บ้านยายฉันอยู่ข้างใต้ บ้านยายของยายอยู่ใต้บ้านยาย", "Evim eski kilden yeni tuğlalar. Ninemin evi altında. Onun ninesininki de onunkinin altında.", "Mi casa es ladrillo nuevo de barro viejo. La de mi abuela está debajo. La de su abuela, debajo de la suya.", "Minha casa é tijolo novo de barro velho. A da minha avó está embaixo. A da avó dela, embaixo da dela.", "Мой дом — новые кирпичи из старой глины. Под ним дом моей бабушки. Под её домом — дом её бабушки.", "Моя хата — нова цегла зі старої глини. Під нею хата моєї бабусі. Під її хатою — хата її бабусі."],
  "The Legacy's woman writes everything down. She's very polite about the digging. Very.": ["遺統のあの女の人はなんでも書き留める。掘ることについてはとても礼儀正しいよ。とってもね。", "유산에서 온 그 여자는 뭐든 적어. 파는 일에 대해선 아주 공손해. 아주.", "遗脉来的那个女人什么都记下来。她对挖土的事非常客气。非常。", "遺脈來的那個女人什麼都記下來。她對挖土的事非常客氣。非常。", "Người đàn bà của Di Sản ghi lại mọi thứ. Bà ấy rất lịch sự về chuyện đào bới. Rất.", "Perempuan dari Warisan itu mencatat segalanya. Ia sangat sopan soal penggalian. Sangat.", "ผู้หญิงจากมรดกจดทุกอย่าง เธอสุภาพมากเรื่องการขุด มากจริงๆ", "Miras'ın kadını her şeyi yazıyor. Kazı konusunda çok kibar. Çok.", "La mujer del Legado lo apunta todo. Es muy educada con lo de cavar. Mucho.", "A mulher do Legado anota tudo. É muito educada quanto à escavação. Muito.", "Женщина из Наследия всё записывает. Она очень вежлива насчёт раскопок. Очень.", "Жінка зі Спадщини все записує. Вона дуже чемна щодо розкопок. Дуже."],
  "One notch a day for every share. The village, the gardens, the caravans. The notches are the same; the water isn't.": ["取り分ごとに一日一刻み。村、畑、隊商。刻みは同じでも、水は同じじゃない。", "몫마다 하루에 한 눈금. 마을, 밭, 대상. 눈금은 같은데, 물은 같지 않아요.", "每份一天刻一道。村子、园子、商队。刻痕一样,水却不一样了。", "每份一天刻一道。村子、園子、商隊。刻痕一樣,水卻不一樣了。", "Mỗi phần một vết khắc mỗi ngày. Làng, vườn, đoàn lữ hành. Vết khắc vẫn vậy; nước thì không.", "Satu takik sehari untuk setiap jatah. Desa, kebun, kafilah. Takiknya sama; airnya tidak.", "หนึ่งรอยต่อวันต่อส่วนแบ่ง หมู่บ้าน สวน กองคาราวาน รอยขีดเหมือนเดิม น้ำไม่เหมือนเดิม", "Her pay için günde bir çentik. Köy, bahçeler, kervanlar. Çentikler aynı; su değil.", "Una muesca al día por cada parte. La aldea, los huertos, las caravanas. Las muescas son las mismas; el agua no.", "Um entalhe por dia para cada parte. A aldeia, os pomares, as caravanas. Os entalhes são os mesmos; a água, não.", "По зарубке в день на каждую долю. Деревня, сады, караваны. Зарубки те же, а вода — нет.", "По зарубці на день на кожну частку. Село, сади, каравани. Зарубки ті самі, а вода — ні."],
  "Ennu dug this well when there was no village, only Ennu and thirst. We've kept it since. We've never kept it so low.": ["エンヌがこの井戸を掘ったとき、村はなかった。エンヌと渇きだけ。それからずっと守ってきたけど、こんなに低くなったことはない。", "엔누가 이 우물을 팠을 때는 마을이 없었어요. 엔누와 목마름뿐이었죠. 그 뒤로 쭉 지켜 왔지만, 이렇게 낮은 적은 없었어요.", "恩努挖这口井的时候还没有村子,只有恩努和口渴。从那以后我们一直守着它。从没守得这么低过。", "恩努挖這口井的時候還沒有村子,只有恩努和口渴。從那以後我們一直守著它。從沒守得這麼低過。", "Ennu đào giếng này khi chưa có làng, chỉ có Ennu và cơn khát. Từ đó chúng tôi giữ nó. Chưa bao giờ giữ nó thấp thế này.", "Ennu menggali sumur ini saat belum ada desa, hanya Ennu dan dahaga. Sejak itu kami menjaganya. Belum pernah serendah ini.", "เอนนูขุดบ่อนี้ตอนที่ยังไม่มีหมู่บ้าน มีแค่เอนนูกับความกระหาย เราดูแลมันมาตั้งแต่นั้น ไม่เคยต่ำขนาดนี้", "Ennu bu kuyuyu kazdığında köy yoktu, yalnızca Ennu ve susuzluk. O günden beri koruyoruz. Hiç bu kadar düşük tutmadık.", "Ennu cavó este pozo cuando no había aldea, solo Ennu y la sed. Lo hemos guardado desde entonces. Nunca lo habíamos tenido tan bajo.", "Ennu cavou este poço quando não havia aldeia, só Ennu e a sede. Nós o guardamos desde então. Nunca esteve tão baixo.", "Энну выкопал этот колодец, когда не было деревни, только Энну и жажда. С тех пор мы его храним. Никогда он не был так низок.", "Енну викопав цю криницю, коли не було села, лише Енну й спрага. Відтоді ми її бережемо. Ніколи вона не була така низька."],
  "Forty camels, twenty years, and Ennu's water every crossing. We pay. We've always paid. A well isn't a well if you can't drink from it.": ["ラクダ四十頭、二十年、そして渡るたびにエンヌの水。俺たちは払う。いつも払ってきた。飲めない井戸なんて井戸じゃない。", "낙타 마흔 마리, 이십 년, 그리고 건널 때마다 엔누의 물. 우린 내. 늘 내 왔어. 마실 수 없는 우물은 우물이 아니야.", "四十峰骆驼,二十年,每趟都喝恩努的水。我们付钱。一直都付。喝不上的井就不算井。", "四十峰駱駝,二十年,每趟都喝恩努的水。我們付錢。一直都付。喝不上的井就不算井。", "Bốn mươi con lạc đà, hai mươi năm, và nước Ennu mỗi chuyến. Chúng tôi trả tiền. Luôn trả. Giếng mà không uống được thì không phải giếng.", "Empat puluh unta, dua puluh tahun, dan air Ennu setiap penyeberangan. Kami membayar. Selalu membayar. Sumur bukan sumur kalau tak bisa diminum.", "อูฐสี่สิบตัว ยี่สิบปี และน้ำของเอนนูทุกเที่ยว เราจ่าย เราจ่ายเสมอ บ่อที่ดื่มไม่ได้ก็ไม่ใช่บ่อ", "Kırk deve, yirmi yıl ve her geçişte Ennu'nun suyu. Öderiz. Hep ödedik. İçemediğin kuyu kuyu değildir.", "Cuarenta camellos, veinte años, y el agua de Ennu en cada travesía. Pagamos. Siempre hemos pagado. Un pozo no es un pozo si no se puede beber de él.", "Quarenta camelos, vinte anos, e a água de Ennu em cada travessia. Pagamos. Sempre pagamos. Um poço não é poço se não se pode beber dele.", "Сорок верблюдов, двадцать лет и вода Энну на каждом переходе. Мы платим. Всегда платили. Колодец не колодец, если из него нельзя пить.", "Сорок верблюдів, двадцять років і вода Енну на кожному переході. Ми платимо. Завжди платили. Криниця не криниця, якщо з неї не можна пити."],
  "Merrab to the steppe is nine days without Ennu's Well. Nine days is a long way to be thirsty.": ["エンヌの井戸がなければ、メラブから草原まで九日。九日も渇いているのは長いぞ。", "엔누의 우물이 없으면 메라브에서 초원까지 아흐레야. 아흐레 동안 목마른 건 긴 여정이지.", "没有恩努井,从梅拉布到草原要九天。九天渴着,路可长了。", "沒有恩努井,從梅拉布到草原要九天。九天渴著,路可長了。", "Không có Giếng Ennu, từ Merrab tới thảo nguyên là chín ngày. Chín ngày là chặng dài để chịu khát.", "Merrab ke padang rumput sembilan hari tanpa Sumur Ennu. Sembilan hari itu panjang untuk menahan haus.", "จากเมอร์รับไปทุ่งหญ้าคือเก้าวันถ้าไม่มีบ่อน้ำเอนนู เก้าวันเป็นทางไกลที่จะต้องกระหาย", "Ennu Kuyusu olmadan Merrab'dan bozkıra dokuz gün. Dokuz gün susuz kalmak için uzun bir yol.", "De Merrab a la estepa son nueve días sin el Pozo de Ennu. Nueve días es mucho camino con sed.", "De Merrab à estepe são nove dias sem o Poço de Ennu. Nove dias é muito caminho com sede.", "От Мерраба до степи девять дней без Колодца Энну. Девять дней — долгий путь для жажды.", "Від Меррабу до степу дев'ять днів без Криниці Енну. Дев'ять днів — довга дорога для спраги."],
  "The palms drink first, or they don't fruit. No dates, no trade; no trade, no village. Palms are very persuasive.": ["ヤシがまず飲まないと実がならない。ナツメヤシがなければ商いはない。商いがなければ村もない。ヤシってのは口がうまいんだ。", "야자나무가 먼저 마셔야 열매가 열려. 대추야자가 없으면 장사도 없고, 장사가 없으면 마을도 없지. 야자나무는 설득력이 대단해.", "棕榈得先喝,不然不结果。没有椰枣就没有买卖;没有买卖就没有村子。棕榈可会说服人了。", "棕櫚得先喝,不然不結果。沒有椰棗就沒有買賣;沒有買賣就沒有村子。棕櫚可會說服人了。", "Cây cọ uống trước, không thì không ra quả. Không chà là, không buôn bán; không buôn bán, không có làng. Cây cọ rất biết thuyết phục.", "Palem minum dulu, atau tak berbuah. Tanpa kurma, tak ada dagang; tanpa dagang, tak ada desa. Palem sangat pandai membujuk.", "ต้นปาล์มต้องดื่มก่อน ไม่อย่างนั้นไม่ออกผล ไม่มีอินทผลัมก็ไม่มีการค้า ไม่มีการค้าก็ไม่มีหมู่บ้าน ต้นปาล์มโน้มน้าวเก่งมาก", "Önce hurmalar içer, yoksa meyve vermezler. Hurma yoksa ticaret yok; ticaret yoksa köy yok. Hurmalar çok ikna edicidir.", "Las palmeras beben primero, o no dan fruto. Sin dátiles no hay comercio; sin comercio no hay aldea. Las palmeras saben convencer.", "As palmeiras bebem primeiro, ou não dão fruto. Sem tâmaras, sem comércio; sem comércio, sem aldeia. Palmeiras são muito persuasivas.", "Пальмы пьют первыми, иначе не плодоносят. Нет фиников — нет торговли; нет торговли — нет деревни. Пальмы очень убедительны.", "Пальми п'ють першими, інакше не родять. Нема фініків — нема торгівлі; нема торгівлі — нема села. Пальми дуже переконливі."],
  "The water's lower every week. The old channel from the hills is half dry, and the sand's getting into it from somewhere.": ["水は毎週低くなる。丘から来る古い水路は半分干上がってて、どこからか砂が入りこんでるんだ。", "물이 주마다 낮아져. 언덕에서 오는 옛 수로가 반쯤 말랐고, 어디선가 모래가 들어오고 있어.", "水一周比一周低。从山上来的老水渠干了一半,沙子不知从哪儿钻了进去。", "水一週比一週低。從山上來的老水渠乾了一半,沙子不知從哪兒鑽了進去。", "Nước mỗi tuần một thấp. Con kênh cũ từ đồi đã khô một nửa, và cát đang lọt vào từ đâu đó.", "Airnya makin rendah tiap minggu. Saluran tua dari perbukitan setengah kering, dan pasir masuk dari suatu tempat.", "น้ำต่ำลงทุกสัปดาห์ รางน้ำเก่าจากเนินเขาแห้งไปครึ่งหนึ่ง และทรายก็เข้ามาจากที่ไหนสักแห่ง", "Su her hafta daha alçak. Tepelerden gelen eski kanal yarı kuru ve bir yerden içine kum giriyor.", "El agua baja cada semana. El viejo canal de las colinas está medio seco, y la arena se le mete por algún sitio.", "A água está mais baixa a cada semana. O velho canal das colinas está meio seco, e a areia está entrando por algum lugar.", "Вода с каждой неделей ниже. Старый канал с холмов наполовину пересох, и откуда-то в него набивается песок.", "Вода з кожним тижнем нижча. Старий канал із пагорбів наполовину пересох, і звідкись у нього набивається пісок."],
  "Dates, bread, a skin of water. The water's free. The skin is very expensive.": ["ナツメヤシ、パン、水袋ひとつ。水はただ。袋はとても高いよ。", "대추야자, 빵, 물주머니 하나. 물은 공짜예요. 주머니는 아주 비싸고요.", "椰枣、面包、一袋水。水不要钱。袋子很贵。", "椰棗、麵包、一袋水。水不要錢。袋子很貴。", "Chà là, bánh mì, một túi nước. Nước miễn phí. Cái túi thì rất đắt.", "Kurma, roti, sekantong air. Airnya gratis. Kantongnya sangat mahal.", "อินทผลัม ขนมปัง ถุงน้ำหนึ่งใบ น้ำฟรี ถุงแพงมาก", "Hurma, ekmek, bir tulum su. Su bedava. Tulum çok pahalı.", "Dátiles, pan, un odre de agua. El agua es gratis. El odre es carísimo.", "Tâmaras, pão, um odre de água. A água é de graça. O odre é caríssimo.", "Финики, хлеб, бурдюк воды. Вода бесплатно. Бурдюк очень дорогой.", "Фініки, хліб, бурдюк води. Вода безкоштовно. Бурдюк дуже дорогий."],
  "That one bites. That one spits. That one's mine, and does both.": ["あいつは噛む。あいつは唾を吐く。あいつは俺のやつで、両方やる。", "저놈은 물고, 저놈은 침 뱉고. 저놈은 내 거고, 둘 다 해.", "那头咬人。那头吐口水。那头是我的,两样都干。", "那頭咬人。那頭吐口水。那頭是我的,兩樣都幹。", "Con đó cắn. Con kia nhổ. Con kia là của tôi, và làm cả hai.", "Yang itu menggigit. Yang itu meludah. Yang itu punyaku, dan melakukan keduanya.", "ตัวนั้นกัด ตัวนั้นถ่มน้ำลาย ตัวนั้นของผม ทำทั้งสองอย่าง", "O ısırır. O tükürür. O benimki, ikisini de yapar.", "Ese muerde. Ese escupe. Ese es mío, y hace las dos cosas.", "Aquele morde. Aquele cospe. Aquele é meu, e faz as duas coisas.", "Этот кусается. Этот плюётся. А этот мой — и то и другое.", "Цей кусається. Цей плюється. А цей мій — і те, і те."],
  "Camels can go a week without water. They don't like to, and they tell you about it the whole week.": ["ラクダは一週間水なしでいける。好きじゃないし、その一週間ずっと文句を言われるがね。", "낙타는 일주일을 물 없이 버틸 수 있어. 싫어하고, 그 일주일 내내 투덜대지만.", "骆驼能一个礼拜不喝水。它们不乐意,还会整整一个礼拜跟你念叨。", "駱駝能一個禮拜不喝水。牠們不樂意,還會整整一個禮拜跟你唸叨。", "Lạc đà nhịn nước được một tuần. Chúng không thích, và kể lể với anh suốt cả tuần.", "Unta bisa seminggu tanpa air. Mereka tak suka, dan mengeluhkannya seminggu penuh.", "อูฐอยู่ได้หนึ่งสัปดาห์โดยไม่มีน้ำ มันไม่ชอบ และบ่นให้คุณฟังตลอดทั้งสัปดาห์", "Develer bir hafta susuz kalabilir. Sevmezler ve bütün hafta boyunca bunu sana anlatırlar.", "Los camellos aguantan una semana sin agua. No les gusta, y te lo cuentan toda la semana.", "Camelos aguentam uma semana sem água. Não gostam, e falam disso a semana inteira.", "Верблюды могут неделю обходиться без воды. Им это не нравится, и всю неделю они тебе об этом сообщают.", "Верблюди можуть тиждень обходитися без води. Їм це не подобається, і цілий тиждень вони тобі про це повідомляють."],
  "Village first, gardens second, caravans third. That's the old measure. The caravans don't like being third.": ["村が一番、畑が二番、隊商が三番。それが昔からの決まり。隊商は三番目が気に入らないの。", "마을이 첫째, 밭이 둘째, 대상이 셋째. 그게 옛날 셈법이에요. 대상은 셋째인 게 싫대요.", "村子第一,园子第二,商队第三。这是老规矩。商队不喜欢排第三。", "村子第一,園子第二,商隊第三。這是老規矩。商隊不喜歡排第三。", "Làng trước, vườn thứ hai, đoàn lữ hành thứ ba. Đó là lệ cũ. Đoàn lữ hành không thích đứng thứ ba.", "Desa pertama, kebun kedua, kafilah ketiga. Itu takaran lama. Kafilah tak suka jadi yang ketiga.", "หมู่บ้านก่อน สวนอันดับสอง กองคาราวานอันดับสาม นั่นคือเกณฑ์เก่า กองคาราวานไม่ชอบเป็นอันดับสาม", "Önce köy, ikinci bahçeler, üçüncü kervanlar. Eski ölçü budur. Kervanlar üçüncü olmayı sevmez.", "Primero la aldea, segundo los huertos, tercero las caravanas. Esa es la medida antigua. A las caravanas no les gusta ser terceras.", "Primeiro a aldeia, segundo os pomares, terceiro as caravanas. É a medida antiga. As caravanas não gostam de ser terceiras.", "Сперва деревня, потом сады, потом караваны. Таков старый порядок. Караванам не нравится быть третьими.", "Спершу село, потім сади, потім каравани. Такий старий порядок. Караванам не подобається бути третіми."],
  "The pool used to come up to that palm. Now look.": ["池は前はあのヤシのところまであったんだ。今を見てごらん。", "연못이 예전엔 저 야자나무까지 차올랐어요. 지금 좀 봐요.", "以前池水能漫到那棵棕榈。现在你看看。", "以前池水能漫到那棵棕櫚。現在你看看。", "Hồ nước trước kia dâng tới cây cọ kia. Giờ nhìn xem.", "Kolam dulu sampai ke pohon palem itu. Sekarang lihat.", "สระเคยสูงถึงต้นปาล์มต้นนั้น ตอนนี้ดูสิ", "Havuz eskiden şu hurmaya kadar gelirdi. Şimdi bak.", "La poza llegaba antes hasta esa palmera. Mira ahora.", "O lago chegava até aquela palmeira. Agora olhe.", "Пруд раньше доходил до той пальмы. А теперь посмотри.", "Ставок раніше сягав до тієї пальми. А тепер подивися."],
  "The Zuri camp here in the dry months. We dress like them; they drink like us.": ["乾季にはズーリがここで野営する。私たちはあの人たちのように装い、あの人たちは私たちのように飲む。", "건기엔 주리 사람들이 여기 야영해요. 우린 그들처럼 입고, 그들은 우리처럼 마시죠.", "旱季时祖里人在这儿扎营。我们穿得像他们,他们喝得像我们。", "旱季時祖里人在這兒紮營。我們穿得像他們,他們喝得像我們。", "Người Zuri cắm trại ở đây vào mùa khô. Chúng tôi ăn mặc giống họ; họ uống nước giống chúng tôi.", "Orang Zuri berkemah di sini pada bulan-bulan kering. Kami berpakaian seperti mereka; mereka minum seperti kami.", "ชาวซูรีมาตั้งค่ายที่นี่ในเดือนแล้ง เราแต่งตัวเหมือนพวกเขา พวกเขาดื่มเหมือนเรา", "Kurak aylarda Zuriler burada kamp kurar. Biz onlar gibi giyiniriz; onlar bizim gibi içer.", "Los zuri acampan aquí en los meses secos. Nosotros vestimos como ellos; ellos beben como nosotros.", "Os zuri acampam aqui nos meses secos. Nós nos vestimos como eles; eles bebem como nós.", "В сухие месяцы здесь стоят зури. Мы одеваемся, как они; они пьют, как мы.", "У сухі місяці тут стоять зурі. Ми вдягаємося, як вони; вони п'ють, як ми."],
  "Talk to Harbourmaster Wenna Coyle in her office on Gullwick's harbour street.": ["ガルウィックの港通りにある事務所で港長ウェナ・コイルに話しかける。", "걸윅 항구 거리의 사무소에서 항만장 웨나 코일에게 말을 건다.", "在鸥湾港口街的办公处和港务长温娜·科伊尔谈话。", "在鷗灣港口街的辦公處和港務長溫娜·科伊爾談話。", "Nói chuyện với Trưởng cảng Wenna Coyle tại văn phòng của bà trên phố cảng Gullwick.", "Bicaralah dengan Syahbandar Wenna Coyle di kantornya di jalan pelabuhan Gullwick.", "คุยกับนายท่าเวนนา คอยล์ที่สำนักงานของเธอบนถนนท่าเรือกัลวิก", "Gullwick'in liman caddesindeki ofisinde Liman Reisi Wenna Coyle ile konuş.", "Habla con la capitana de puerto Wenna Coyle en su oficina de la calle del puerto de Gullwick.", "Fale com a capitã do porto Wenna Coyle no escritório dela, na rua do porto de Gullwick.", "Поговорите с начальницей порта Венной Койл в её конторе на портовой улице Галлвика.", "Поговоріть із начальницею порту Венною Койл у її конторі на портовій вулиці Галлвіка."],
  "Gullwick's harbourmaster is looking at the lighthouse as if it had insulted her.": ["ガルウィックの港長が、侮辱でもされたかのように灯台をにらんでいる。", "걸윅의 항만장이 등대가 자기를 모욕하기라도 한 듯 쳐다보고 있다.", "鸥湾的港务长盯着灯塔,好像灯塔得罪了她。", "鷗灣的港務長盯著燈塔,好像燈塔得罪了她。", "Trưởng cảng Gullwick đang nhìn ngọn hải đăng như thể nó vừa xúc phạm bà.", "Syahbandar Gullwick memandangi mercusuar seolah mercusuar itu menghinanya.", "นายท่าแห่งกัลวิกจ้องประภาคารราวกับมันดูหมิ่นเธอ", "Gullwick'in liman reisi feneri, sanki ona hakaret etmiş gibi süzüyor.", "La capitana de puerto de Gullwick mira el faro como si la hubiera insultado.", "A capitã do porto de Gullwick olha para o farol como se ele a tivesse insultado.", "Начальница порта Галлвика смотрит на маяк так, будто он её оскорбил.", "Начальниця порту Галлвіка дивиться на маяк так, ніби він її образив."],
  "Gullwick Light has gone dark three nights this month, and two boats nearly went onto the rocks off Wrack Point. Harbourmaster Wenna Coyle wants to know why.": ["ガルウィック灯台は今月三晩消え、二隻の船がレック岬沖の岩にあやうく乗り上げるところだった。港長ウェナ・コイルはその理由を知りたがっている。", "걸윅 등대가 이번 달에 세 밤이나 꺼졌고, 배 두 척이 렉 곶 앞바다 바위에 걸릴 뻔했다. 항만장 웨나 코일은 그 이유를 알고 싶어 한다.", "鸥湾灯塔这个月黑了三个晚上,两条船差点撞上残骸岬外的礁石。港务长温娜·科伊尔想知道为什么。", "鷗灣燈塔這個月黑了三個晚上,兩條船差點撞上殘骸岬外的礁石。港務長溫娜·科伊爾想知道為什麼。", "Đèn biển Gullwick đã tắt ba đêm trong tháng này, và hai chiếc thuyền suýt đâm vào đá ngoài mũi Wrack. Trưởng cảng Wenna Coyle muốn biết tại sao.", "Mercusuar Gullwick padam tiga malam bulan ini, dan dua perahu nyaris menabrak karang di lepas Tanjung Wrack. Syahbandar Wenna Coyle ingin tahu sebabnya.", "ประภาคารกัลวิกดับไปสามคืนในเดือนนี้ และเรือสองลำเกือบชนโขดหินนอกแหลมแร็ก นายท่าเวนนา คอยล์อยากรู้ว่าทำไม", "Gullwick Feneri bu ay üç gece karanlık kaldı ve iki tekne Wrack Burnu açığındaki kayalara az kalsın oturuyordu. Liman Reisi Wenna Coyle nedenini bilmek istiyor.", "El faro de Gullwick se ha apagado tres noches este mes, y dos barcas casi dan en las rocas de la Punta Wrack. La capitana de puerto Wenna Coyle quiere saber por qué.", "O farol de Gullwick se apagou três noites este mês, e dois barcos quase foram parar nas rochas da Ponta Wrack. A capitã do porto Wenna Coyle quer saber por quê.", "Галлвикский маяк гас три ночи в этом месяце, и две лодки едва не налетели на скалы у мыса Рэк. Начальница порта Венна Койл хочет знать почему.", "Галлвіцький маяк гаснув три ночі цього місяця, і два човни мало не наскочили на скелі біля мису Рек. Начальниця порту Венна Койл хоче знати чому."],
  "Somebody waters the Light's oil on the nights a paid-up cargo boat is due, and a light shows on Wrack Point where no light should be.": ["税を払い済みの貨物船が来る夜に、誰かが灯台の油を水で薄めている。そしてレック岬の、灯があるはずのない場所に灯が見える。", "세금을 다 낸 화물선이 오는 밤마다 누군가 등대 기름에 물을 탄다. 그리고 렉 곶의, 불빛이 있어서는 안 될 곳에 불빛이 보인다.", "每逢缴清税费的货船要到的夜里,就有人往灯塔的油里掺水;而残骸岬上本不该有光的地方,亮起了一盏灯。", "每逢繳清稅費的貨船要到的夜裡,就有人往燈塔的油裡摻水;而殘骸岬上本不該有光的地方,亮起了一盞燈。", "Có kẻ pha nước vào dầu của Đèn vào những đêm có thuyền hàng đã đóng đủ thuế sắp tới, và một ánh đèn hiện lên trên mũi Wrack, nơi không nên có đèn.", "Seseorang mencampur air ke minyak Mercusuar pada malam-malam ketika kapal muatan yang sudah lunas bea akan tiba, dan sebuah cahaya muncul di Tanjung Wrack, tempat yang tak semestinya ada cahaya.", "มีใครบางคนผสมน้ำลงในน้ำมันของประภาคารในคืนที่เรือสินค้าที่จ่ายค่าธรรมเนียมแล้วจะมาถึง และมีแสงไฟปรากฏบนแหลมแร็กในที่ที่ไม่ควรมีแสง", "Vergisini ödemiş bir yük teknesinin geleceği gecelerde biri fenerin yağına su katıyor ve Wrack Burnu'nda ışık olmaması gereken yerde bir ışık görünüyor.", "Alguien agua el aceite del faro las noches en que llega un barco de carga con los derechos pagados, y una luz aparece en la Punta Wrack donde no debería haber ninguna.", "Alguém põe água no óleo do farol nas noites em que um barco de carga com as taxas pagas deve chegar, e uma luz aparece na Ponta Wrack onde não deveria haver luz.", "Кто-то разбавляет водой масло маяка в те ночи, когда ждут грузовую лодку с уплаченными сборами, а на мысе Рэк загорается огонь там, где огня быть не должно.", "Хтось розбавляє водою олію маяка в ті ночі, коли чекають вантажний човен зі сплаченими зборами, а на мисі Рек спалахує вогонь там, де вогню бути не повинно."],
  "A false lantern on Wrack Point, burning the Light's own oil, tied to its pole with a gansey sleeve in the Tregellas pattern. Wreckers.": ["レック岬の偽のランタン。灯台の油を燃やし、トレゲラス家の模様のガンジーの袖で竿に結ばれている。難破させ屋だ。", "렉 곶의 가짜 등불. 등대의 기름을 태우고, 트레겔라스 무늬 건지 소매로 장대에 묶여 있다. 난파꾼들이다.", "残骸岬上的假灯笼,烧的是灯塔自己的油,用一只特雷盖拉斯家花纹的毛衣袖子绑在杆上。诱船贼。", "殘骸岬上的假燈籠,燒的是燈塔自己的油,用一隻特雷蓋拉斯家花紋的毛衣袖子綁在桿上。誘船賊。", "Một chiếc đèn lồng giả trên mũi Wrack, đốt chính dầu của ngọn Đèn, buộc vào cột bằng ống tay áo gansey hoa văn nhà Tregellas. Bọn làm đắm tàu.", "Lentera palsu di Tanjung Wrack, membakar minyak Mercusuar sendiri, diikat ke tiangnya dengan lengan sweter gansey berpola Tregellas. Penjarah kapal karam.", "ตะเกียงปลอมบนแหลมแร็ก เผาน้ำมันของประภาคารเอง ผูกกับเสาด้วยแขนเสื้อแกนซีลายตระกูลเทรเกลลัส พวกโจรล่อเรือแตก", "Wrack Burnu'nda sahte bir fener; fenerin kendi yağını yakıyor, direğine Tregellas desenli bir gansey koluyla bağlanmış. Gemi batırıcılar.", "Un farol falso en la Punta Wrack, que quema el aceite del propio faro, atado a su poste con una manga de gansey con el dibujo de los Tregellas. Raqueros.", "Uma lanterna falsa na Ponta Wrack, queimando o próprio óleo do farol, amarrada ao poste com uma manga de gansey no padrão dos Tregellas. Saqueadores de naufrágios.", "Ложный фонарь на мысе Рэк, жжёт масло самого маяка, привязан к шесту рукавом гернси с узором Трегелласов. Береговые мародёры.", "Фальшивий ліхтар на мисі Рек, палить олію самого маяка, прив'язаний до жердини рукавом гернсі з візерунком Трегелласів. Берегові мародери."],
  "Deal with the wreckers' chief on Wrack Point, or ask Nan Tregellas, by the quay, about the pattern": ["レック岬で難破させ屋の頭を片づけるか、岸壁そばのナン・トレゲラスに模様のことを尋ねる", "렉 곶에서 난파꾼 두목을 처리하거나, 부두 옆의 낸 트레겔라스에게 무늬에 대해 묻는다", "去残骸岬对付诱船贼的头目,或者到码头边问问南·特雷盖拉斯那花纹的事", "去殘骸岬對付誘船賊的頭目,或者到碼頭邊問問南·特雷蓋拉斯那花紋的事", "Xử lý tên cầm đầu bọn làm đắm tàu trên mũi Wrack, hoặc hỏi Nan Tregellas, cạnh bến, về hoa văn", "Bereskan kepala para penjarah di Tanjung Wrack, atau tanyakan pada Nan Tregellas, dekat dermaga, soal polanya", "จัดการหัวหน้าโจรล่อเรือแตกบนแหลมแร็ก หรือถามแนน เทรเกลลัสที่ริมท่าเรือเรื่องลวดลาย", "Wrack Burnu'ndaki batırıcıların reisinin hakkından gel ya da rıhtım yanındaki Nan Tregellas'a deseni sor", "Encárgate del jefe de los raqueros en la Punta Wrack, o pregunta a Nan Tregellas, junto al muelle, por el dibujo", "Dê um jeito no chefe dos saqueadores na Ponta Wrack, ou pergunte a Nan Tregellas, junto ao cais, sobre o padrão", "Разберитесь с главарём мародёров на мысе Рэк или спросите Нэн Трегеллас у причала об узоре", "Розберіться з ватажком мародерів на мисі Рек або спитайте Нен Трегеллас біля причалу про візерунок"],
  "Nan Tregellas says the wreckers are fishers the new dues ruined, her son Kit among them, and that she will call him off.": ["ナン・トレゲラスによれば、難破させ屋たちは新しい税で身を持ち崩した漁師で、息子のキットもその一人。彼女は息子をやめさせると言う。", "낸 트레겔라스는 난파꾼들이 새 세금에 망한 어부들이고, 아들 킷도 그중 하나이며, 아들을 그만두게 하겠다고 한다.", "南·特雷盖拉斯说,诱船贼都是被新税逼垮的渔民,她儿子基特也在其中,她会叫他收手。", "南·特雷蓋拉斯說,誘船賊都是被新稅逼垮的漁民,她兒子基特也在其中,她會叫他收手。", "Nan Tregellas nói bọn làm đắm tàu là những ngư dân bị thuế mới làm cho khánh kiệt, trong đó có con trai bà, Kit, và bà sẽ bảo nó dừng tay.", "Nan Tregellas berkata para penjarah adalah nelayan yang dihancurkan bea baru, termasuk putranya Kit, dan ia akan menghentikannya.", "แนน เทรเกลลัสว่าโจรล่อเรือแตกคือชาวประมงที่ค่าธรรมเนียมใหม่ทำให้ล่มจม รวมถึงคิตลูกชายของเธอ และเธอจะเรียกเขากลับ", "Nan Tregellas, batırıcıların yeni vergilerin mahvettiği balıkçılar olduğunu, oğlu Kit'in de aralarında bulunduğunu ve onu vazgeçireceğini söylüyor.", "Nan Tregellas dice que los raqueros son pescadores arruinados por los nuevos derechos, entre ellos su hijo Kit, y que ella le hará parar.", "Nan Tregellas diz que os saqueadores são pescadores arruinados pelas novas taxas, entre eles o filho dela, Kit, e que ela vai fazê-lo parar.", "Нэн Трегеллас говорит, что мародёры — рыбаки, разорённые новыми сборами, и её сын Кит среди них, и что она его остановит.", "Нен Трегеллас каже, що мародери — рибалки, розорені новими зборами, і її син Кіт серед них, і що вона його зупинить."],
  "Kit Tregellas, the wreckers' chief, is dead, and the false lantern is out.": ["難破させ屋の頭キット・トレゲラスは死に、偽のランタンは消えた。", "난파꾼 두목 킷 트레겔라스는 죽었고, 가짜 등불은 꺼졌다.", "诱船贼的头目基特·特雷盖拉斯死了,假灯笼也灭了。", "誘船賊的頭目基特·特雷蓋拉斯死了,假燈籠也滅了。", "Kit Tregellas, tên cầm đầu bọn làm đắm tàu, đã chết, và chiếc đèn lồng giả đã tắt.", "Kit Tregellas, kepala para penjarah, sudah mati, dan lentera palsu sudah padam.", "คิต เทรเกลลัส หัวหน้าโจรล่อเรือแตกตายแล้ว และตะเกียงปลอมก็ดับแล้ว", "Batırıcıların reisi Kit Tregellas öldü ve sahte fener söndü.", "Kit Tregellas, el jefe de los raqueros, ha muerto, y el farol falso está apagado.", "Kit Tregellas, o chefe dos saqueadores, está morto, e a lanterna falsa se apagou.", "Кит Трегеллас, главарь мародёров, мёртв, и ложный фонарь погашен.", "Кіт Трегеллас, ватажок мародерів, мертвий, і фальшивий ліхтар погашено."],
  "I told the harbourmaster why the wreckers wrecked. The small boats' dues are halved, and Kit Tregellas's lantern hangs in Gullwick Light now, lit the right way round. QUEST COMPLETE!": ["難破させ屋がなぜ船を沈めたのか、港長に話した。小舟の税は半分になり、キット・トレゲラスのランタンは今ガルウィック灯台に吊るされ、正しい向きに灯っている。クエスト完了！", "난파꾼들이 왜 배를 난파시켰는지 항만장에게 말했다. 작은 배들의 세금은 절반이 되었고, 킷 트레겔라스의 등불은 이제 걸윅 등대에 걸려 제대로 된 방향으로 빛난다. 퀘스트 완료!", "我告诉港务长诱船贼为什么要诱船。小船的税减了一半,基特·特雷盖拉斯的灯笼如今挂在鸥湾灯塔里,照着正确的方向亮着。任务完成！", "我告訴港務長誘船賊為什麼要誘船。小船的稅減了一半,基特·特雷蓋拉斯的燈籠如今掛在鷗灣燈塔裡,照著正確的方向亮著。任務完成！", "Tôi đã kể với trưởng cảng vì sao bọn làm đắm tàu làm thế. Thuế của thuyền nhỏ được giảm một nửa, và chiếc đèn lồng của Kit Tregellas giờ treo trong Đèn biển Gullwick, thắp đúng hướng. HOÀN THÀNH NHIỆM VỤ!", "Kuceritakan pada syahbandar kenapa para penjarah menjarah. Bea perahu kecil dipotong separuh, dan lentera Kit Tregellas kini tergantung di Mercusuar Gullwick, menyala ke arah yang benar. MISI SELESAI!", "ฉันบอกนายท่าว่าทำไมโจรล่อเรือแตกจึงทำอย่างนั้น ค่าธรรมเนียมของเรือเล็กลดลงครึ่งหนึ่ง และตะเกียงของคิต เทรเกลลัสตอนนี้แขวนอยู่ในประภาคารกัลวิก จุดส่องถูกทาง ภารกิจสำเร็จ!", "Liman reisine batırıcıların neden gemi batırdığını anlattım. Küçük teknelerin vergileri yarıya indi ve Kit Tregellas'ın feneri şimdi Gullwick Feneri'nde, doğru yöne yanarak asılı. GÖREV TAMAMLANDI!", "Le conté a la capitana de puerto por qué los raqueros hacían naufragar barcos. Los derechos de las barcas pequeñas se reducen a la mitad, y el farol de Kit Tregellas cuelga ahora en el faro de Gullwick, encendido hacia el lado correcto. ¡MISIÓN CUMPLIDA!", "Contei à capitã do porto por que os saqueadores faziam naufrágios. As taxas dos barcos pequenos caíram pela metade, e a lanterna de Kit Tregellas agora pende no farol de Gullwick, acesa do lado certo. MISSÃO CUMPRIDA!", "Я рассказал начальнице порта, зачем мародёры топили корабли. Сборы с малых лодок уменьшены вдвое, а фонарь Кита Трегелласа теперь висит на Галлвикском маяке и светит как надо. ЗАДАНИЕ ВЫПОЛНЕНО!", "Я розповів начальниці порту, навіщо мародери топили кораблі. Збори з малих човнів зменшено вдвічі, а ліхтар Кіта Трегелласа тепер висить на Галлвіцькому маяку й світить як слід. ЗАВДАННЯ ВИКОНАНО!"],
  "The wreckers' chief is dead and Wrack Point is dark. The dues stand, and the fishers don't look at me on the quay. QUEST COMPLETE!": ["難破させ屋の頭は死に、レック岬は暗くなった。税はそのままで、漁師たちは岸壁で私と目を合わせない。クエスト完了！", "난파꾼 두목은 죽었고 렉 곶은 어두워졌다. 세금은 그대로고, 어부들은 부두에서 나를 쳐다보지 않는다. 퀘스트 완료!", "诱船贼的头目死了,残骸岬暗了下来。税还照旧,码头上的渔民都不看我。任务完成！", "誘船賊的頭目死了,殘骸岬暗了下來。稅還照舊,碼頭上的漁民都不看我。任務完成！", "Tên cầm đầu bọn làm đắm tàu đã chết và mũi Wrack đã tối. Thuế vẫn giữ nguyên, và dân chài trên bến không nhìn tôi. HOÀN THÀNH NHIỆM VỤ!", "Kepala para penjarah sudah mati dan Tanjung Wrack gelap. Bea tetap berlaku, dan para nelayan tak mau menatapku di dermaga. MISI SELESAI!", "หัวหน้าโจรล่อเรือแตกตายแล้ว และแหลมแร็กก็มืด ค่าธรรมเนียมยังคงเดิม และชาวประมงบนท่าเรือไม่มองหน้าฉัน ภารกิจสำเร็จ!", "Batırıcıların reisi öldü ve Wrack Burnu karanlık. Vergiler yerinde duruyor ve balıkçılar rıhtımda yüzüme bakmıyor. GÖREV TAMAMLANDI!", "El jefe de los raqueros ha muerto y la Punta Wrack está a oscuras. Los derechos siguen, y los pescadores no me miran en el muelle. ¡MISIÓN CUMPLIDA!", "O chefe dos saqueadores está morto e a Ponta Wrack, às escuras. As taxas continuam, e os pescadores não olham para mim no cais. MISSÃO CUMPRIDA!", "Главарь мародёров мёртв, мыс Рэк погрузился во тьму. Сборы остались, и рыбаки на причале не смотрят мне в глаза. ЗАДАНИЕ ВЫПОЛНЕНО!", "Ватажок мародерів мертвий, мис Рек поринув у темряву. Збори лишилися, і рибалки на причалі не дивляться мені в очі. ЗАВДАННЯ ВИКОНАНО!"],
  "The salt-panners of Saltreach and the King's Salt-House are not speaking, which in Raria is said very loudly.": ["ソルトリーチの塩田の者たちと王の塩館は口をきいていない。ラリアでは、それはとても大きな声で言われることだ。", "솔트리치의 염부들과 왕의 소금관은 말을 섞지 않는다. 라리아에서는 그 말을 아주 크게 한다.", "盐滩港的盐工和王家盐务所互不说话,这在拉瑞亚可是要大声宣告的。", "鹽灘港的鹽工和王家鹽務所互不說話,這在拉瑞亞可是要大聲宣告的。", "Những người làm muối ở Saltreach và Nhà Muối của Nhà Vua không nói chuyện với nhau, điều mà ở Raria được nói rất to.", "Para petani garam Saltreach dan Rumah Garam Raja tak saling bicara, yang di Raria diucapkan dengan sangat lantang.", "ชาวนาเกลือแห่งซอลต์รีชกับโรงเกลือหลวงไม่พูดกัน ซึ่งในราเรียพูดกันเสียงดังมาก", "Saltreach'in tuzcuları ile Kralın Tuz Evi konuşmuyor; Raria'da bu çok yüksek sesle söylenir.", "Los salineros de Saltreach y la Casa de la Sal del Rey no se hablan, cosa que en Raria se dice muy alto.", "Os salineiros de Saltreach e a Casa do Sal do Rei não se falam, o que em Raria se diz muito alto.", "Солевары Солтрича и Королевский Соляной дом не разговаривают, а в Рарии об этом говорят очень громко.", "Солевари Солтріча й Королівський Соляний дім не розмовляють, а в Рарії про це говорять дуже голосно."],
  "The Salt-House fines the panners because their sacks come in light; the panners say the King's scale is heavy. Mother Brannagh wants somebody to weigh it up who isn't in the Ledger.": ["塩館は袋が軽いといって塩田の者に罰金を科し、塩田の者は王の天秤が重いと言う。ブラナー母さんは、台帳に載っていない誰かに量りなおしてほしいと思っている。", "소금관은 자루가 가볍게 들어온다며 염부들에게 벌금을 물리고, 염부들은 왕의 저울이 무겁다고 한다. 브래나 어멈은 장부에 없는 누군가가 따져 봐 주기를 바란다.", "盐务所因为盐工的袋子分量不足而罚他们的款;盐工们却说国王的秤偏重。布兰娜大妈想找个不在册子上的人来掂量掂量。", "鹽務所因為鹽工的袋子分量不足而罰他們的款;鹽工們卻說國王的秤偏重。布蘭娜大媽想找個不在冊子上的人來掂量掂量。", "Nhà Muối phạt người làm muối vì bao của họ nhẹ cân; người làm muối nói cân của Nhà Vua bị nặng. Bà mẹ Brannagh muốn ai đó không có tên trong Sổ cân nhắc chuyện này.", "Rumah Garam mendenda petani garam karena karung mereka kurang berat; petani garam bilang timbangan Raja terlalu berat. Ibu Brannagh ingin seseorang yang tak tercatat di Buku menimbangnya.", "โรงเกลือปรับชาวนาเกลือเพราะกระสอบของพวกเขาน้ำหนักขาด ชาวนาเกลือว่าตาชั่งหลวงหนักเกิน แม่แบรนนาห์อยากให้ใครสักคนที่ไม่อยู่ในสมุดมาชั่งดู", "Tuz Evi tuzculara çuvalları hafif geldiği için ceza kesiyor; tuzcular Kral'ın terazisinin ağır olduğunu söylüyor. Brannagh Ana, Defter'de olmayan birinin bunu tartmasını istiyor.", "La Casa de la Sal multa a los salineros porque sus sacos llegan cortos de peso; los salineros dicen que la balanza del Rey pesa de más. La madre Brannagh quiere que lo sopese alguien que no esté en el Libro.", "A Casa do Sal multa os salineiros porque os sacos chegam leves; os salineiros dizem que a balança do Rei pesa a mais. A mãe Brannagh quer que alguém que não está no Livro pese a questão.", "Соляной дом штрафует солеваров за недовес мешков; солевары говорят, что королевские весы тяжелят. Матушка Браннах хочет, чтобы всё взвесил тот, кого нет в Книге.", "Соляний дім штрафує солеварів за недоважені мішки; солевари кажуть, що королівські терези важать більше. Матінка Браннах хоче, щоб усе зважив той, кого немає в Книзі."],
};
